CREATE OR REPLACE FUNCTION public.accept_quotation(p_token_hash text, p_acceptor_name text, p_acceptor_doc text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tok public.sales_quotation_tokens%ROWTYPE;
  v_doc public.sales_documents%ROWTYPE;
  v_wo public.work_orders%ROWTYPE;
  v_acc public.sales_quotation_acceptances%ROWTYPE;
  v_client_name text;
  v_items_snap jsonb;
  v_pol record;
  v_wf public.work_order_workflow_status;
  v_wo_created boolean := false;
  v_name text;
  v_exp timestamptz;
BEGIN
  -- Fail closed: hash malformado = enlace inválido, sin distinguir motivos.
  IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Enlace inválido.';
  END IF;
  v_name := btrim(COALESCE(p_acceptor_name, ''));
  IF char_length(v_name) < 2 OR char_length(v_name) > 200 THEN
    RAISE EXCEPTION 'Indicá tu nombre y apellido para aceptar.';
  END IF;

  -- Orden de bloqueo fijo token → documento: serializa aceptaciones
  -- concurrentes del mismo link en el lock del documento.
  SELECT * INTO v_tok FROM public.sales_quotation_tokens WHERE token_hash = p_token_hash FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Enlace inválido.'; END IF;
  IF v_tok.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'Este enlace fue revocado. Pedí un nuevo enlace a la empresa.'; END IF;

  SELECT * INTO v_doc FROM public.sales_documents WHERE id = v_tok.sales_document_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cotización no encontrada.'; END IF;
  -- Tenant isolation: el token solo puede resolver su propio documento.
  IF v_tok.empresa_id IS DISTINCT FROM v_doc.empresa_id THEN
    RAISE EXCEPTION 'Enlace inválido.';
  END IF;
  IF v_doc.doc_type IS DISTINCT FROM 'PROFORMA' THEN RAISE EXCEPTION 'Este documento no es una cotización.'; END IF;

  -- Idempotencia de lectura: ya aceptada → devolver lo existente.
  IF v_doc.acceptance_status = 'ACCEPTED' THEN
    SELECT * INTO v_wo FROM public.work_orders WHERE sales_document_id = v_doc.id;
    SELECT * INTO v_acc FROM public.sales_quotation_acceptances WHERE sales_document_id = v_doc.id;
    RETURN jsonb_build_object(
      'sales_document_id', v_doc.id,
      'work_order_id', CASE WHEN v_wo.id IS NULL THEN NULL ELSE v_wo.id END,
      'acceptance_id', CASE WHEN v_acc.id IS NULL THEN NULL ELSE v_acc.id END,
      'already_accepted', true);
  END IF;

  IF v_doc.acceptance_status = 'REJECTED' THEN
    RAISE EXCEPTION 'Esta cotización fue rechazada. Pedí a la empresa un nuevo ciclo de cotización.';
  END IF;
  IF v_doc.acceptance_status = 'DRAFT' THEN RAISE EXCEPTION 'Esta cotización todavía no está habilitada para aceptar.'; END IF;

  v_exp := LEAST(
    COALESCE(v_tok.expires_at, v_doc.acceptance_expires_at, now() + interval '1 second'),
    COALESCE(v_doc.acceptance_expires_at, v_tok.expires_at, now() + interval '1 second'));
  IF v_tok.expires_at IS NULL AND v_doc.acceptance_expires_at IS NULL THEN v_exp := NULL; END IF;
  IF v_exp IS NOT NULL AND now() > v_exp THEN
    IF v_doc.acceptance_status = 'PENDING_ACCEPTANCE' THEN
      UPDATE public.sales_documents SET acceptance_status = 'EXPIRED' WHERE id = v_doc.id;
      INSERT INTO public.sales_quotation_events
        (empresa_id, sales_document_id, token_id, event_type, actor_label, actor_ip, actor_user_agent, detail)
      VALUES (v_doc.empresa_id, v_doc.id, v_tok.id, 'EXPIRED', 'sistema', p_ip, p_user_agent,
        jsonb_build_object('reason', 'expired_on_accept_attempt'));
    END IF;
    RAISE EXCEPTION 'Esta cotización venció. Contactá a la empresa para pedir una nueva.';
  END IF;

  IF v_doc.acceptance_status = 'EXPIRED' THEN
    RAISE EXCEPTION 'Esta cotización venció. Contactá a la empresa para pedir una nueva.';
  END IF;
  IF v_doc.acceptance_status <> 'PENDING_ACCEPTANCE' THEN
    RAISE EXCEPTION 'Esta cotización no está pendiente de aceptación.';
  END IF;

  -- Versión congelada: el chequeo ocurre DENTRO de la transacción con el
  -- lock del documento ya tomado, así que una edición concurrente o bien
  -- commiteó antes (versión distinta → rechazo) o espera al lock y luego
  -- aborta en el guard de inmutabilidad. Sin ventana superseded.
  IF v_tok.quotation_version IS DISTINCT FROM v_doc.quotation_version THEN
    RAISE EXCEPTION 'La cotización fue actualizada por la empresa. Pedí el nuevo enlace antes de aceptar.';
  END IF;

  SELECT name INTO v_client_name FROM public.clients WHERE id = v_doc.client_id;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'description', description, 'quantity', quantity, 'unit_price', unit_price,
      'vat_rate', vat_rate, 'line_total', line_total) ORDER BY created_at), '[]'::jsonb)
    INTO v_items_snap
  FROM public.sales_document_items WHERE sales_document_id = v_doc.id;

  UPDATE public.sales_documents SET
    acceptance_status = 'ACCEPTED',
    accepted_at = now(),
    accepted_by_name = v_name,
    accepted_by_doc = NULLIF(btrim(COALESCE(p_acceptor_doc, '')), ''),
    rejection_reason = NULL,
    rejected_at = NULL
  WHERE id = v_doc.id;

  -- OT interna idempotente: UNIQUE(sales_document_id) + ON CONFLICT como
  -- backstop de concurrencia además de la serialización por locks.
  INSERT INTO public.work_orders
    (empresa_id, sales_document_id, client_id, currency, subtotal, vat_amount, total, status, notes)
  VALUES (
    v_doc.empresa_id, v_doc.id, v_doc.client_id, v_doc.currency,
    v_doc.subtotal, v_doc.vat_amount, v_doc.total, 'PENDIENTE',
    'Generada automáticamente por aceptación electrónica de ' || v_doc.code
      || ' v' || v_doc.quotation_version || ' por ' || v_name || '.'
      || CASE WHEN p_notes IS NOT NULL AND btrim(p_notes) <> '' THEN ' Comentario del cliente: ' || btrim(p_notes) ELSE '' END)
  ON CONFLICT (sales_document_id) DO NOTHING
  RETURNING * INTO v_wo;
  IF FOUND THEN
    v_wo_created := true;
    INSERT INTO public.work_order_items
      (empresa_id, work_order_id, description, quantity, unit_price, vat_rate, line_total)
    SELECT v_doc.empresa_id, v_wo.id, description, quantity, unit_price, vat_rate, line_total
    FROM public.sales_document_items WHERE sales_document_id = v_doc.id ORDER BY created_at;
  ELSE
    SELECT * INTO v_wo FROM public.work_orders WHERE sales_document_id = v_doc.id;
  END IF;

  -- Acceptance record explícito: UNIQUE(sales_document_id) garantiza una
  -- sola aceptación por cotización aunque dos requests corran en paralelo.
  INSERT INTO public.sales_quotation_acceptances (
    empresa_id, sales_document_id, quotation_version, client_id, client_name_snapshot,
    subtotal_snapshot, vat_snapshot, total_snapshot, currency_snapshot, channel,
    recipient_email, acceptor_name, acceptor_doc, acceptor_notes, ip, user_agent,
    token_id, token_prefix, items_snapshot, work_order_id
  ) VALUES (
    v_doc.empresa_id, v_doc.id, v_doc.quotation_version, v_doc.client_id,
    COALESCE(v_client_name, '—'),
    v_doc.subtotal, v_doc.vat_amount, v_doc.total, v_doc.currency, 'PORTAL',
    v_tok.prepared_for_email, v_name,
    NULLIF(btrim(COALESCE(p_acceptor_doc, '')), ''),
    NULLIF(btrim(COALESCE(p_notes, '')), ''),
    p_ip, p_user_agent, v_tok.id, v_tok.token_prefix, v_items_snap, v_wo.id)
  ON CONFLICT (sales_document_id) DO NOTHING
  RETURNING * INTO v_acc;
  IF NOT FOUND THEN
    SELECT * INTO v_acc FROM public.sales_quotation_acceptances WHERE sales_document_id = v_doc.id;
  END IF;

  -- Workflow interno resuelto por configuración (nunca hardcodea personas).
  SELECT * INTO v_pol FROM public.resolve_work_order_policy(v_doc.empresa_id, v_doc.client_id, NULL);
  v_wf := CASE WHEN v_pol.mode = 'RESPONSIBLE_APPROVAL'
    THEN 'PENDING_INTERNAL_APPROVAL'::public.work_order_workflow_status
    ELSE 'READY_FOR_PRODUCTION'::public.work_order_workflow_status END;
  UPDATE public.work_orders SET
    approval_mode = v_pol.mode,
    workflow_status = v_wf,
    responsible_role = v_pol.responsible_role,
    routing_policy_id = v_pol.policy_id
  WHERE id = v_wo.id;

  INSERT INTO public.sales_quotation_events
    (empresa_id, sales_document_id, token_id, event_type, actor_label, actor_ip, actor_user_agent, detail)
  VALUES
    (v_doc.empresa_id, v_doc.id, v_tok.id, 'ACCEPTED', v_name, p_ip, p_user_agent,
      jsonb_build_object('acceptance_id', v_acc.id, 'acceptor_doc', p_acceptor_doc,
        'quotation_version', v_doc.quotation_version)),
    (v_doc.empresa_id, v_doc.id, v_tok.id, 'WORK_ORDER_CREATED', 'sistema', NULL, NULL,
      jsonb_build_object('work_order_id', v_wo.id, 'work_order_code', v_wo.code,
        'acceptance_id', v_acc.id)),
    (v_doc.empresa_id, v_doc.id, v_tok.id, 'WORKFLOW_RESOLVED', 'sistema', NULL, NULL,
      jsonb_build_object('work_order_id', v_wo.id, 'mode', v_pol.mode,
        'workflow_status', v_wf, 'policy_scope', v_pol.scope,
        'responsible_role', v_pol.responsible_role));

  RETURN jsonb_build_object(
    'sales_document_id', v_doc.id,
    'work_order_id', v_wo.id,
    'acceptance_id', v_acc.id,
    'workflow_status', v_wf,
    'already_accepted', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.advance_sandbox_room(p_room_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_room      public.auction_sandbox_rooms%rowtype;
  v_now       timestamptz := clock_timestamp();
  v_seq       bigint;
  v_close     timestamptz;
  v_offset    double precision;
  v_winner_id uuid;
  v_winner_alias text;
  v_winner_price bigint;
begin
  select * into v_room
  from public.auction_sandbox_rooms
  where id = p_room_id
  for update;

  if not found then
    return jsonb_build_object('transitioned', false, 'reason', 'UNKNOWN_ROOM');
  end if;

  if v_room.status = 'DRAFT' or v_room.status = 'CLOSED' then
    return jsonb_build_object('transitioned', false, 'status', v_room.status);
  end if;

  -- NORMAL → RANDOM
  if v_room.status = 'ACTIVE_NORMAL' then
    if v_room.started_at is null
       or v_now < v_room.started_at + (v_room.normal_duration_seconds || ' seconds')::interval then
      return jsonb_build_object('transitioned', false, 'status', 'ACTIVE_NORMAL');
    end if;

    v_offset := v_room.random_min_seconds
                + random() * greatest(0, v_room.random_max_seconds - v_room.random_min_seconds);

    -- Una sola llamada gana el roll; las demás reusan el valor existente.
    insert into public.auction_sandbox_room_private (room_id, random_close_at, updated_at)
    values (p_room_id, v_now + make_interval(secs => v_offset), v_now)
    on conflict (room_id) do nothing;

    update public.auction_sandbox_rooms
    set status = 'ACTIVE_RANDOM',
        random_started_at = coalesce(random_started_at, v_now),
        next_sequence = next_sequence + 1
    where id = p_room_id
    returning next_sequence - 1 into v_seq;

    insert into public.auction_sandbox_events (room_id, type, payload, server_sequence)
    values (p_room_id, 'RANDOM_PHASE_STARTED',
            jsonb_build_object('at', v_now), v_seq);

    return jsonb_build_object('transitioned', true, 'status', 'ACTIVE_RANDOM');
  end if;

  -- ACTIVE_RANDOM → CLOSED
  select random_close_at into v_close
  from public.auction_sandbox_room_private where room_id = p_room_id;

  if v_close is null then
    -- Backstop: si el roll nunca ocurrió, generarlo ahora (una sola vez).
    v_offset := v_room.random_min_seconds
                + random() * greatest(0, v_room.random_max_seconds - v_room.random_min_seconds);
    insert into public.auction_sandbox_room_private (room_id, random_close_at, updated_at)
    values (p_room_id, v_now + make_interval(secs => v_offset), v_now)
    on conflict (room_id) do nothing
    returning random_close_at into v_close;
    if v_close is null then
      select random_close_at into v_close
      from public.auction_sandbox_room_private where room_id = p_room_id;
    end if;
    return jsonb_build_object('transitioned', false, 'status', 'ACTIVE_RANDOM');
  end if;

  if v_now < v_close then
    -- closeRisk se deriva en app desde random_started_at + min (público).
    return jsonb_build_object('transitioned', false, 'status', 'ACTIVE_RANDOM');
  end if;

  -- Ganador: mejor precio; empate entre participantes: menor secuencia.
  select b.participant_id, b.price_pyg, p.display_alias
    into v_winner_id, v_winner_price, v_winner_alias
  from public.auction_sandbox_bids b
  join public.auction_sandbox_participants p on p.id = b.participant_id
  where b.room_id = p_room_id and b.accepted
  order by b.price_pyg asc, b.server_sequence asc
  limit 1;

  update public.auction_sandbox_rooms
  set status = 'CLOSED',
      closed_at = v_now,
      winner_participant_id = v_winner_id,
      next_sequence = next_sequence + 2
  where id = p_room_id
  returning next_sequence - 2 into v_seq;

  insert into public.auction_sandbox_events (room_id, type, payload, server_sequence)
  values
    (p_room_id, 'AUCTION_CLOSED',
     jsonb_build_object('at', v_now, 'total_bids',
       (select count(*) from public.auction_sandbox_bids where room_id = p_room_id and accepted)),
     v_seq),
    (p_room_id, 'WINNER_DECLARED',
     case when v_winner_id is null
       then jsonb_build_object('participant_id', null)
       else jsonb_build_object('participant_id', v_winner_id, 'alias', v_winner_alias, 'price_pyg', v_winner_price)
     end,
     v_seq + 1);

  return jsonb_build_object('transitioned', true, 'status', 'CLOSED',
                            'winner_participant_id', v_winner_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.append_sandbox_event(p_room_id uuid, p_type text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_seq bigint;
begin
  select next_sequence into v_seq
  from public.auction_sandbox_rooms
  where id = p_room_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'UNKNOWN_ROOM');
  end if;

  update public.auction_sandbox_rooms
  set next_sequence = next_sequence + 1
  where id = p_room_id;

  insert into public.auction_sandbox_events (room_id, type, payload, server_sequence)
  values (p_room_id, p_type, coalesce(p_payload, '{}'::jsonb), v_seq);

  return jsonb_build_object('ok', true, 'sequence', v_seq);
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_subcontractor_certificate_atomically(p_empresa_id uuid, p_certificate_id uuid, p_approved_pct numeric, p_approved_amount numeric, p_notes text, p_actor_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_contract_id uuid;
  v_project_id uuid;
  v_status text;
  v_existing_pct numeric;
  v_existing_amount numeric;
  v_existing_notes text;
  v_contracted_amount numeric;
  v_other_approved numeric;
BEGIN
  IF auth.uid() IS NULL
     OR p_actor_id IS DISTINCT FROM auth.uid()
     OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
     OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Acceso denegado para aprobar certificado de subcontratista';
  END IF;
  IF p_approved_pct IS NULL OR p_approved_pct <= 0 OR p_approved_pct > 100
     OR p_approved_amount IS NULL OR p_approved_amount <= 0 THEN
    RAISE EXCEPTION 'El porcentaje y el monto aprobados deben ser válidos';
  END IF;

  SELECT sc.contract_id, sc.project_id, sc.status, sc.approved_pct, sc.approved_amount, sc.notes
    INTO v_contract_id, v_project_id, v_status, v_existing_pct, v_existing_amount, v_existing_notes
  FROM public.subcontractor_certificates sc
  JOIN public.projects p ON p.id = sc.project_id AND p.empresa_id = p_empresa_id
  WHERE sc.id = p_certificate_id
  FOR UPDATE OF sc;
  IF NOT FOUND THEN RAISE EXCEPTION 'Certificado no encontrado para la empresa'; END IF;

  SELECT c.contracted_amount INTO v_contracted_amount
  FROM public.subcontractor_contracts c
  WHERE c.id = v_contract_id AND c.project_id = v_project_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Contrato no encontrado para el proyecto'; END IF;

  IF v_status = 'APROBADO'
     AND v_existing_pct IS NOT DISTINCT FROM p_approved_pct
     AND v_existing_amount IS NOT DISTINCT FROM p_approved_amount
     AND v_existing_notes IS NOT DISTINCT FROM p_notes THEN
    RETURN p_certificate_id;
  END IF;
  IF v_status <> 'PENDIENTE' THEN
    RAISE EXCEPTION 'Solo se puede aprobar un certificado pendiente';
  END IF;

  SELECT coalesce(sum(sc.approved_amount), 0) INTO v_other_approved
  FROM public.subcontractor_certificates sc
  WHERE sc.contract_id = v_contract_id AND sc.id <> p_certificate_id
    AND sc.status IN ('APROBADO','PAGADO');
  IF v_other_approved + p_approved_amount > v_contracted_amount THEN
    RAISE EXCEPTION 'La aprobación supera el monto contratado';
  END IF;

  UPDATE public.subcontractor_certificates sc
  SET status = 'APROBADO', approved_pct = p_approved_pct,
      approved_amount = p_approved_amount, notes = p_notes
  WHERE sc.id = p_certificate_id AND sc.project_id = v_project_id AND sc.status = 'PENDIENTE';
  IF NOT FOUND THEN RAISE EXCEPTION 'El certificado cambió durante la aprobación'; END IF;
  RETURN p_certificate_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_mrp_actor(p_empresa_id uuid, p_actor_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role public.user_role;
BEGIN
  PERFORM 1 FROM public.empresas WHERE id = p_empresa_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Empresa no encontrada';
  END IF;

  SELECT role INTO v_role FROM public.profiles
    WHERE id = p_actor_id AND empresa_id = p_empresa_id;
  IF NOT FOUND OR v_role IS NULL THEN
    RAISE EXCEPTION 'Actor sin perfil en la empresa (tenant fail-closed)';
  END IF;
  IF v_role NOT IN ('administracion', 'admin') THEN
    RAISE EXCEPTION 'Actor sin rol requerido para MRP';
  END IF;

  RETURN p_empresa_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.bump_quotation_version_on_item_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_doc uuid;
BEGIN
  v_doc := COALESCE(NEW.sales_document_id, OLD.sales_document_id);
  UPDATE public.sales_documents
    SET quotation_version = COALESCE(quotation_version, 1) + 1
    WHERE id = v_doc AND doc_type = 'PROFORMA'
      AND acceptance_status IN ('DRAFT', 'PENDING_ACCEPTANCE');
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.calcular_dv_ruc_py(p_ruc text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_base text;
  v_total int := 0;
  v_k int := 2;
  v_i int;
  v_char char;
  v_digit int;
  v_resto int;
begin
  v_base := public.normalizar_ruc(p_ruc);
  if v_base is null or length(v_base) = 0 then
    return null;
  end if;

  for v_i in reverse length(v_base)..1 loop
    v_char := substr(v_base, v_i, 1);
    if v_char between '0' and '9' then
      v_digit := ascii(v_char) - 48;
    else
      v_digit := ascii(upper(v_char));
    end if;
    v_total := v_total + (v_digit * v_k);
    v_k := v_k + 1;
    if v_k > 11 then
      v_k := 2;
    end if;
  end loop;

  v_resto := v_total % 11;
  if v_resto > 1 then
    return (11 - v_resto)::text;
  else
    return '0';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.can_read_warehouse_evidence(p_object_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_empresa_id uuid;
  v_context_id uuid;
  v_location_id uuid;
BEGIN
  IF (SELECT auth.uid()) IS NULL
     OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
    RETURN false;
  END IF;
  v_empresa_id := public.current_empresa_id();
  IF v_empresa_id IS NULL OR p_object_name IS NULL THEN
    RETURN false;
  END IF;

  IF p_object_name ~ '^receipts/[0-9A-Fa-f-]{36}/[^/]+$' THEN
    BEGIN
      v_context_id := split_part(p_object_name, '/', 2)::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RETURN false;
    END;
    RETURN EXISTS (
      SELECT 1
      FROM public.inventory_receipt_evidence e
      JOIN public.oc_recepciones r ON r.id = e.receipt_id
      WHERE e.empresa_id = v_empresa_id
        AND r.empresa_id = v_empresa_id
        AND e.receipt_id = v_context_id
        AND e.storage_bucket = 'warehouse-evidence'
        AND e.storage_path = p_object_name
        AND split_part(p_object_name, '/', 2) = e.receipt_id::text
    );
  END IF;

  IF p_object_name ~ '^[0-9A-Fa-f-]{36}/[0-9A-Fa-f-]{36}/[^/]+$' THEN
    BEGIN
      v_location_id := split_part(p_object_name, '/', 1)::uuid;
      v_context_id := split_part(p_object_name, '/', 2)::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RETURN false;
    END;
    RETURN EXISTS (
      SELECT 1
      FROM public.warehouse_submission_evidence e
      JOIN public.warehouse_submissions s ON s.id = e.submission_id
      JOIN public.inventory_locations l ON l.id = s.location_id
      WHERE e.empresa_id = v_empresa_id
        AND s.empresa_id = v_empresa_id
        AND l.empresa_id = v_empresa_id
        AND e.submission_id = v_context_id
        AND s.location_id = v_location_id
        AND e.storage_bucket = 'warehouse-evidence'
        AND e.storage_path = p_object_name
        AND split_part(p_object_name, '/', 1) = s.location_id::text
        AND split_part(p_object_name, '/', 2) = e.submission_id::text
    );
  END IF;

  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_email_approval_for_draft(p_draft_id uuid, p_empresa_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer;
begin
  if p_empresa_id is distinct from public.current_empresa_id() then
    raise exception 'tenant mismatch';
  end if;
  update public.agent_approvals
  set status = 'CANCELLED', decided_by = auth.uid(), decided_at = now()
  where empresa_id = p_empresa_id
    and tool_name = 'send_email'
    and status = 'REQUESTED'
    and payload_json ->> 'draft_id' = p_draft_id::text;
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.check_invoice_delete_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF old.status = 'PAGADO' THEN
    RAISE EXCEPTION 'No se puede eliminar la factura % porque ya fue pagada (integridad contable)', old.invoice_number;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.payment_order_invoices poi
    JOIN public.payment_orders po ON po.id = poi.payment_order_id
    WHERE poi.invoice_id = old.id AND po.status = 'EJECUTADA'
  ) THEN
    RAISE EXCEPTION 'No se puede eliminar la factura % porque pertenece a una orden de pago ejecutada', old.invoice_number;
  END IF;

  RETURN old;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_email_send(p_empresa_id uuid, p_user_id uuid, p_draft_id uuid, p_connection_id uuid, p_approval_id uuid, p_approved_revision bigint, p_approved_content_hash text, p_delivery_fingerprint text, p_allow_delivery_unknown_retry boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_connection public.email_connections%rowtype;
  v_draft public.email_drafts%rowtype;
  v_approval public.agent_approvals%rowtype;
  v_attempt_id uuid := gen_random_uuid();
  v_client_message_id text := '<' || v_attempt_id::text || '@dominio-control-facturas>';
  v_unknown_created_at timestamptz;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required for email send claim';
  end if;
  if p_empresa_id is null or p_user_id is null or p_draft_id is null
     or p_connection_id is null or p_approval_id is null then
    raise exception 'email send claim identity is incomplete';
  end if;
  if p_approved_revision is null or p_approved_content_hash is null
     or p_delivery_fingerprint is null then
    raise exception 'email send claim binding is incomplete';
  end if;

  select * into v_connection
  from public.email_connections c
  where c.id = p_connection_id
    and c.empresa_id = p_empresa_id
    and c.user_id = p_user_id
    and c.provider = 'GMAIL'
  for update;
  if not found or v_connection.status <> 'CONNECTED' then
    raise exception 'email connection is not CONNECTED at send linearization point';
  end if;

  select * into v_draft
  from public.email_drafts d
  where d.id = p_draft_id
    and d.empresa_id = p_empresa_id
    and d.created_by = p_user_id
  for update;
  if not found then
    raise exception 'email draft does not belong to the requested actor';
  end if;
  if v_draft.status <> 'WAITING_APPROVAL' then
    raise exception 'email draft is not waiting for approval';
  end if;
  if v_draft.provider_connection_id is distinct from p_connection_id then
    raise exception 'email draft connection changed after approval';
  end if;
  if v_draft.revision is distinct from p_approved_revision
     or v_draft.content_hash is distinct from p_approved_content_hash then
    raise exception 'email draft revision or content hash changed after approval';
  end if;

  select * into v_approval
  from public.agent_approvals a
  where a.id = p_approval_id
    and a.empresa_id = p_empresa_id
    and a.tool_name = 'send_email'
  for update;
  if not found or v_approval.status not in ('APPROVED', 'EXECUTING') then
    raise exception 'email approval is not valid or has already been consumed';
  end if;
  if v_approval.approved_revision is distinct from p_approved_revision
     or v_approval.approved_content_hash is distinct from p_approved_content_hash
     or v_approval.payload_json ->> 'draft_id' is distinct from p_draft_id::text
     or v_approval.payload_json ->> 'draft_hash' is distinct from p_approved_content_hash
     or (v_approval.payload_json ->> 'draft_revision')::bigint is distinct from p_approved_revision then
    raise exception 'email approval snapshot does not match the send claim';
  end if;

  select max(a.created_at) into v_unknown_created_at
  from public.email_send_attempts a
  where a.empresa_id = p_empresa_id
    and a.delivery_fingerprint = p_delivery_fingerprint
    and a.status = 'DELIVERY_UNKNOWN';
  if v_unknown_created_at is not null
     and (not p_allow_delivery_unknown_retry or v_approval.created_at <= v_unknown_created_at) then
    raise exception 'delivery outcome is unknown; explicit resend with a new approval is required';
  end if;

  insert into public.email_send_attempts (
    id, empresa_id, draft_id, connection_id, approval_id,
    approved_revision, content_hash, delivery_fingerprint,
    client_message_id, status
  ) values (
    v_attempt_id, p_empresa_id, p_draft_id, p_connection_id, p_approval_id,
    p_approved_revision, p_approved_content_hash, p_delivery_fingerprint,
    v_client_message_id, 'CLAIMED'
  );

  update public.email_drafts
  set status = 'SENDING', failure_reason = null
  where id = p_draft_id;

  return jsonb_build_object(
    'attempt_id', v_attempt_id,
    'client_message_id', v_client_message_id,
    'status', 'CLAIMED',
    'approved_revision', p_approved_revision,
    'content_hash', p_approved_content_hash
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.commit_production_plan_atomic(p_empresa_id uuid, p_actor_id uuid, p_plan_id uuid, p_project_id uuid, p_start_date date, p_end_date date, p_status text, p_notes text, p_items jsonb, p_weather_snapshot_batch_id uuid, p_location_id uuid, p_reserve_items jsonb, p_needed_by date, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_empresa_id UUID := public.assert_mrp_actor(p_empresa_id, p_actor_id);
  v_saved JSONB;
  v_new_plan_id UUID;
BEGIN
  IF p_status NOT IN ('DRAFT', 'COMMITTED', 'CLOSED') THEN
    RAISE EXCEPTION 'status inválido para commit MRP: %', p_status;
  END IF;

  PERFORM 1 FROM public.projects
    WHERE id = p_project_id AND empresa_id = v_empresa_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Proyecto no encontrado o sin permisos';
  END IF;

  IF p_location_id IS NOT NULL THEN
    PERFORM 1 FROM public.inventory_locations
      WHERE id = p_location_id AND empresa_id = v_empresa_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Depósito no encontrado o sin permisos';
    END IF;
  END IF;

  -- Contexto JWT para el anidado legacy (save_weekly_plan_atomic usa
  -- current_empresa_id(); el actor ya fue validado arriba).
  PERFORM set_config('request.jwt.claim.sub', p_actor_id::text, true);

  -- 1) Plan + targets (misma RPC certificada).
  SELECT public.save_weekly_plan_atomic(
    p_plan_id, p_project_id, p_start_date, p_end_date,
    p_status, p_notes, p_items, p_weather_snapshot_batch_id
  ) INTO v_saved;
  v_new_plan_id := (v_saved ->> 'plan_id')::uuid;
  IF v_new_plan_id IS NULL THEN
    RAISE EXCEPTION 'No se pudo persistir el plan semanal';
  END IF;

  -- 2) Lifecycle de reservas EN LA MISMA transacción.
  -- Orden: primero liberar lo retenido (si el save falla después, el
  -- ROLLBACK lo restaura: rollback total probado en tests).
  IF p_plan_id IS NOT NULL THEN
    UPDATE public.inventory_reservations
      SET status = 'RELEASED', released_at = now()
      WHERE weekly_plan_id = p_plan_id
        AND status = 'ACTIVE'
        AND empresa_id = v_empresa_id;
  END IF;

  IF p_status = 'COMMITTED' AND p_location_id IS NOT NULL THEN
    -- Reemplazo atómico: reserva las nuevas (o falla todo).
    PERFORM public.reserve_plan_stock(
      v_empresa_id, p_actor_id, p_project_id, v_new_plan_id, p_location_id,
      COALESCE(p_reserve_items, '[]'::jsonb),
      p_needed_by, p_idempotency_key || ':' || v_new_plan_id::text, true
    );
  END IF;

  RETURN jsonb_build_object('plan_id', v_new_plan_id, 'status', 'SUCCESS');
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_email_send_attempt(p_send_attempt_id uuid, p_empresa_id uuid, p_user_id uuid, p_provider_message_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_attempt public.email_send_attempts%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required for email attempt transition';
  end if;
  select a.* into v_attempt
  from public.email_send_attempts a
  join public.email_drafts d on d.id = a.draft_id
  where a.id = p_send_attempt_id and a.empresa_id = p_empresa_id
    and d.created_by = p_user_id
  for update;
  if not found or v_attempt.status <> 'DISPATCHING' then
    raise exception 'email send attempt is not dispatching';
  end if;
  update public.email_send_attempts
  set status = 'SENT', provider_message_id = p_provider_message_id,
      provider_accepted_at = coalesce(provider_accepted_at, now()), completed_at = now()
  where id = p_send_attempt_id;
  update public.email_drafts
  set status = 'SENT', provider_message_id = p_provider_message_id,
      sent_at = now(), failure_reason = null
  where id = v_attempt.draft_id and status = 'SENDING';
  return jsonb_build_object('attempt_id', p_send_attempt_id, 'status', 'SENT',
    'provider_message_id', p_provider_message_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.convertir_licitacion_a_proyecto_atomico(p_empresa_id uuid, p_name text, p_code text, p_client text, p_comitente text, p_contract_number text, p_contract_amount numeric, p_budget_total numeric, p_plazo_dias integer, p_anticipo_pct numeric, p_retencion_pct numeric, p_start_date date, p_end_date date, p_tender_id text, p_bid_analysis_run_id uuid, p_created_by uuid, p_budget_items jsonb, p_nombre_deposito text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_current_empresa UUID;
  v_project_id UUID;
  v_existing_code TEXT;
  v_existing_tender_id TEXT;
  v_existing_deposito_proj UUID;
  v_item JSONB;
  v_sort_order INT := 1;
  v_lic_decision TEXT;
  v_lic_empresa UUID;
  v_lic_proj UUID;
  v_lic_db_id UUID;
  v_lic_proc_id UUID;
  v_run_empresa UUID;
  v_item_qty NUMERIC;
  v_item_price NUMERIC;
  v_item_desc TEXT;
  v_item_unit TEXT;
  v_calculated_budget_total NUMERIC(18,2) := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Acceso denegado: se requiere sesión autenticada';
  END IF;

  v_current_empresa := public.current_empresa_id();
  IF v_current_empresa IS NULL OR v_current_empresa IS DISTINCT FROM p_empresa_id THEN
    RAISE EXCEPTION 'Acceso denegado: el usuario autenticado no pertenece a la empresa especificada (%)', p_empresa_id;
  END IF;

  IF p_budget_items IS NULL OR jsonb_array_length(p_budget_items) = 0 THEN
    RAISE EXCEPTION 'No se puede convertir licitacion a proyecto sin items de presupuesto';
  END IF;

  IF p_tender_id IS NOT NULL AND trim(p_tender_id) <> '' THEN
    SELECT id, empresa_id, decision, project_id, process_id
    INTO v_lic_db_id, v_lic_empresa, v_lic_decision, v_lic_proj, v_lic_proc_id
    FROM public.licitaciones
    WHERE (id::TEXT = p_tender_id OR dncp_nro = p_tender_id)
      AND empresa_id = p_empresa_id;

    IF v_lic_empresa IS NULL THEN
      RAISE EXCEPTION 'Licitación % no encontrada para la empresa %', p_tender_id, p_empresa_id;
    END IF;

    IF COALESCE(v_lic_decision, '') <> 'GANADA' THEN
      RAISE EXCEPTION 'Integridad contractual violada: la licitación % no tiene decisión GANADA (estado actual: %)', p_tender_id, COALESCE(v_lic_decision, 'SIN_DECISION');
    END IF;

    IF v_lic_proj IS NOT NULL THEN
      SELECT id, code INTO v_project_id, v_existing_code
      FROM public.projects
      WHERE id = v_lic_proj AND empresa_id = p_empresa_id;

      IF v_project_id IS NOT NULL THEN
        RETURN jsonb_build_object(
          'success', true,
          'already_existed', true,
          'project_id', v_project_id,
          'project_code', v_existing_code
        );
      END IF;
    END IF;
  END IF;

  IF p_bid_analysis_run_id IS NOT NULL THEN
    SELECT empresa_id INTO v_run_empresa
    FROM public.bid_analysis_runs
    WHERE id = p_bid_analysis_run_id;

    IF v_run_empresa IS NULL OR v_run_empresa <> p_empresa_id THEN
      RAISE EXCEPTION 'La corrida de análisis % no pertenece a la empresa %', p_bid_analysis_run_id, p_empresa_id;
    END IF;
  END IF;

  SELECT id, code, tender_id INTO v_project_id, v_existing_code, v_existing_tender_id
  FROM public.projects
  WHERE empresa_id = p_empresa_id AND code = p_code;

  IF v_project_id IS NOT NULL THEN
    IF v_existing_tender_id IS NOT NULL AND p_tender_id IS NOT NULL AND v_existing_tender_id <> p_tender_id THEN
      RAISE EXCEPTION 'Conflicto de integridad: ya existe un proyecto con código % asignado a otra licitación (%)', p_code, v_existing_tender_id;
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'already_existed', true,
      'project_id', v_project_id,
      'project_code', v_existing_code
    );
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_budget_items)
  LOOP
    v_item_desc := trim(COALESCE(v_item->>'description', ''));
    v_item_unit := trim(COALESCE(v_item->>'unit', ''));
    v_item_qty := (v_item->>'quantity')::NUMERIC;
    v_item_price := (v_item->>'unit_price')::NUMERIC;

    IF v_item_desc = '' THEN
      RAISE EXCEPTION 'Ítem de presupuesto inválido: descripción no puede ser vacía';
    END IF;

    IF v_item_unit = '' THEN
      RAISE EXCEPTION 'Ítem de presupuesto % sin unidad de medida verificable', v_item_desc;
    END IF;

    IF v_item_qty IS NULL OR v_item_qty <= 0 THEN
      RAISE EXCEPTION 'Ítem de presupuesto % tiene cantidad no válida (%)', v_item_desc, v_item_qty;
    END IF;

    IF v_item_price IS NULL OR v_item_price <= 0 THEN
      RAISE EXCEPTION 'Ítem de presupuesto % tiene precio unitario no válido (%)', v_item_desc, v_item_price;
    END IF;

    v_calculated_budget_total := v_calculated_budget_total + ROUND(v_item_qty * v_item_price, 2);
  END LOOP;

  INSERT INTO public.projects (
    empresa_id, name, code, client, comitente, contract_number, contract_amount,
    budget_total, plazo_dias, anticipo_pct, retencion_pct, start_date, end_date,
    status, tender_id, bid_analysis_run_id, created_by
  ) VALUES (
    p_empresa_id, p_name, p_code, p_client, p_comitente, p_contract_number, p_contract_amount,
    COALESCE(p_budget_total, v_calculated_budget_total), p_plazo_dias, p_anticipo_pct,
    p_retencion_pct, p_start_date, p_end_date, 'ACTIVO', p_tender_id, p_bid_analysis_run_id, p_created_by
  )
  RETURNING id INTO v_project_id;

  v_sort_order := 1;
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_budget_items)
  LOOP
    v_item_qty := (v_item->>'quantity')::NUMERIC;
    v_item_price := (v_item->>'unit_price')::NUMERIC;

    INSERT INTO public.budget_items (
      project_id, code, description, unit, quantity, unit_price, sort_order
    ) VALUES (
      v_project_id,
      COALESCE(v_item->>'code', 'ITM-' || LPAD(v_sort_order::TEXT, 3, '0')),
      trim(v_item->>'description'),
      trim(v_item->>'unit'),
      v_item_qty,
      v_item_price,
      COALESCE((v_item->>'sort_order')::INT, v_sort_order)
    );
    v_sort_order := v_sort_order + 1;
  END LOOP;

  IF p_nombre_deposito IS NOT NULL AND trim(p_nombre_deposito) <> '' THEN
    SELECT id INTO v_existing_deposito_proj
    FROM public.depositos
    WHERE empresa_id = p_empresa_id AND project_id = v_project_id
    LIMIT 1;

    IF v_existing_deposito_proj IS NULL THEN
      INSERT INTO public.depositos (empresa_id, nombre, es_principal, project_id, activo)
      VALUES (p_empresa_id, p_nombre_deposito, false, v_project_id, true);
    END IF;
  END IF;

  IF p_tender_id IS NOT NULL AND trim(p_tender_id) <> '' THEN
    UPDATE public.licitaciones
    SET
      project_id = v_project_id,
      raw_json = jsonb_set(
        COALESCE(raw_json, '{}'::JSONB),
        '{obra_vinculada}',
        jsonb_build_object(
          'project_id', v_project_id,
          'project_code', p_code,
          'converted_at', timezone('utc'::TEXT, now())
        )
      ),
      updated_at = timezone('utc'::TEXT, now())
    WHERE (id::TEXT = p_tender_id OR dncp_nro = p_tender_id)
      AND empresa_id = p_empresa_id;

    IF v_lic_proc_id IS NOT NULL THEN
      UPDATE public.empresa_licitacion_seguimiento
      SET project_id = v_project_id, updated_at = now()
      WHERE empresa_id = p_empresa_id AND process_id = v_lic_proc_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'already_existed', false,
    'project_id', v_project_id,
    'project_code', p_code
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.crear_cuenta_financiera_atomica(p_empresa_id uuid, p_nombre text, p_tipo text, p_banco text, p_numero_cuenta text, p_moneda currency_code, p_saldo_inicial numeric, p_created_by uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_cuenta_id uuid;
  v_opening numeric := coalesce(p_saldo_inicial, 0);
BEGIN
  IF auth.uid() IS NULL
     OR p_created_by IS DISTINCT FROM auth.uid()
     OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
     OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Acceso denegado para crear cuenta financiera';
  END IF;
  IF pg_catalog.btrim(coalesce(p_nombre, '')) = '' OR p_tipo NOT IN ('BANCO','CAJA','TARJETA','OTRO')
     OR p_moneda IS NULL THEN
    RAISE EXCEPTION 'Datos de cuenta financiera inválidos';
  END IF;

  INSERT INTO public.cuentas_financieras (
    empresa_id, nombre, tipo, banco, numero_cuenta, moneda, created_by
  ) VALUES (
    p_empresa_id, pg_catalog.btrim(p_nombre), p_tipo,
    nullif(pg_catalog.btrim(p_banco), ''), nullif(pg_catalog.btrim(p_numero_cuenta), ''),
    p_moneda, p_created_by
  ) RETURNING id INTO v_cuenta_id;

  IF v_opening <> 0 THEN
    INSERT INTO public.movimientos_tesoreria (
      empresa_id, cuenta_id, fecha, monto, tipo, motivo, created_by
    ) VALUES (
      p_empresa_id, v_cuenta_id, CURRENT_DATE, v_opening,
      'SALDO_INICIAL', 'Saldo inicial de la cuenta', p_created_by
    );
  END IF;
  RETURN v_cuenta_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_receipt_portal_link(p_empresa_id uuid, p_order_id uuid, p_location_id uuid, p_token_hash text, p_token_hint text, p_expires_at timestamp with time zone, p_created_by uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order public.authorized_orders%ROWTYPE;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Acceso denegado';
  END IF;

  SELECT * INTO v_order
  FROM public.authorized_orders
  WHERE id = p_order_id AND empresa_id = p_empresa_id
  FOR UPDATE;
  IF NOT FOUND OR v_order.project_id IS NULL THEN
    RAISE EXCEPTION 'OC de obra no encontrada';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.inventory_locations
    WHERE id = p_location_id AND empresa_id = p_empresa_id
      AND project_id = v_order.project_id AND location_type = 'PROJECT' AND active
  ) THEN
    RAISE EXCEPTION 'La ubicación de obra no es válida';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.authorized_order_items
    WHERE order_id = p_order_id AND empresa_id = p_empresa_id
  ) THEN
    INSERT INTO public.authorized_order_items (
      order_id, empresa_id, product, quantity, unit, unit_price, total_price, sort_order
    ) VALUES (
      v_order.id, v_order.empresa_id, v_order.product, v_order.quantity,
      v_order.unit, v_order.unit_price, greatest(v_order.total_price, 0.01), 0
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.authorized_order_items oi
    WHERE oi.order_id = p_order_id AND oi.empresa_id = p_empresa_id
      AND oi.quantity > coalesce((
        SELECT sum(ri.cantidad_recibida)
        FROM public.oc_recepcion_items ri
        JOIN public.oc_recepciones r ON r.id = ri.recepcion_id
        WHERE ri.order_item_id = oi.id AND ri.empresa_id = p_empresa_id
          AND r.order_id = p_order_id AND r.empresa_id = p_empresa_id
          AND r.status IN ('DRAFT', 'CONFIRMED')
      ), 0)
  ) THEN
    RAISE EXCEPTION 'La OC no tiene cantidades pendientes para recibir';
  END IF;

  UPDATE public.receipt_portal_links
  SET active = false
  WHERE empresa_id = p_empresa_id AND order_id = p_order_id AND active;

  INSERT INTO public.receipt_portal_links (
    empresa_id, order_id, location_id, token_hash, token_hint, expires_at, created_by
  ) VALUES (
    p_empresa_id, p_order_id, p_location_id, p_token_hash, p_token_hint,
    p_expires_at, p_created_by
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.ejecutar_orden_pago_atomica(p_empresa_id uuid, p_op_id uuid, p_cuenta_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_op public.payment_orders;
  v_account_currency public.currency_code;
  v_invoice_currency public.currency_code;
  v_invoice_count integer;
  v_link_count integer;
  v_total numeric;
  v_locked_id uuid;
BEGIN
  IF auth.uid() IS NULL
     OR p_created_by IS DISTINCT FROM auth.uid()
     OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
     OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Acceso denegado para ejecutar orden de pago';
  END IF;

  SELECT * INTO v_op FROM public.payment_orders po
  WHERE po.id = p_op_id AND po.empresa_id = p_empresa_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Orden de pago no encontrada'; END IF;
  IF v_op.status <> 'EMITIDA' THEN
    RAISE EXCEPTION 'La orden de pago ya fue ejecutada o anulada';
  END IF;

  SELECT count(*) INTO v_link_count FROM public.payment_order_invoices poi
  WHERE poi.payment_order_id = p_op_id AND poi.empresa_id = p_empresa_id;
  IF v_link_count = 0 THEN RAISE EXCEPTION 'La orden de pago no tiene facturas vinculadas'; END IF;

  -- Stable lock ordering prevents invoice/payment races and deadlocks.
  FOR v_locked_id IN
    SELECT i.id
    FROM public.payment_order_invoices poi
    JOIN public.invoices i ON i.id = poi.invoice_id
    WHERE poi.payment_order_id = p_op_id AND poi.empresa_id = p_empresa_id
    ORDER BY i.id
    FOR UPDATE OF i
  LOOP
    NULL;
  END LOOP;

  SELECT count(*), coalesce(sum(i.total), 0)
    INTO v_invoice_count, v_total
  FROM public.payment_order_invoices poi
  JOIN public.invoices i ON i.id = poi.invoice_id
  WHERE poi.payment_order_id = p_op_id AND poi.empresa_id = p_empresa_id
    AND i.empresa_id = p_empresa_id AND i.provider_id = v_op.provider_id
    AND i.status <> 'PAGADO';
  IF v_invoice_count <> v_link_count THEN
    RAISE EXCEPTION 'La OP contiene facturas ajenas, pagadas, anuladas o de otro proveedor';
  END IF;

  SELECT i.currency INTO v_invoice_currency
  FROM public.payment_order_invoices poi
  JOIN public.invoices i ON i.id = poi.invoice_id
  WHERE poi.payment_order_id = p_op_id AND poi.empresa_id = p_empresa_id
  ORDER BY i.id LIMIT 1;
  IF EXISTS (
    SELECT 1 FROM public.payment_order_invoices poi
    JOIN public.invoices i ON i.id = poi.invoice_id
    WHERE poi.payment_order_id = p_op_id AND poi.empresa_id = p_empresa_id
      AND i.currency IS DISTINCT FROM v_invoice_currency
  ) THEN
    RAISE EXCEPTION 'Una OP no puede agrupar facturas de monedas distintas';
  END IF;

  IF p_cuenta_id IS NOT NULL THEN
    SELECT c.moneda INTO v_account_currency
    FROM public.cuentas_financieras c
    WHERE c.id = p_cuenta_id AND c.empresa_id = p_empresa_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Cuenta financiera no encontrada para la empresa'; END IF;
    IF EXISTS (
      SELECT 1 FROM public.payment_order_invoices poi
      JOIN public.invoices i ON i.id = poi.invoice_id
      WHERE poi.payment_order_id = p_op_id AND poi.empresa_id = p_empresa_id
        AND (i.empresa_id IS DISTINCT FROM p_empresa_id
          OR i.currency IS DISTINCT FROM v_account_currency)
    ) THEN
      RAISE EXCEPTION 'La moneda de la cuenta no coincide con todas las facturas de la OP';
    END IF;
  END IF;

  UPDATE public.payment_orders po
  SET status = 'EJECUTADA', executed_at = pg_catalog.now(), cuenta_id = p_cuenta_id
  WHERE po.id = p_op_id AND po.empresa_id = p_empresa_id AND po.status = 'EMITIDA';
  IF NOT FOUND THEN RAISE EXCEPTION 'La OP cambió de estado durante la ejecución'; END IF;

  UPDATE public.invoices i
  SET status = 'PAGADO', updated_at = pg_catalog.now()
  WHERE i.id IN (
    SELECT poi.invoice_id FROM public.payment_order_invoices poi
    WHERE poi.payment_order_id = p_op_id AND poi.empresa_id = p_empresa_id
  ) AND i.empresa_id = p_empresa_id;

  IF p_cuenta_id IS NOT NULL AND v_total > 0 THEN
    PERFORM public.registrar_movimiento_tesoreria(
      p_empresa_id := p_empresa_id,
      p_cuenta_id := p_cuenta_id,
      p_monto := -v_total,
      p_tipo := 'PAGO',
      p_fecha := CURRENT_DATE,
      p_motivo := 'Pago OP ' || v_op.code,
      p_payment_order_id := p_op_id,
      p_created_by := p_created_by,
      p_permitir_negativo := true
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.email_connect_gmail(p_empresa_id uuid, p_user_id uuid, p_provider_email text, p_scopes text[], p_refresh_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'vault', 'pg_temp'
AS $function$
declare
  v_connection_id uuid;
  v_secret_id uuid;
begin
  if p_empresa_id is null or p_user_id is null or nullif(btrim(p_refresh_token), '') is null then
    raise exception 'OAuth connection payload is incomplete';
  end if;
  if nullif(btrim(p_provider_email), '') is null then
    raise exception 'OAuth provider email is required';
  end if;
  if not exists (
    select 1
    from public.profiles p
    where p.id = p_user_id and p.empresa_id = p_empresa_id
  ) then
    raise exception 'OAuth user is not a member of the empresa';
  end if;
  if exists (
    select 1
    from public.email_connections c
    where c.empresa_id = p_empresa_id
      and c.user_id = p_user_id
      and c.provider = 'GMAIL'
      and c.status in ('CONNECTED', 'REVOKE_PENDING', 'DISCONNECT_FAILED')
  ) then
    raise exception 'An existing Gmail connection must be disconnected before reconnecting';
  end if;

  delete from vault.secrets
  where id in (
    select c.refresh_token_secret_id
    from public.email_connections c
    where c.empresa_id = p_empresa_id
      and c.user_id = p_user_id
      and c.provider = 'GMAIL'
      and c.status = 'ERROR'
      and c.refresh_token_secret_id is not null
  );
  update public.email_connections
  set status = 'REVOKED', disconnected_at = now(), refresh_token_secret_id = null
  where empresa_id = p_empresa_id
    and user_id = p_user_id
    and provider = 'GMAIL'
    and status = 'ERROR';

  v_secret_id := vault.create_secret(
    btrim(p_refresh_token),
    'gmail-refresh-token:' || p_user_id::text || ':' || gen_random_uuid()::text,
    'Rodrigo Gmail OAuth refresh token'
  );
  insert into public.email_connections (
    empresa_id, user_id, provider, provider_email, status, scopes, refresh_token_secret_id
  ) values (
    p_empresa_id, p_user_id, 'GMAIL', nullif(btrim(p_provider_email), ''), 'CONNECTED', coalesce(p_scopes, '{}'::text[]), v_secret_id
  )
  returning id into v_connection_id;
  return v_connection_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.email_connect_gmail(p_provider_email text, p_scopes text[], p_refresh_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
declare
  v_connection_id uuid;
  v_secret_id uuid;
begin
  if auth.uid() is null or public.current_empresa_id() is null then
    raise exception 'authenticated tenant required';
  end if;
  if p_refresh_token is null or btrim(p_refresh_token) = '' then
    raise exception 'refresh token required';
  end if;
  if p_provider_email is null or btrim(p_provider_email) = '' then
    raise exception 'provider email required';
  end if;
  select vault.create_secret(
    p_refresh_token,
    'gmail-refresh-token:' || auth.uid()::text || ':' || gen_random_uuid()::text,
    'Rodrigo Gmail OAuth refresh token'
  ) into v_secret_id;
  delete from vault.secrets
  where id in (
    select refresh_token_secret_id
    from public.email_connections
    where empresa_id = public.current_empresa_id()
      and user_id = auth.uid()
      and provider = 'GMAIL'
      and status in ('CONNECTED', 'ERROR')
      and refresh_token_secret_id is not null
  );
  update public.email_connections
  set status = 'REVOKED', disconnected_at = now(), refresh_token_secret_id = null
  where empresa_id = public.current_empresa_id()
    and user_id = auth.uid()
    and provider = 'GMAIL'
    and status in ('CONNECTED', 'ERROR');
  insert into public.email_connections (
    empresa_id, user_id, provider, provider_email, status, scopes, refresh_token_secret_id
  ) values (
    public.current_empresa_id(), auth.uid(), 'GMAIL', btrim(p_provider_email), 'CONNECTED',
    coalesce(p_scopes, '{}'::text[]), v_secret_id
  ) returning id into v_connection_id;
  return v_connection_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.email_delete_oauth_secret(p_secret_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
begin
  if auth.uid() is null or not exists (
    select 1 from public.email_connections c
    where c.refresh_token_secret_id = p_secret_id
      and c.empresa_id = public.current_empresa_id()
      and c.user_id = auth.uid()
  ) then
    raise exception 'secret does not belong to current user and tenant';
  end if;
  delete from vault.secrets where id = p_secret_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_inventory_company_pro_plan()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_plan text;
BEGIN
  IF auth.role() = 'service_role' OR v_actor IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT e.plan INTO v_plan
  FROM public.empresas e
  WHERE e.id = NEW.empresa_id;
  IF v_plan IS NULL OR v_plan NOT IN ('pro', 'caterpillar') THEN
    RAISE EXCEPTION 'Los movimientos canónicos de inventario requieren plan Pro';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_manual_inventory_movement_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_reason text;
  v_actor uuid := auth.uid();
BEGIN
  IF NEW.movement_type = 'ADJUSTMENT' THEN
    v_reason := nullif(pg_catalog.btrim(NEW.metadata->>'reason'), '');
    IF v_reason IS NULL OR pg_catalog.char_length(v_reason) > 500 THEN
      RAISE EXCEPTION 'Los ajustes de inventario requieren un motivo de hasta 500 caracteres';
    END IF;
    NEW.metadata := pg_catalog.jsonb_set(
      coalesce(NEW.metadata, '{}'::jsonb),
      '{reason}',
      pg_catalog.to_jsonb(v_reason),
      true
    );
  END IF;

  IF v_actor IS NOT NULL
     AND NEW.movement_type IN ('TRANSFER', 'RETURN', 'ADJUSTMENT')
     AND NEW.source_type <> 'MANUAL' THEN
    RAISE EXCEPTION 'Los movimientos humanos deben registrarse con origen MANUAL';
  END IF;

  IF NEW.source_type = 'MANUAL'
     AND NEW.movement_type IN ('TRANSFER', 'RETURN', 'ADJUSTMENT') THEN
    IF NEW.source_id IS NULL OR NEW.source_line_id IS NOT NULL
       OR NEW.idempotency_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'Un movimiento manual necesita una clave UUID estable como origen';
    END IF;
    IF NEW.source_id IS DISTINCT FROM NEW.idempotency_key::uuid THEN
      RAISE EXCEPTION 'El origen manual debe coincidir con la clave de idempotencia';
    END IF;
    IF v_actor IS NOT NULL AND NEW.created_by IS DISTINCT FROM v_actor THEN
      RAISE EXCEPTION 'El creador del movimiento manual debe ser el usuario autenticado';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.evaluar_estado_documento_boveda(p_fecha_vencimiento date, p_es_vencible boolean, p_dias_alerta integer DEFAULT 30)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
    IF NOT p_es_vencible OR p_fecha_vencimiento IS NULL THEN
        RETURN 'VIGENTE';
    END IF;

    IF p_fecha_vencimiento < CURRENT_DATE THEN
        RETURN 'VENCIDO';
    ELSIF p_fecha_vencimiento <= (CURRENT_DATE + p_dias_alerta) THEN
        RETURN 'POR_VENCER';
    ELSE
        RETURN 'VIGENTE';
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.extraer_dv_ruc(p_ruc text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_clean TEXT;
BEGIN
  IF p_ruc IS NULL OR trim(p_ruc) = '' THEN
    RETURN NULL;
  END IF;
  v_clean := regexp_replace(trim(p_ruc), '\s+', '', 'g');
  v_clean := regexp_replace(v_clean, '^(PY-)?RUC-', '', 'i');
  IF position('-' IN v_clean) > 0 THEN
    RETURN split_part(v_clean, '-', 2);
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fail_email_send_attempt(p_send_attempt_id uuid, p_empresa_id uuid, p_user_id uuid, p_error_code text, p_failure_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_attempt public.email_send_attempts%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required for email attempt transition';
  end if;
  select a.* into v_attempt
  from public.email_send_attempts a
  join public.email_drafts d on d.id = a.draft_id
  where a.id = p_send_attempt_id and a.empresa_id = p_empresa_id
    and d.created_by = p_user_id
  for update;
  if not found or v_attempt.status not in ('CLAIMED', 'DISPATCHING') then
    raise exception 'email send attempt cannot be failed safely';
  end if;
  update public.email_send_attempts
  set status = 'FAILED_SAFE', error_code = p_error_code, completed_at = now()
  where id = p_send_attempt_id;
  update public.email_drafts
  set status = 'FAILED', failure_reason = p_failure_reason
  where id = v_attempt.draft_id and status = 'SENDING';
  return jsonb_build_object('attempt_id', p_send_attempt_id, 'status', 'FAILED_SAFE');
end;
$function$

CREATE OR REPLACE FUNCTION public.force_close_sandbox_room(p_room_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_room      public.auction_sandbox_rooms%rowtype;
  v_now       timestamptz := clock_timestamp();
  v_seq       bigint;
  v_winner_id uuid;
  v_winner_alias text;
  v_winner_price bigint;
begin
  select * into v_room
  from public.auction_sandbox_rooms
  where id = p_room_id
  for update;

  if not found then
    return jsonb_build_object('closed', false, 'reason', 'UNKNOWN_ROOM');
  end if;

  if v_room.status = 'CLOSED' then
    return jsonb_build_object('closed', true, 'already', true);
  end if;

  select b.participant_id, b.price_pyg, p.display_alias
    into v_winner_id, v_winner_price, v_winner_alias
  from public.auction_sandbox_bids b
  join public.auction_sandbox_participants p on p.id = b.participant_id
  where b.room_id = p_room_id and b.accepted
  order by b.price_pyg asc, b.server_sequence asc
  limit 1;

  update public.auction_sandbox_rooms
  set status = 'CLOSED',
      closed_at = v_now,
      winner_participant_id = v_winner_id,
      next_sequence = next_sequence + 2
  where id = p_room_id
  returning next_sequence - 2 into v_seq;

  insert into public.auction_sandbox_events (room_id, type, payload, server_sequence)
  values
    (p_room_id, 'AUCTION_CLOSED',
     jsonb_build_object('at', v_now, 'manual', true, 'total_bids',
       (select count(*) from public.auction_sandbox_bids where room_id = p_room_id and accepted)),
     v_seq),
    (p_room_id, 'WINNER_DECLARED',
     case when v_winner_id is null
       then jsonb_build_object('participant_id', null)
       else jsonb_build_object('participant_id', v_winner_id, 'alias', v_winner_alias, 'price_pyg', v_winner_price)
     end,
     v_seq + 1);

  return jsonb_build_object('closed', true, 'winner_participant_id', v_winner_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_competitor_contextual_fingerprint(p_supplier_id uuid, p_comitente text DEFAULT NULL::text, p_categoria text DEFAULT NULL::text, p_monto numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_bracket text;
  v_rec record;
  v_result jsonb;
begin
  v_bracket := public.categorizar_tamano_contrato(p_monto);

  -- Nivel 1: Match Exacto (Empresa × Convocante × Rubro × Tamaño)
  if p_comitente is not null and p_categoria is not null and p_monto is not null then
    select * into v_rec
    from public.v_procurement_competitor_contextual
    where supplier_id = p_supplier_id
      and comitente_nombre ilike ('%' || p_comitente || '%')
      and categoria ilike ('%' || p_categoria || '%')
      and size_bracket = v_bracket
      and certainty_tier in ('ALTA', 'MEDIA');

    if found then
      return jsonb_build_object(
        'level', 'EXACT_CONTEXT',
        'supplier_id', v_rec.supplier_id,
        'win_rate_pct', v_rec.win_rate_pct,
        'avg_discount_pct', v_rec.avg_discount_pct,
        'stddev_discount_pct', v_rec.stddev_discount_pct,
        'sample_size', v_rec.sample_size_with_price,
        'certainty_tier', v_rec.certainty_tier,
        'fallback_applied', false
      );
    end if;
  end if;

  -- Nivel 2: Fallback Rubro + Tamaño (Empresa × Rubro × Tamaño)
  if p_categoria is not null then
    select
      round(avg(win_rate_pct), 1) as win_rate_pct,
      round(avg(avg_discount_pct), 2) as avg_discount_pct,
      sum(sample_size_with_price) as sample_size,
      count(*) as entries_count
    into v_rec
    from public.v_procurement_competitor_contextual
    where supplier_id = p_supplier_id
      and categoria ilike ('%' || p_categoria || '%');

    if found and v_rec.sample_size >= 2 then
      return jsonb_build_object(
        'level', 'FALLBACK_CATEGORY',
        'supplier_id', p_supplier_id,
        'win_rate_pct', coalesce(v_rec.win_rate_pct, 0),
        'avg_discount_pct', coalesce(v_rec.avg_discount_pct, 0),
        'sample_size', v_rec.sample_size,
        'certainty_tier', case when v_rec.sample_size >= 10 then 'MEDIA' else 'BAJA' end,
        'fallback_applied', true
      );
    end if;
  end if;

  -- Nivel 3: Fallback Global de la Empresa
  select * into v_rec
  from public.v_procurement_competitor_global
  where supplier_id = p_supplier_id;

  if found then
    return jsonb_build_object(
      'level', 'FALLBACK_GLOBAL',
      'supplier_id', p_supplier_id,
      'win_rate_pct', v_rec.global_win_rate_pct,
      'avg_discount_pct', coalesce(v_rec.global_avg_discount_pct, 0),
      'sample_size', v_rec.total_bids,
      'certainty_tier', v_rec.certainty_tier,
      'fallback_applied', true
    );
  end if;

  return jsonb_build_object(
    'level', 'UNKNOWN',
    'supplier_id', p_supplier_id,
    'win_rate_pct', 0,
    'avg_discount_pct', 0,
    'sample_size', 0,
    'certainty_tier', 'INSUFICIENTE',
    'fallback_applied', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_accepted_quotation_items()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_status public.quotation_acceptance_status;
DECLARE v_doc uuid;
BEGIN
  v_doc := COALESCE(NEW.sales_document_id, OLD.sales_document_id);
  SELECT acceptance_status INTO v_status
  FROM public.sales_documents WHERE id = v_doc AND doc_type = 'PROFORMA';
  IF v_status = 'ACCEPTED' THEN
    RAISE EXCEPTION 'Ítems de cotización aceptada son inmutables (doc %).', v_doc;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_certificate_workbook_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_certificate_id uuid := coalesce(NEW.certificate_id, OLD.certificate_id);
  v_status text;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.certificate_id IS DISTINCT FROM NEW.certificate_id THEN
    RAISE EXCEPTION 'La planilla no puede moverse a otro certificado';
  END IF;

  SELECT c.status::text INTO v_status
  FROM public.project_certificates c
  WHERE c.id = v_certificate_id
  FOR UPDATE;
  IF NOT FOUND AND TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  IF TG_OP = 'UPDATE' AND (NOT FOUND OR v_status IS DISTINCT FROM 'BORRADOR') THEN
    RAISE EXCEPTION 'Solo se puede editar la planilla de un certificado en borrador';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_email_attachment_send_barrier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_draft_id uuid := coalesce(new.draft_id, old.draft_id);
  v_status text;
begin
  select d.status into v_status
  from public.email_drafts d
  where d.id = v_draft_id
  for update;

  if v_status = 'SENDING' then
    raise exception 'email draft attachments are locked by an in-flight send attempt';
  end if;

  update public.email_drafts
  set revision = revision + 1,
      delivery_retry_authorized = false
  where id = v_draft_id;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_email_draft_send_barrier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_role text := coalesce(current_setting('request.jwt.claim.role', true), '');
begin
  if old.status = 'SENDING' and v_role = 'authenticated' then
    raise exception 'email draft is locked by an in-flight send attempt';
  end if;

  if old.status = 'SENDING'
     and new.status not in ('SENDING', 'SENT', 'FAILED', 'DELIVERY_UNKNOWN') then
    raise exception 'email draft cannot leave SENDING through this transition';
  end if;

  if old.to_json is distinct from new.to_json
     or old.cc_json is distinct from new.cc_json
     or old.bcc_json is distinct from new.bcc_json
     or old.subject is distinct from new.subject
     or old.body_text is distinct from new.body_text
     or old.body_html is distinct from new.body_html
     or old.content_hash is distinct from new.content_hash
     or old.provider_connection_id is distinct from new.provider_connection_id then
    new.revision := old.revision + 1;
    new.delivery_retry_authorized := false;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_project_certificate_create()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_project_id uuid;
  v_latest_num integer;
  v_latest_status text;
BEGIN
  IF auth.uid() IS NULL
     OR NOT public.is_internal_role(ARRAY['administracion', 'admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Solo administración puede crear certificados';
  END IF;

  SELECT p.id INTO v_project_id
  FROM public.projects p
  WHERE p.id = NEW.project_id
    AND p.empresa_id = public.current_empresa_id()
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Proyecto no encontrado para la empresa';
  END IF;
  IF NEW.status IS DISTINCT FROM 'BORRADOR' THEN
    RAISE EXCEPTION 'Un certificado nuevo debe comenzar en borrador';
  END IF;

  -- Imported certificates represent autonomous contractual documents which
  -- may not be consecutive (e.g. Cert #6 without 1-5).
  IF NEW.import_fingerprint IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT c.numero, c.status::text
    INTO v_latest_num, v_latest_status
  FROM public.project_certificates c
  WHERE c.project_id = NEW.project_id
  ORDER BY c.numero DESC
  LIMIT 1;

  IF v_latest_num IS NOT NULL AND v_latest_status NOT IN ('APROBADO', 'FACTURADO') THEN
    RAISE EXCEPTION 'El certificado anterior debe estar aprobado antes de crear otro';
  END IF;
  IF NEW.numero IS DISTINCT FROM coalesce(v_latest_num, 0) + 1 THEN
    RAISE EXCEPTION 'El número del certificado cambió; actualizá la pantalla e intentá de nuevo';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_project_certificate_header_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.id IS DISTINCT FROM NEW.id OR OLD.project_id IS DISTINCT FROM NEW.project_id OR OLD.numero IS DISTINCT FROM NEW.numero THEN
    RAISE EXCEPTION 'La identidad, el proyecto y el número del certificado son inmutables';
  END IF;
  IF OLD.status = 'BORRADOR' AND NEW.status = 'ELABORADO' THEN
    IF (pg_catalog.to_jsonb(NEW) - ARRAY['status','elaborado_por','elaborado_at','closed_at','devolucion_anticipo_pct_snap','retencion_pct_snap','devolucion_anticipo','retencion','monto_liquido','monto_acumulado','updated_at'])
       IS DISTINCT FROM
       (pg_catalog.to_jsonb(OLD) - ARRAY['status','elaborado_por','elaborado_at','closed_at','devolucion_anticipo_pct_snap','retencion_pct_snap','devolucion_anticipo','retencion','monto_liquido','monto_acumulado','updated_at']) THEN
      RAISE EXCEPTION 'La transición de certificado no puede modificar otros datos';
    END IF;
  ELSIF OLD.status = 'ELABORADO' AND NEW.status = 'VERIFICADO' THEN
    IF (pg_catalog.to_jsonb(NEW) - ARRAY['status','verificado_por','verificado_at','monto_liquido','monto_acumulado','updated_at'])
       IS DISTINCT FROM (pg_catalog.to_jsonb(OLD) - ARRAY['status','verificado_por','verificado_at','monto_liquido','monto_acumulado','updated_at']) THEN
      RAISE EXCEPTION 'La transición de certificado no puede modificar otros datos';
    END IF;
  ELSIF OLD.status = 'VERIFICADO' AND NEW.status = 'APROBADO' THEN
    IF (pg_catalog.to_jsonb(NEW) - ARRAY['status','aprobado_por','aprobado_at','monto_liquido','monto_acumulado','updated_at'])
       IS DISTINCT FROM (pg_catalog.to_jsonb(OLD) - ARRAY['status','aprobado_por','aprobado_at','monto_liquido','monto_acumulado','updated_at']) THEN
      RAISE EXCEPTION 'La transición de certificado no puede modificar otros datos';
    END IF;
  END IF;
  IF OLD.status NOT IN ('APROBADO', 'FACTURADO') THEN RETURN NEW; END IF;
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
    IF (pg_catalog.to_jsonb(NEW) - ARRAY['updated_at','monto_liquido','monto_acumulado']) IS DISTINCT FROM (pg_catalog.to_jsonb(OLD) - ARRAY['updated_at','monto_liquido','monto_acumulado']) THEN
      RAISE EXCEPTION 'La cabecera de un certificado aprobado o facturado es inmutable';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.status = 'APROBADO' AND NEW.status = 'FACTURADO' THEN
    IF NEW.factura_numero IS NULL OR pg_catalog.btrim(NEW.factura_numero) = '' OR NEW.facturado_at IS NULL THEN
      RAISE EXCEPTION 'Un certificado facturado requiere número y fecha de factura';
    END IF;
    IF (pg_catalog.to_jsonb(NEW) - ARRAY['status','factura_numero','facturado_at','monto_liquido','monto_acumulado','updated_at'])
       IS DISTINCT FROM (pg_catalog.to_jsonb(OLD) - ARRAY['status','factura_numero','facturado_at','monto_liquido','monto_acumulado','updated_at']) THEN
      RAISE EXCEPTION 'La facturación no puede modificar otros datos del certificado';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.status = 'APROBADO' AND NEW.status = 'VERIFICADO' THEN
    IF (pg_catalog.to_jsonb(NEW) - ARRAY['status','aprobado_por','aprobado_at','monto_liquido','monto_acumulado','updated_at'])
       IS DISTINCT FROM (pg_catalog.to_jsonb(OLD) - ARRAY['status','aprobado_por','aprobado_at','monto_liquido','monto_acumulado','updated_at']) THEN
      RAISE EXCEPTION 'La reversa de aprobación no puede modificar otros datos del certificado';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.status = 'FACTURADO' AND NEW.status = 'APROBADO' THEN
    IF (pg_catalog.to_jsonb(NEW) - ARRAY['status','factura_numero','facturado_at','monto_liquido','monto_acumulado','updated_at'])
       IS DISTINCT FROM (pg_catalog.to_jsonb(OLD) - ARRAY['status','factura_numero','facturado_at','monto_liquido','monto_acumulado','updated_at']) THEN
      RAISE EXCEPTION 'La reversa de facturación no puede modificar otros datos del certificado';
    END IF;
    RETURN NEW;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_project_certificate_line_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_certificate_id uuid;
  v_status text;
BEGIN
  IF TG_OP = 'DELETE' THEN v_certificate_id := OLD.certificate_id; ELSE v_certificate_id := NEW.certificate_id; END IF;
  IF TG_OP = 'UPDATE' AND OLD.certificate_id IS DISTINCT FROM NEW.certificate_id THEN
    RAISE EXCEPTION 'No se puede mover una línea entre certificados';
  END IF;
  SELECT c.status::text INTO v_status FROM public.project_certificates c WHERE c.id = v_certificate_id FOR UPDATE;
  IF NOT FOUND AND TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  IF NOT FOUND OR v_status IS DISTINCT FROM 'BORRADOR' THEN
    RAISE EXCEPTION 'Solo se pueden modificar líneas de un certificado en borrador';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_project_certificate_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
  IF (OLD.status = 'BORRADOR' AND NEW.status = 'ELABORADO')
     OR (OLD.status = 'ELABORADO' AND NEW.status = 'VERIFICADO')
     OR (OLD.status = 'VERIFICADO' AND NEW.status = 'APROBADO')
     OR (OLD.status = 'APROBADO' AND NEW.status = 'FACTURADO') THEN
    RETURN NEW;
  END IF;
  DELETE FROM private.project_certificate_transition_authorizations a
  WHERE a.transaction_id = pg_catalog.txid_current() AND a.certificate_id = OLD.id AND a.user_id = auth.uid()
    AND a.from_status = OLD.status::text AND a.to_status = NEW.status::text;
  IF FOUND THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'La regresión de estado del certificado requiere la acción administrativa autorizada';
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_subcontractor_certificate_project_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_contract_project uuid;
  v_project_empresa uuid;
BEGIN
  SELECT c.project_id INTO v_contract_project
  FROM public.subcontractor_contracts c WHERE c.id = NEW.contract_id;
  IF NOT FOUND OR v_contract_project IS DISTINCT FROM NEW.project_id THEN
    RAISE EXCEPTION 'El certificado debe pertenecer al proyecto de su contrato';
  END IF;
  SELECT p.empresa_id INTO v_project_empresa
  FROM public.projects p WHERE p.id = NEW.project_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Proyecto del certificado no encontrado'; END IF;
  IF auth.uid() IS NOT NULL AND v_project_empresa IS DISTINCT FROM public.current_empresa_id() THEN
    RAISE EXCEPTION 'El certificado pertenece a otra empresa';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_subcontractor_contract_project_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_project_empresa uuid;
  v_subcontractor_empresa uuid;
  v_budget_project uuid;
BEGIN
  SELECT p.empresa_id INTO v_project_empresa
  FROM public.projects p WHERE p.id = NEW.project_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Proyecto del contrato no encontrado'; END IF;
  SELECT s.empresa_id INTO v_subcontractor_empresa
  FROM public.subcontractors s WHERE s.id = NEW.subcontractor_id;
  IF NOT FOUND OR v_subcontractor_empresa IS DISTINCT FROM v_project_empresa THEN
    RAISE EXCEPTION 'El subcontratista no pertenece a la empresa del proyecto';
  END IF;
  IF NEW.budget_item_id IS NOT NULL THEN
    SELECT b.project_id INTO v_budget_project
    FROM public.budget_items b WHERE b.id = NEW.budget_item_id;
    IF NOT FOUND OR v_budget_project IS DISTINCT FROM NEW.project_id THEN
      RAISE EXCEPTION 'La partida presupuestaria no pertenece al proyecto del contrato';
    END IF;
  END IF;
  IF auth.uid() IS NOT NULL AND v_project_empresa IS DISTINCT FROM public.current_empresa_id() THEN
    RAISE EXCEPTION 'El proyecto del contrato pertenece a otra empresa';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_workbook_import_session_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.status IN ('CONFIRMED', 'DISCARDED') AND (
       NEW.working_snapshot IS DISTINCT FROM OLD.working_snapshot
       OR NEW.original_storage_path IS DISTINCT FROM OLD.original_storage_path
       OR NEW.status IS DISTINCT FROM OLD.status) THEN
    RAISE EXCEPTION 'La sesión de importación ya fue cerrada';
  END IF;
  IF OLD.empresa_id IS DISTINCT FROM NEW.empresa_id THEN
    RAISE EXCEPTION 'La sesión no puede cambiar de empresa';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.import_project_certificate_atomically(p_project_id uuid, p_expected_number integer, p_period_start date, p_period_end date, p_import_fingerprint text, p_items jsonb)
 RETURNS TABLE(certificate_id uuid, numero integer, already_imported boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_project_id uuid;
  v_certificate_id uuid;
  v_item_count integer;
  v_inserted_count integer;
  v_existing_number integer;
  v_monto_anterior numeric(18,2);
  v_monto_presente numeric(18,2);
BEGIN
  IF v_user_id IS NULL
     OR NOT public.is_internal_role(ARRAY['administracion', 'admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Solo administración puede importar certificados';
  END IF;
  IF p_import_fingerprint IS NULL OR p_import_fingerprint !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'La huella del archivo no es válida';
  END IF;
  IF p_period_start IS NULL OR p_period_end IS NULL OR p_period_end < p_period_start THEN
    RAISE EXCEPTION 'El período del certificado es inválido';
  END IF;
  IF p_expected_number IS NULL OR p_expected_number <= 0 THEN
    RAISE EXCEPTION 'El número de certificado es inválido';
  END IF;
  IF p_items IS NULL OR pg_catalog.jsonb_typeof(p_items) IS DISTINCT FROM 'array'
     OR pg_catalog.jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'El certificado no contiene partidas';
  END IF;

  SELECT p.id INTO v_project_id
  FROM public.projects p
  WHERE p.id = p_project_id
    AND p.empresa_id = public.current_empresa_id();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Obra no encontrada para la empresa';
  END IF;

  -- Same file/project retries return the original draft; the unique index
  -- closes the race between concurrent first attempts.
  SELECT c.id, c.numero INTO v_certificate_id, v_existing_number
  FROM public.project_certificates c
  WHERE c.project_id = v_project_id AND c.import_fingerprint = p_import_fingerprint;
  IF FOUND THEN
    RETURN QUERY SELECT v_certificate_id, v_existing_number, true;
    RETURN;
  END IF;

  SELECT pg_catalog.jsonb_array_length(p_items) INTO v_item_count;

  -- Ensure each non-null budget_item_id is linked at most once
  IF EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_to_recordset(p_items) AS line(budget_item_id uuid)
    WHERE line.budget_item_id IS NOT NULL
    GROUP BY line.budget_item_id
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'Cada partida del presupuesto puede vincularse una sola vez';
  END IF;

  -- Validate that if a budget_item_id is specified, it exists and belongs to this project;
  -- and validate that numeric fields are non-negative.
  IF EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_to_recordset(p_items) AS line(
      budget_item_id uuid,
      qty_contractual numeric,
      qty_anterior numeric,
      qty_presente numeric,
      precio_unitario numeric
    )
    LEFT JOIN public.budget_items bi
      ON bi.id = line.budget_item_id AND bi.project_id = v_project_id
    WHERE (line.budget_item_id IS NOT NULL AND bi.id IS NULL)
       OR line.qty_contractual IS NULL OR line.qty_contractual < 0
       OR line.qty_anterior IS NULL OR line.qty_anterior < 0
       OR line.qty_presente IS NULL OR line.qty_presente < 0
       OR line.precio_unitario IS NULL OR line.precio_unitario < 0
  ) THEN
    RAISE EXCEPTION 'Hay partidas inválidas o vinculadas a otra obra';
  END IF;

  BEGIN
    INSERT INTO public.project_certificates (
      project_id, numero, period_start, period_end, status, created_by, import_fingerprint
    ) VALUES (
      v_project_id, p_expected_number, p_period_start, p_period_end,
      'BORRADOR', v_user_id, p_import_fingerprint
    ) RETURNING id INTO v_certificate_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT c.id, c.numero INTO v_certificate_id, v_existing_number
    FROM public.project_certificates c
    WHERE c.project_id = v_project_id AND c.import_fingerprint = p_import_fingerprint;
    IF FOUND THEN
      RETURN QUERY SELECT v_certificate_id, v_existing_number, true;
      RETURN;
    END IF;
    RAISE;
  END;

  INSERT INTO public.project_certificate_items (
    certificate_id, budget_item_id, codigo, descripcion, unidad,
    qty_contractual, precio_unitario, qty_anterior, qty_presente, sort_order
  )
  SELECT
    v_certificate_id, line.budget_item_id, line.codigo, line.descripcion, line.unidad,
    line.qty_contractual, line.precio_unitario, line.qty_anterior, line.qty_presente, line.sort_order
  FROM pg_catalog.jsonb_to_recordset(p_items) AS line(
    budget_item_id uuid,
    codigo text,
    descripcion text,
    unidad text,
    qty_contractual numeric,
    precio_unitario numeric,
    qty_anterior numeric,
    qty_presente numeric,
    sort_order integer
  );
  GET DIAGNOSTICS v_inserted_count = ROW_COUNT;
  IF v_inserted_count <> v_item_count THEN
    RAISE EXCEPTION 'No se pudieron crear todas las partidas del certificado';
  END IF;

  SELECT coalesce(sum(i.monto_anterior), 0), coalesce(sum(i.monto_presente), 0)
    INTO v_monto_anterior, v_monto_presente
  FROM public.project_certificate_items i
  WHERE i.certificate_id = v_certificate_id;
  UPDATE public.project_certificates
  SET monto_anterior = v_monto_anterior,
      monto_presente = v_monto_presente
  WHERE id = v_certificate_id;

  RETURN QUERY SELECT v_certificate_id, p_expected_number, false;
END;
$function$

CREATE OR REPLACE FUNCTION public.ingestar_proceso_ocds_global(p_cr jsonb, p_fuente text DEFAULT 'DNCP_OCDS'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_cr JSONB;
  v_releases JSONB := '[]'::JSONB;
  v_releases_metadata JSONB := '[]'::JSONB;
  v_tender JSONB;
  v_planning JSONB;
  v_ocid TEXT;
  v_dncp_nro TEXT;
  v_titulo TEXT;
  v_buyer_name TEXT;
  v_buyer_id TEXT;
  v_entity_id UUID;
  v_process_id UUID;
  v_sha TEXT;
  v_estado TEXT;
  v_estado_anterior TEXT;
  v_monto_ref NUMERIC(18,2);
  v_monto_disp NUMERIC(18,2);
  v_moneda TEXT;
  v_item JSONB;
  v_lot JSONB;
  v_lot_id UUID;
  v_lot_num INTEGER;
  v_parsed_order INTEGER;
  v_final_sort_order INTEGER;
  v_party JSONB;
  v_award JSONB;
  v_award_db_id UUID;
  v_award_dncp_id TEXT;
  v_contract JSONB;
  v_amendment JSONB;
  v_doc JSONB;
  v_ruc_clean TEXT;
  v_supplier_id UUID;
  v_award_supplier_ids UUID[];
  v_contract_supplier_ids UUID[];
  v_supplier_name TEXT;
  v_supplier_scale TEXT;
  v_contract_db_id UUID;
  v_orig_contract_id UUID;
  v_contract_dncp_id TEXT;
  v_extends_contract_id TEXT;
  v_monto_contrato_orig NUMERIC(18,2);
  v_contract_moneda TEXT;
  v_contract_award_id UUID;
  v_contract_supplier_id UUID;
  v_fecha_inicio TIMESTAMPTZ;
  v_fecha_fin TIMESTAMPTZ;
  v_duracion_dias_orig INTEGER;
  v_amendment_dncp_id TEXT;
  v_amendment_fingerprint TEXT;
  v_amendment_desc TEXT;
  v_amendment_delta NUMERIC(18,2);
  v_amendment_moneda TEXT;
  v_duracion_delta INTEGER;
  v_amendment_tipo TEXT;
  v_dncp_raw_type TEXT;
  v_item_sort_order INTEGER := 1;
  v_doc_key TEXT;
  
  -- Variables de reconciliación de adendas independientes
  v_amend_count INTEGER;
  v_amend_total_delta NUMERIC(18,2);
  v_amend_dur_delta INTEGER;
  v_has_unres_amt BOOLEAN;
  v_has_unres_dur BOOLEAN;
  v_any_amount_amend BOOLEAN;
  v_any_dur_amend BOOLEAN;
  r_amend RECORD;
BEGIN
  -- 10. PRESERVAR HISTORIAL DE RELEASES Y COMPILED_RELEASE
  -- Compatibilidad Canónica P0: p_cr permanece como parámetro con nombre.
  -- Si p_cr contiene compiledRelease, normalizar internamente y preservar el paquete completo en raw_json.
  -- Si p_cr es bare compiledRelease, soportarlo de forma transparente.
  IF p_cr ? 'compiledRelease' THEN
    v_cr := p_cr->'compiledRelease';
    IF p_cr ? 'releases' AND jsonb_typeof(p_cr->'releases') = 'array' THEN
      v_releases := p_cr->'releases';
      -- Extraer metadatos cronológicos de releases con semántica honesta (RELEASE_INDEX / RELEASE_REFERENCE)
      SELECT jsonb_agg(jsonb_build_object(
        'id', COALESCE(rel->>'id', rel->>'url'),
        'date', rel->>'date',
        'tag', rel->'tag',
        'url', rel->>'url',
        'initiationType', rel->>'initiationType',
        'release_type', CASE 
          WHEN rel ? 'tender' OR rel ? 'contracts' OR rel ? 'awards' THEN 'FULL_RELEASE'
          ELSE 'RELEASE_REFERENCE'
        END,
        'payload_sha256', encode(digest(rel::TEXT, 'sha256'), 'hex')
      )) INTO v_releases_metadata
      FROM jsonb_array_elements(v_releases) AS rel;
    END IF;
  ELSE
    v_cr := p_cr;
  END IF;

  v_ocid := v_cr->>'ocid';
  IF v_ocid IS NULL OR trim(v_ocid) = '' THEN
    RAISE EXCEPTION 'compiledRelease no contiene ocid válido';
  END IF;

  v_tender := COALESCE(v_cr->'tender', '{}'::JSONB);
  v_planning := COALESCE(v_cr->'planning', '{}'::JSONB);
  v_dncp_nro := COALESCE(v_tender->>'id', split_part(v_ocid, '-', 3));
  v_titulo := COALESCE(v_tender->>'title', 'Sin título');
  v_buyer_name := COALESCE(v_cr->'buyer'->>'name', v_tender->'procuringEntity'->>'name');
  v_buyer_id := COALESCE(v_cr->'buyer'->>'id', v_tender->'procuringEntity'->>'id');

  -- 9. HASH SEMANTICS: SHA-256 CANÓNICO (NO MD5)
  v_sha := encode(digest(p_cr::TEXT, 'sha256'), 'hex');

  -- 1. Resolver o Ingestar Entidad Compradora
  IF v_buyer_id IS NOT NULL AND v_buyer_name IS NOT NULL THEN
    INSERT INTO public.procurement_entities (
      dncp_id, nombre, nombre_normalizado
    ) VALUES (
      v_buyer_id,
      v_buyer_name,
      public.normalizar_texto(v_buyer_name)
    )
    ON CONFLICT (dncp_id) DO UPDATE SET
      nombre = EXCLUDED.nombre,
      nombre_normalizado = EXCLUDED.nombre_normalizado,
      updated_at = now()
    RETURNING id INTO v_entity_id;
  END IF;

  -- 2. Calcular montos (sin forzar PYG si no está verificado en evidencia)
  v_monto_disp := (v_planning->'budget'->'amount'->>'amount')::NUMERIC;
  v_monto_ref := (v_tender->'value'->>'amount')::NUMERIC;
  v_moneda := v_tender->'value'->>'currency';
  v_estado := upper(COALESCE(v_tender->>'status', 'PLANNING'));

  -- 3. Upsert Proceso Global
  SELECT id, estado INTO v_process_id, v_estado_anterior
  FROM public.procurement_processes
  WHERE ocid = v_ocid;

  IF v_process_id IS NULL THEN
    INSERT INTO public.procurement_processes (
      ocid, dncp_nro, titulo, entity_id, comitente_nombre, comitente_id,
      categoria, categoria_detalle, procurement_method, procurement_method_detalle,
      award_criteria_detalle, monto_referencial, monto_disponible, moneda,
      fecha_publicacion, fecha_consultas_fin, fecha_entrega_ofertas, fecha_apertura,
      lugar_apertura, estado, estado_detalle, raw_json, payload_sha256, fuente,
      releases_metadata, sync_count, first_synced_at, last_synced_at
    ) VALUES (
      v_ocid, v_dncp_nro, v_titulo, v_entity_id, v_buyer_name, v_buyer_id,
      v_tender->>'mainProcurementCategory', v_tender->>'mainProcurementCategoryDetails',
      v_tender->>'procurementMethod', v_tender->>'procurementMethodDetails',
      v_tender->>'awardCriteriaDetails', v_monto_ref, v_monto_disp, v_moneda,
      (v_tender->>'datePublished')::TIMESTAMPTZ,
      (v_tender->'enquiryPeriod'->>'endDate')::TIMESTAMPTZ,
      (v_tender->'tenderPeriod'->>'endDate')::TIMESTAMPTZ,
      (v_tender->'bidOpening'->>'date')::TIMESTAMPTZ,
      COALESCE(v_tender->'bidOpening'->'address'->>'streetAddress', v_tender->>'submissionMethodDetails'),
      v_estado, v_tender->>'statusDetails', p_cr, v_sha, p_fuente,
      v_releases_metadata, 1, now(), now()
    ) RETURNING id INTO v_process_id;
  ELSE
    IF v_estado_anterior IS DISTINCT FROM v_estado THEN
      INSERT INTO public.procurement_process_history (
        process_id, estado_anterior, estado_nuevo, payload_sha256, change_diff
      ) VALUES (
        v_process_id, v_estado_anterior, v_estado, v_sha,
        jsonb_build_object('prev_status', v_estado_anterior, 'new_status', v_estado, 'date', now())
      );
    END IF;

    UPDATE public.procurement_processes SET
      titulo = v_titulo,
      entity_id = COALESCE(v_entity_id, procurement_processes.entity_id),
      comitente_nombre = v_buyer_name,
      comitente_id = v_buyer_id,
      categoria = v_tender->>'mainProcurementCategory',
      categoria_detalle = v_tender->>'mainProcurementCategoryDetails',
      procurement_method = v_tender->>'procurementMethod',
      procurement_method_detalle = v_tender->>'procurementMethodDetails',
      award_criteria_detalle = v_tender->>'awardCriteriaDetails',
      monto_referencial = v_monto_ref,
      monto_disponible = v_monto_disp,
      moneda = v_moneda,
      fecha_consultas_fin = (v_tender->'enquiryPeriod'->>'endDate')::TIMESTAMPTZ,
      fecha_entrega_ofertas = (v_tender->'tenderPeriod'->>'endDate')::TIMESTAMPTZ,
      fecha_apertura = (v_tender->'bidOpening'->>'date')::TIMESTAMPTZ,
      lugar_apertura = COALESCE(v_tender->'bidOpening'->'address'->>'streetAddress', v_tender->>'submissionMethodDetails'),
      estado = v_estado,
      estado_detalle = v_tender->>'statusDetails',
      raw_json = p_cr,
      payload_sha256 = v_sha,
      releases_metadata = COALESCE(v_releases_metadata, procurement_processes.releases_metadata),
      sync_count = sync_count + 1,
      last_synced_at = now(),
      updated_at = now()
    WHERE id = v_process_id;
  END IF;

  -- 4. Ingestar Lotes Globales (1. REAL DNCP IDS ARE NOT INTEGERS)
  IF jsonb_typeof(v_tender->'lots') = 'array' THEN
    FOR v_lot IN SELECT * FROM jsonb_array_elements(v_tender->'lots') LOOP
      v_lot_num := NULL;
      IF (v_lot->>'number') IS NOT NULL AND (v_lot->>'number') ~ '^[0-9]+$' THEN
        v_lot_num := (v_lot->>'number')::INTEGER;
      ELSIF (v_lot->>'numero') IS NOT NULL AND (v_lot->>'numero') ~ '^[0-9]+$' THEN
        v_lot_num := (v_lot->>'numero')::INTEGER;
      ELSIF (v_lot->>'id') IS NOT NULL AND (v_lot->>'id') ~ '^[0-9]+$' THEN
        v_lot_num := (v_lot->>'id')::INTEGER;
      END IF;

      INSERT INTO public.procurement_lots (
        process_id, lote_dncp_id, numero, titulo, monto_referencial
      ) VALUES (
        v_process_id,
        v_lot->>'id',
        v_lot_num,
        v_lot->>'title',
        (v_lot->'value'->>'amount')::NUMERIC
      )
      ON CONFLICT (process_id, lote_dncp_id) DO UPDATE SET
        numero = EXCLUDED.numero,
        titulo = EXCLUDED.titulo,
        monto_referencial = EXCLUDED.monto_referencial;
    END LOOP;
  END IF;

  -- 5. Ingestar Ítems Globales (1. REAL DNCP IDS ARE NOT INTEGERS: sort_order desde Orden o loop order)
  IF jsonb_typeof(v_tender->'items') = 'array' THEN
    v_item_sort_order := 1;
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_tender->'items') LOOP
      v_lot_id := NULL;
      IF v_item->>'relatedLot' IS NOT NULL THEN
        SELECT id INTO v_lot_id FROM public.procurement_lots
        WHERE process_id = v_process_id AND lote_dncp_id = v_item->>'relatedLot';
      END IF;

      v_parsed_order := NULL;
      IF jsonb_typeof(v_item->'attributes') = 'array' THEN
        SELECT (attr->>'value')::INTEGER INTO v_parsed_order
        FROM jsonb_array_elements(v_item->'attributes') AS attr
        WHERE lower(trim(attr->>'name')) = 'orden' AND (attr->>'value') ~ '^[0-9]+$'
        LIMIT 1;
      END IF;
      IF v_parsed_order IS NULL AND (v_item->>'sort_order') ~ '^[0-9]+$' THEN
        v_parsed_order := (v_item->>'sort_order')::INTEGER;
      ELSIF v_parsed_order IS NULL AND (v_item->>'orden') ~ '^[0-9]+$' THEN
        v_parsed_order := (v_item->>'orden')::INTEGER;
      END IF;
      v_final_sort_order := COALESCE(v_parsed_order, v_item_sort_order);

      INSERT INTO public.procurement_items (
        process_id, lot_id, item_dncp_id, codigo_catalogo, codigo_unspsc,
        descripcion, cantidad, unidad, precio_unitario_referencial, sort_order
      ) VALUES (
        v_process_id,
        v_lot_id,
        v_item->>'id',
        v_item->'classification'->>'id',
        v_item->'additionalClassifications'->0->>'id',
        COALESCE(v_item->>'description', v_item->'classification'->>'description', '(sin descripción)'),
        (v_item->>'quantity')::NUMERIC,
        v_item->'unit'->>'name',
        (v_item->'unit'->'value'->>'amount')::NUMERIC,
        v_final_sort_order
      )
      ON CONFLICT (process_id, item_dncp_id) DO UPDATE SET
        lot_id = EXCLUDED.lot_id,
        codigo_catalogo = EXCLUDED.codigo_catalogo,
        codigo_unspsc = EXCLUDED.codigo_unspsc,
        descripcion = EXCLUDED.descripcion,
        cantidad = EXCLUDED.cantidad,
        unidad = EXCLUDED.unidad,
        precio_unitario_referencial = EXCLUDED.precio_unitario_referencial,
        sort_order = EXCLUDED.sort_order;

      v_item_sort_order := v_item_sort_order + 1;
    END LOOP;
  END IF;

  -- 6. Ingestar Proveedores y Participaciones / Ofertas
  IF jsonb_typeof(v_cr->'parties') = 'array' THEN
    FOR v_party IN SELECT * FROM jsonb_array_elements(v_cr->'parties') LOOP
      v_ruc_clean := public.normalizar_ruc(COALESCE(v_party->'identifier'->>'id', v_party->>'id'));
      IF v_ruc_clean IS NOT NULL THEN
        v_supplier_name := COALESCE(v_party->>'name', v_ruc_clean);
        v_supplier_scale := v_party->'details'->>'scale';

        INSERT INTO public.procurement_suppliers (
          ruc_clean, ruc_raw, dv, nombre, nombre_normalizado, tamano
        ) VALUES (
          v_ruc_clean,
          COALESCE(v_party->'identifier'->>'id', v_party->>'id'),
          public.extraer_dv_ruc(COALESCE(v_party->'identifier'->>'id', v_party->>'id')),
          v_supplier_name,
          public.normalizar_texto(v_supplier_name),
          v_supplier_scale
        )
        ON CONFLICT (ruc_clean) DO UPDATE SET
          nombre = EXCLUDED.nombre,
          nombre_normalizado = EXCLUDED.nombre_normalizado,
          tamano = COALESCE(EXCLUDED.tamano, procurement_suppliers.tamano),
          updated_at = now()
        RETURNING id INTO v_supplier_id;
      END IF;
    END LOOP;
  END IF;

  IF jsonb_typeof(v_tender->'tenderers') = 'array' THEN
    FOR v_party IN SELECT * FROM jsonb_array_elements(v_tender->'tenderers') LOOP
      v_ruc_clean := public.normalizar_ruc(v_party->>'id');
      IF v_ruc_clean IS NOT NULL THEN
        SELECT id INTO v_supplier_id FROM public.procurement_suppliers WHERE ruc_clean = v_ruc_clean;
        IF v_supplier_id IS NOT NULL THEN
          INSERT INTO public.procurement_bids (
            process_id, supplier_id, fuente
          ) VALUES (
            v_process_id, v_supplier_id, 'API'
          )
          ON CONFLICT (process_id, supplier_id) DO NOTHING;
        END IF;
      END IF;
    END LOOP;
  END IF;

  -- 7. Ingestar Adjudicaciones (Multi-supplier semantics: join table is canonical)
  IF jsonb_typeof(v_cr->'awards') = 'array' THEN
    FOR v_award IN SELECT * FROM jsonb_array_elements(v_cr->'awards') LOOP
      IF v_award->>'status' <> 'unsuccessful' THEN
        v_award_dncp_id := COALESCE(v_award->>'id', '1');
        v_award_supplier_ids := ARRAY[]::UUID[];

        -- Recolectar todos los proveedores verificados de la adjudicación
        IF jsonb_typeof(v_award->'suppliers') = 'array' THEN
          FOR v_party IN SELECT * FROM jsonb_array_elements(v_award->'suppliers') LOOP
            v_ruc_clean := public.normalizar_ruc(v_party->>'id');
            IF v_ruc_clean IS NOT NULL THEN
              SELECT id INTO v_supplier_id FROM public.procurement_suppliers WHERE ruc_clean = v_ruc_clean;
              IF v_supplier_id IS NOT NULL AND NOT (v_supplier_id = ANY(v_award_supplier_ids)) THEN
                v_award_supplier_ids := array_append(v_award_supplier_ids, v_supplier_id);
              END IF;
            END IF;
          END LOOP;
        END IF;

        -- Semántica Multi-Proveedor Canónica:
        -- Exactamente 1 proveedor verificado -> supplier_id = ese ID
        -- Más de 1 proveedor verificado -> supplier_id = NULL
        -- Cero proveedores verificados -> supplier_id = NULL
        IF array_length(v_award_supplier_ids, 1) = 1 THEN
          v_supplier_id := v_award_supplier_ids[1];
        ELSE
          v_supplier_id := NULL;
        END IF;

        INSERT INTO public.procurement_awards (
          process_id, award_dncp_id, supplier_id, monto_adjudicado,
          moneda, fecha_adjudicacion, status, raw_payload
        ) VALUES (
          v_process_id,
          v_award_dncp_id,
          v_supplier_id,
          (v_award->'value'->>'amount')::NUMERIC,
          COALESCE(v_award->'value'->>'currency', v_moneda),
          (v_award->>'date')::TIMESTAMPTZ,
          v_award->>'status',
          v_award
        )
        ON CONFLICT (process_id, award_dncp_id) DO UPDATE SET
          supplier_id = EXCLUDED.supplier_id,
          monto_adjudicado = EXCLUDED.monto_adjudicado,
          moneda = COALESCE(EXCLUDED.moneda, procurement_awards.moneda),
          status = EXCLUDED.status,
          raw_payload = EXCLUDED.raw_payload
        RETURNING id INTO v_award_db_id;

        -- Ingestar TODOS los proveedores adjudicados en la tabla join procurement_award_suppliers
        IF array_length(v_award_supplier_ids, 1) > 0 THEN
          FOREACH v_supplier_id IN ARRAY v_award_supplier_ids LOOP
            INSERT INTO public.procurement_award_suppliers (award_id, supplier_id)
            VALUES (v_award_db_id, v_supplier_id)
            ON CONFLICT (award_id, supplier_id) DO NOTHING;

            INSERT INTO public.procurement_bids (process_id, supplier_id, gano, fuente)
            VALUES (v_process_id, v_supplier_id, true, 'API')
            ON CONFLICT (process_id, supplier_id) DO UPDATE SET gano = true;
          END LOOP;
        END IF;
      END IF;
    END LOOP;
  END IF;

  -- 8. Ingestar Contratos y Adendas
  IF jsonb_typeof(v_cr->'contracts') = 'array' THEN
    -- 8.1 PRIMER PASO: Ingestar Contratos Originales (aquellos que NO extienden otro contrato)
    FOR v_contract IN SELECT * FROM jsonb_array_elements(v_cr->'contracts') LOOP
      v_extends_contract_id := trim(COALESCE(v_contract->>'extendsContractID', ''));

      IF v_extends_contract_id = '' THEN
        v_contract_dncp_id := COALESCE(v_contract->>'id', '1');
        v_monto_contrato_orig := (v_contract->'value'->>'amount')::NUMERIC;
        v_contract_moneda := COALESCE(v_contract->'value'->>'currency', v_moneda);
        v_fecha_inicio := (v_contract->'period'->>'startDate')::TIMESTAMPTZ;
        v_fecha_fin := (v_contract->'period'->>'endDate')::TIMESTAMPTZ;
        v_duracion_dias_orig := NULL;

        IF v_fecha_inicio IS NOT NULL AND v_fecha_fin IS NOT NULL THEN
          v_duracion_dias_orig := extract(day from (v_fecha_fin - v_fecha_inicio))::INTEGER;
        END IF;

        -- CONTRACT -> AWARD -> SUPPLIER CHAIN:
        v_contract_award_id := NULL;
        v_contract_supplier_id := NULL;
        v_contract_supplier_ids := ARRAY[]::UUID[];

        IF v_contract->>'awardID' IS NOT NULL THEN
          SELECT id INTO v_contract_award_id
          FROM public.procurement_awards
          WHERE process_id = v_process_id AND award_dncp_id = (v_contract->>'awardID');
        END IF;

        -- 1. Si el contrato trae suppliers directamente, recolectar proveedores verificados
        IF jsonb_typeof(v_contract->'suppliers') = 'array' AND jsonb_array_length(v_contract->'suppliers') > 0 THEN
          FOR v_party IN SELECT * FROM jsonb_array_elements(v_contract->'suppliers') LOOP
            v_ruc_clean := public.normalizar_ruc(v_party->>'id');
            IF v_ruc_clean IS NOT NULL THEN
              SELECT id INTO v_supplier_id FROM public.procurement_suppliers WHERE ruc_clean = v_ruc_clean;
              IF v_supplier_id IS NOT NULL AND NOT (v_supplier_id = ANY(v_contract_supplier_ids)) THEN
                v_contract_supplier_ids := array_append(v_contract_supplier_ids, v_supplier_id);
              END IF;
            END IF;
          END LOOP;
        ELSIF v_contract_award_id IS NOT NULL THEN
          -- 2. Si el contrato no trae suppliers, heredar proveedores de la adjudicación vinculada
          SELECT ARRAY_AGG(DISTINCT supplier_id) INTO v_contract_supplier_ids
          FROM public.procurement_award_suppliers
          WHERE award_id = v_contract_award_id;
        END IF;

        -- Semántica Multi-Proveedor Canónica:
        -- Exactamente 1 proveedor verificado -> supplier_id = ese ID
        -- Más de 1 proveedor verificado -> supplier_id = NULL
        -- Cero proveedores verificados -> supplier_id = NULL
        IF v_contract_supplier_ids IS NOT NULL AND array_length(v_contract_supplier_ids, 1) = 1 THEN
          v_contract_supplier_id := v_contract_supplier_ids[1];
        ELSE
          v_contract_supplier_id := NULL;
        END IF;

        INSERT INTO public.procurement_contracts (
          process_id, award_id, supplier_id, contract_dncp_id, numero_contrato,
          monto_contrato, monto_contrato_original, monto_contrato_vigente,
          moneda, fecha_firma, fecha_inicio, fecha_fin, 
          duracion_dias_original, duracion_dias_vigente,
          status
        ) VALUES (
          v_process_id,
          v_contract_award_id,
          v_contract_supplier_id,
          v_contract_dncp_id,
          v_contract->>'title',
          v_monto_contrato_orig,
          v_monto_contrato_orig,
          v_monto_contrato_orig,
          v_contract_moneda,
          (v_contract->>'dateSigned')::TIMESTAMPTZ,
          v_fecha_inicio,
          v_fecha_fin,
          v_duracion_dias_orig,
          v_duracion_dias_orig,
          v_contract->>'status'
        )
        ON CONFLICT (process_id, contract_dncp_id) DO UPDATE SET
          award_id = COALESCE(EXCLUDED.award_id, procurement_contracts.award_id),
          supplier_id = EXCLUDED.supplier_id,
          numero_contrato = COALESCE(EXCLUDED.numero_contrato, procurement_contracts.numero_contrato),
          monto_contrato_original = COALESCE(procurement_contracts.monto_contrato_original, EXCLUDED.monto_contrato_original),
          moneda = COALESCE(EXCLUDED.moneda, procurement_contracts.moneda),
          fecha_firma = COALESCE(EXCLUDED.fecha_firma, procurement_contracts.fecha_firma),
          fecha_inicio = COALESCE(EXCLUDED.fecha_inicio, procurement_contracts.fecha_inicio),
          fecha_fin = COALESCE(EXCLUDED.fecha_fin, procurement_contracts.fecha_fin),
          duracion_dias_original = COALESCE(procurement_contracts.duracion_dias_original, EXCLUDED.duracion_dias_original),
          status = EXCLUDED.status
        RETURNING id INTO v_contract_db_id;

        -- Ingestar todos los proveedores del contrato en procurement_contract_suppliers
        IF v_contract_supplier_ids IS NOT NULL AND array_length(v_contract_supplier_ids, 1) > 0 THEN
          FOREACH v_supplier_id IN ARRAY v_contract_supplier_ids LOOP
            INSERT INTO public.procurement_contract_suppliers (contract_id, supplier_id)
            VALUES (v_contract_db_id, v_supplier_id)
            ON CONFLICT (contract_id, supplier_id) DO NOTHING;
          END LOOP;
        END IF;

        -- Ingestar adendas embebidas en contracts[].amendments
        IF jsonb_typeof(v_contract->'amendments') = 'array' THEN
          FOR v_amendment IN SELECT * FROM jsonb_array_elements(v_contract->'amendments') LOOP
            -- 3. DETERMINISTIC AMENDMENT IDENTITY (SHA-256)
            v_amendment_fingerprint := encode(digest(
              v_process_id::TEXT || '|' ||
              COALESCE(v_contract_dncp_id, '') || '|' ||
              COALESCE(v_amendment->>'date', '') || '|' ||
              COALESCE(v_amendment->>'description', '') || '|' ||
              COALESCE(v_amendment->'amendsAmount'->>'amount', ''),
              'sha256'
            ), 'hex');

            v_amendment_dncp_id := COALESCE(
              v_amendment->>'id',
              v_amendment->>'financialCode',
              'amend-' || substring(v_amendment_fingerprint from 1 for 16)
            );

            v_amendment_desc := v_amendment->>'description';
            v_dncp_raw_type := COALESCE(v_amendment->>'dncpAmendmentType', v_amendment->>'amendmentType', v_amendment_desc);
            v_amendment_moneda := COALESCE(v_amendment->'amendsAmount'->>'currency', v_contract_moneda);

            -- Clasificación con prioridad a evidencia cruda DNCP
            v_amendment_tipo := 'OTHER';
            IF lower(COALESCE(v_dncp_raw_type, '')) LIKE '%reajuste%' THEN
              v_amendment_tipo := 'PRICE_ADJUSTMENT';
            ELSIF lower(COALESCE(v_dncp_raw_type, '')) LIKE '%ampliaci%monto%' OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%aumento%' THEN
              v_amendment_tipo := 'AMOUNT_INCREASE';
            ELSIF lower(COALESCE(v_dncp_raw_type, '')) LIKE '%disminuci%monto%' OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%reducci%monto%' THEN
              v_amendment_tipo := 'AMOUNT_DECREASE';
            ELSIF lower(COALESCE(v_dncp_raw_type, '')) LIKE '%pr%rroga%' OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%ampliaci%plazo%' THEN
              v_amendment_tipo := 'TERM_EXTENSION';
            ELSIF lower(COALESCE(v_dncp_raw_type, '')) LIKE '%reducci%plazo%' THEN
              v_amendment_tipo := 'TERM_REDUCTION';
            ELSIF lower(COALESCE(v_dncp_raw_type, '')) LIKE '%modificaci%' OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%alcance%' OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%item%' THEN
              v_amendment_tipo := 'SCOPE_MODIFICATION';
            END IF;

            -- 8. AMENDMENT DIMENSIONS: monto_delta y duracion_delta independientes
            v_amendment_delta := (v_amendment->'amendsAmount'->>'amount')::NUMERIC;
            v_duracion_delta := NULL;

            INSERT INTO public.procurement_contract_amendments (
              contract_id, process_id, amendment_dncp_id, tipo,
              dncp_amendment_type_raw, source_type,
              fecha, descripcion, moneda, monto_delta, duracion_dias_delta,
              financial_code, is_orphan, raw_payload
            ) VALUES (
              v_contract_db_id,
              v_process_id,
              v_amendment_dncp_id,
              v_amendment_tipo,
              v_dncp_raw_type,
              'EMBEDDED_AMENDMENT',
              (v_amendment->>'date')::TIMESTAMPTZ,
              v_amendment_desc,
              v_amendment_moneda,
              v_amendment_delta,
              v_duracion_delta,
              v_amendment->>'financialCode',
              false,
              v_amendment
            )
            ON CONFLICT (process_id, amendment_dncp_id) DO UPDATE SET
              contract_id = EXCLUDED.contract_id,
              tipo = EXCLUDED.tipo,
              dncp_amendment_type_raw = EXCLUDED.dncp_amendment_type_raw,
              fecha = EXCLUDED.fecha,
              descripcion = EXCLUDED.descripcion,
              moneda = EXCLUDED.moneda,
              monto_delta = EXCLUDED.monto_delta,
              duracion_dias_delta = EXCLUDED.duracion_dias_delta,
              financial_code = EXCLUDED.financial_code,
              is_orphan = false,
              raw_payload = EXCLUDED.raw_payload;
          END LOOP;
        END IF;
      END IF;
    END LOOP;

    -- 8.2 SEGUNDO PASO: Ingestar Registros de Adenda vinculados por extendsContractID
    FOR v_contract IN SELECT * FROM jsonb_array_elements(v_cr->'contracts') LOOP
      v_extends_contract_id := trim(COALESCE(v_contract->>'extendsContractID', ''));

      IF v_extends_contract_id <> '' THEN
        -- 2. NEVER GUESS AMENDMENT PARENT: Exact match only!
        SELECT id INTO v_orig_contract_id
        FROM public.procurement_contracts
        WHERE process_id = v_process_id AND contract_dncp_id = v_extends_contract_id;

        -- 3. DETERMINISTIC AMENDMENT IDENTITY (SHA-256)
        v_amendment_fingerprint := encode(digest(
          v_process_id::TEXT || '|' ||
          v_extends_contract_id || '|' ||
          COALESCE(v_contract->>'dncpContractCode', '') || '|' ||
          COALESCE(v_contract->>'dateSigned', '') || '|' ||
          COALESCE(v_contract->>'title', '') || '|' ||
          COALESCE(v_contract->'value'->>'amount', ''),
          'sha256'
        ), 'hex');

        v_amendment_dncp_id := COALESCE(
          v_contract->>'id',
          v_contract->>'dncpContractCode',
          'amend-' || substring(v_amendment_fingerprint from 1 for 16)
        );

        v_dncp_raw_type := COALESCE(v_contract->>'dncpAmendmentType', v_contract->>'amendmentType', v_contract->>'title', 'Adenda Contractual');
        v_amendment_moneda := COALESCE(v_contract->'value'->>'currency', v_moneda);

        v_amendment_tipo := 'OTHER';
        IF lower(COALESCE(v_dncp_raw_type, '')) LIKE '%reajuste%' THEN
          v_amendment_tipo := 'PRICE_ADJUSTMENT';
        ELSIF lower(COALESCE(v_dncp_raw_type, '')) LIKE '%ampliaci%monto%' OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%aumento%' THEN
          v_amendment_tipo := 'AMOUNT_INCREASE';
        ELSIF lower(COALESCE(v_dncp_raw_type, '')) LIKE '%disminuci%monto%' OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%reducci%monto%' THEN
          v_amendment_tipo := 'AMOUNT_DECREASE';
        ELSIF lower(COALESCE(v_dncp_raw_type, '')) LIKE '%pr%rroga%' OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%ampliaci%plazo%' THEN
          v_amendment_tipo := 'TERM_EXTENSION';
        ELSIF lower(COALESCE(v_dncp_raw_type, '')) LIKE '%reducci%plazo%' THEN
          v_amendment_tipo := 'TERM_REDUCTION';
        ELSIF lower(COALESCE(v_dncp_raw_type, '')) LIKE '%modificaci%' OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%alcance%' OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%item%' THEN
          v_amendment_tipo := 'SCOPE_MODIFICATION';
        END IF;

        -- 8. AMENDMENT DIMENSIONS: Do not apply a monetary value to a term-only amendment merely because value exists
        v_amendment_delta := NULL;
        IF v_amendment_tipo IN ('AMOUNT_INCREASE', 'AMOUNT_DECREASE', 'PRICE_ADJUSTMENT', 'SCOPE_MODIFICATION')
           OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%monto%'
           OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%reajuste%' THEN
          v_amendment_delta := (v_contract->'value'->>'amount')::NUMERIC;
        END IF;

        -- Only apply a duration delta when official amendment represents a term modification
        v_duracion_delta := NULL;
        IF (v_amendment_tipo IN ('TERM_EXTENSION', 'TERM_REDUCTION', 'SCOPE_MODIFICATION')
            OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%plazo%'
            OR lower(COALESCE(v_dncp_raw_type, '')) LIKE '%pr%rroga%')
           AND v_contract->'period'->>'startDate' IS NOT NULL AND v_contract->'period'->>'endDate' IS NOT NULL THEN
          v_duracion_delta := extract(day from ((v_contract->'period'->>'endDate')::TIMESTAMPTZ - (v_contract->'period'->>'startDate')::TIMESTAMPTZ))::INTEGER;
        END IF;

        -- Insert amendment: if parent not found (v_orig_contract_id IS NULL), store as orphan evidence (contract_id = NULL, is_orphan = true)
        INSERT INTO public.procurement_contract_amendments (
          contract_id, process_id, amendment_dncp_id, tipo,
          dncp_amendment_type_raw, extends_contract_id, dncp_contract_code,
          source_type, fecha, descripcion, moneda, monto_delta, duracion_dias_delta,
          financial_code, is_orphan, raw_payload
        ) VALUES (
          v_orig_contract_id,
          v_process_id,
          v_amendment_dncp_id,
          v_amendment_tipo,
          v_dncp_raw_type,
          v_extends_contract_id,
          v_contract->>'dncpContractCode',
          'EXTENDS_CONTRACT',
          COALESCE((v_contract->>'dateSigned')::TIMESTAMPTZ, (v_contract->'period'->>'startDate')::TIMESTAMPTZ),
          v_contract->>'description',
          v_amendment_moneda,
          v_amendment_delta,
          v_duracion_delta,
          v_contract->>'financialCode',
          (v_orig_contract_id IS NULL),
          v_contract
        )
        ON CONFLICT (process_id, amendment_dncp_id) DO UPDATE SET
          contract_id = EXCLUDED.contract_id,
          tipo = EXCLUDED.tipo,
          dncp_amendment_type_raw = EXCLUDED.dncp_amendment_type_raw,
          extends_contract_id = EXCLUDED.extends_contract_id,
          dncp_contract_code = EXCLUDED.dncp_contract_code,
          fecha = EXCLUDED.fecha,
          descripcion = EXCLUDED.descripcion,
          moneda = EXCLUDED.moneda,
          monto_delta = EXCLUDED.monto_delta,
          duracion_dias_delta = EXCLUDED.duracion_dias_delta,
          financial_code = EXCLUDED.financial_code,
          is_orphan = EXCLUDED.is_orphan,
          raw_payload = EXCLUDED.raw_payload;
      END IF;
    END LOOP;

    -- 8.3 TERCER PASO: Reconciliar y computar estadísticas para cada contrato del proceso
    -- 8. AMENDMENT DIMENSIONS: Mantener incertidumbre de monto y duración INDEPENDIENTES
    FOR v_contract_db_id IN SELECT id FROM public.procurement_contracts WHERE process_id = v_process_id LOOP
      v_amend_count := 0;
      v_amend_total_delta := 0;
      v_amend_dur_delta := 0;
      v_has_unres_amt := false;
      v_has_unres_dur := false;
      v_any_amount_amend := false;
      v_any_dur_amend := false;

      -- Obtener moneda del contrato base
      SELECT moneda INTO v_contract_moneda FROM public.procurement_contracts WHERE id = v_contract_db_id;

      FOR r_amend IN SELECT tipo, monto_delta, duracion_dias_delta, moneda, dncp_amendment_type_raw, descripcion
                     FROM public.procurement_contract_amendments
                     WHERE contract_id = v_contract_db_id LOOP
        v_amend_count := v_amend_count + 1;

        -- Reconciliación de impacto en Monto
        IF r_amend.tipo IN ('AMOUNT_INCREASE', 'AMOUNT_DECREASE', 'PRICE_ADJUSTMENT', 'SCOPE_MODIFICATION')
           OR lower(COALESCE(r_amend.dncp_amendment_type_raw, r_amend.descripcion, '')) LIKE '%monto%'
           OR lower(COALESCE(r_amend.dncp_amendment_type_raw, r_amend.descripcion, '')) LIKE '%reajuste%' THEN
          v_any_amount_amend := true;
          -- 5. Moneda incompatible sin tipo de cambio verificado => efecto económico no resuelto
          IF r_amend.moneda IS DISTINCT FROM v_contract_moneda THEN
            v_has_unres_amt := true;
          ELSIF r_amend.monto_delta IS NULL THEN
            v_has_unres_amt := true;
          ELSE
            v_amend_total_delta := v_amend_total_delta + r_amend.monto_delta;
          END IF;
        ELSIF r_amend.monto_delta IS NOT NULL THEN
          IF r_amend.moneda IS DISTINCT FROM v_contract_moneda THEN
            v_has_unres_amt := true;
          ELSE
            v_amend_total_delta := v_amend_total_delta + r_amend.monto_delta;
          END IF;
        END IF;

        -- Reconciliación de impacto en Plazo
        IF r_amend.tipo IN ('TERM_EXTENSION', 'TERM_REDUCTION', 'SCOPE_MODIFICATION')
           OR lower(COALESCE(r_amend.dncp_amendment_type_raw, r_amend.descripcion, '')) LIKE '%plazo%'
           OR lower(COALESCE(r_amend.dncp_amendment_type_raw, r_amend.descripcion, '')) LIKE '%pr%rroga%' THEN
          v_any_dur_amend := true;
          IF r_amend.duracion_dias_delta IS NULL THEN
            v_has_unres_dur := true;
          ELSE
            v_amend_dur_delta := v_amend_dur_delta + r_amend.duracion_dias_delta;
          END IF;
        ELSIF r_amend.duracion_dias_delta IS NOT NULL THEN
          v_amend_dur_delta := v_amend_dur_delta + r_amend.duracion_dias_delta;
        END IF;
      END LOOP;

      UPDATE public.procurement_contracts SET
        amendment_count = v_amend_count,
        has_unresolved_amount = v_has_unres_amt,
        has_unresolved_duration = v_has_unres_dur,
        has_unresolved_amendments = (v_has_unres_amt OR v_has_unres_dur),
        total_amendment_amount_delta = CASE WHEN v_has_unres_amt AND v_any_amount_amend THEN NULL ELSE v_amend_total_delta END,
        total_amendment_duration_delta_days = CASE WHEN v_has_unres_dur AND v_any_dur_amend THEN NULL ELSE v_amend_dur_delta END,
        monto_contrato_vigente = CASE 
          WHEN v_has_unres_amt AND v_any_amount_amend THEN NULL 
          ELSE COALESCE(monto_contrato_original, monto_contrato) + v_amend_total_delta 
        END,
        duracion_dias_vigente = CASE 
          WHEN (v_has_unres_dur AND v_any_dur_amend) OR duracion_dias_original IS NULL THEN NULL 
          ELSE duracion_dias_original + v_amend_dur_delta 
        END
      WHERE id = v_contract_db_id;
    END LOOP;
  END IF;

  -- 9. Ingestar Documentos Públicos con ESCOPO DETERMINÍSTICO Y SHA-256
  IF jsonb_typeof(v_tender->'documents') = 'array' THEN
    FOR v_doc IN SELECT * FROM jsonb_array_elements(v_tender->'documents') LOOP
      v_doc_key := 'tender:' || COALESCE(v_doc->>'id', v_doc->>'url', encode(digest(COALESCE(v_doc->>'title', 'tender-doc'), 'sha256'), 'hex'));
      INSERT INTO public.procurement_documents (
        process_id, document_dncp_id, doc_key, tipo, tipo_detalle, titulo, url_dncp, format
      ) VALUES (
        v_process_id,
        v_doc->>'id',
        v_doc_key,
        v_doc->>'documentType',
        v_doc->>'documentTypeDetails',
        v_doc->>'title',
        v_doc->>'url',
        v_doc->>'format'
      )
      ON CONFLICT (process_id, doc_key) DO UPDATE SET
        tipo = COALESCE(EXCLUDED.tipo, procurement_documents.tipo),
        tipo_detalle = COALESCE(EXCLUDED.tipo_detalle, procurement_documents.tipo_detalle),
        url_dncp = COALESCE(EXCLUDED.url_dncp, procurement_documents.url_dncp),
        format = COALESCE(EXCLUDED.format, procurement_documents.format);
    END LOOP;
  END IF;

  IF jsonb_typeof(v_cr->'awards') = 'array' THEN
    FOR v_award IN SELECT * FROM jsonb_array_elements(v_cr->'awards') LOOP
      v_award_dncp_id := COALESCE(v_award->>'id', '1');
      IF jsonb_typeof(v_award->'documents') = 'array' THEN
        FOR v_doc IN SELECT * FROM jsonb_array_elements(v_award->'documents') LOOP
          v_doc_key := 'award:' || v_award_dncp_id || ':' || COALESCE(v_doc->>'id', v_doc->>'url', encode(digest(COALESCE(v_doc->>'title', 'award-doc'), 'sha256'), 'hex'));
          INSERT INTO public.procurement_documents (
            process_id, document_dncp_id, doc_key, tipo, tipo_detalle, titulo, url_dncp, format
          ) VALUES (
            v_process_id,
            v_doc->>'id',
            v_doc_key,
            v_doc->>'documentType',
            v_doc->>'documentTypeDetails',
            v_doc->>'title',
            v_doc->>'url',
            v_doc->>'format'
          )
          ON CONFLICT (process_id, doc_key) DO UPDATE SET
            tipo = COALESCE(EXCLUDED.tipo, procurement_documents.tipo),
            tipo_detalle = COALESCE(EXCLUDED.tipo_detalle, procurement_documents.tipo_detalle),
            url_dncp = COALESCE(EXCLUDED.url_dncp, procurement_documents.url_dncp),
            format = COALESCE(EXCLUDED.format, procurement_documents.format);
        END LOOP;
      END IF;
    END LOOP;
  END IF;

  IF jsonb_typeof(v_cr->'contracts') = 'array' THEN
    FOR v_contract IN SELECT * FROM jsonb_array_elements(v_cr->'contracts') LOOP
      v_contract_dncp_id := COALESCE(v_contract->>'id', '1');
      IF jsonb_typeof(v_contract->'documents') = 'array' THEN
        FOR v_doc IN SELECT * FROM jsonb_array_elements(v_contract->'documents') LOOP
          v_doc_key := 'contract:' || v_contract_dncp_id || ':' || COALESCE(v_doc->>'id', v_doc->>'url', encode(digest(COALESCE(v_doc->>'title', 'contract-doc'), 'sha256'), 'hex'));
          INSERT INTO public.procurement_documents (
            process_id, document_dncp_id, doc_key, tipo, tipo_detalle, titulo, url_dncp, format
          ) VALUES (
            v_process_id,
            v_doc->>'id',
            v_doc_key,
            v_doc->>'documentType',
            v_doc->>'documentTypeDetails',
            v_doc->>'title',
            v_doc->>'url',
            v_doc->>'format'
          )
          ON CONFLICT (process_id, doc_key) DO UPDATE SET
            tipo = COALESCE(EXCLUDED.tipo, procurement_documents.tipo),
            tipo_detalle = COALESCE(EXCLUDED.tipo_detalle, procurement_documents.tipo_detalle),
            url_dncp = COALESCE(EXCLUDED.url_dncp, procurement_documents.url_dncp),
            format = COALESCE(EXCLUDED.format, procurement_documents.format);
        END LOOP;
      END IF;
    END LOOP;
  END IF;

  RETURN v_process_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventory_apply_warehouse_upload_result(p_empresa_id uuid, p_submission_id uuid, p_resolved_sha256 text[], p_failed jsonb)
 RETURNS TABLE(upload_incomplete boolean, pending_uploads jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_submission record;
  v_pending jsonb;
  v_resolved text[];
  v_failed jsonb;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Acceso denegado: sólo el portal de rendiciones puede actualizar el estado de ingestión';
  END IF;

  v_resolved := coalesce(p_resolved_sha256, '{}');
  v_failed := coalesce(p_failed, '[]'::jsonb);
  IF jsonb_typeof(v_failed) <> 'array' THEN
    RAISE EXCEPTION 'p_failed debe ser un arreglo jsonb';
  END IF;

  SELECT * INTO v_submission
  FROM public.warehouse_submissions
  WHERE id = p_submission_id AND empresa_id = p_empresa_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Rendición no encontrada'; END IF;
  IF v_submission.status IN ('CONFIRMED', 'VOIDED') THEN
    RAISE EXCEPTION 'La rendición está cerrada y no admite cambios de ingestión';
  END IF;

  v_pending := coalesce(
    (
      SELECT jsonb_agg(elem)
      FROM jsonb_array_elements(v_submission.pending_uploads) elem
      WHERE NOT (elem ->> 'sha256' = ANY (v_resolved))
    ),
    '[]'::jsonb
  );

  IF jsonb_array_length(v_failed) > 0 THEN
    v_pending := coalesce(
      (
        SELECT jsonb_agg(elem)
        FROM jsonb_array_elements(v_pending) elem
        WHERE NOT (
          elem ->> 'sha256' IN (SELECT f ->> 'sha256' FROM jsonb_array_elements(v_failed) f)
        )
      ),
      '[]'::jsonb
    ) || v_failed;
  END IF;

  UPDATE public.warehouse_submissions
  SET pending_uploads = v_pending,
      upload_incomplete = (jsonb_array_length(v_pending) > 0),
      updated_at = now()
  WHERE id = p_submission_id AND empresa_id = p_empresa_id;

  RETURN QUERY SELECT (jsonb_array_length(v_pending) > 0), v_pending;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventory_confirm_receipt(p_empresa_id uuid, p_receipt_id uuid, p_delivery_location_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_confirmed_by uuid DEFAULT NULL::uuid)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_receipt record;
  v_order record;
  v_location uuid := p_delivery_location_id;
  v_item record;
  v_movement uuid;
  v_ids uuid[] := '{}';
  v_key text;
  v_received_quantity numeric;
BEGIN
  IF auth.role() <> 'service_role' THEN
    IF public.current_empresa_id() IS NULL OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
       OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
      RAISE EXCEPTION 'Acceso denegado para confirmar recepción';
    END IF;
  END IF;

  SELECT * INTO v_receipt
  FROM public.oc_recepciones
  WHERE id = p_receipt_id AND empresa_id = p_empresa_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Recepción no encontrada'; END IF;
  IF v_receipt.status = 'VOIDED' THEN RAISE EXCEPTION 'La recepción está anulada'; END IF;
  IF v_receipt.status = 'CONFIRMED' THEN
    IF p_delivery_location_id IS NOT NULL
       AND p_delivery_location_id IS DISTINCT FROM v_receipt.delivery_location_id THEN
      RAISE EXCEPTION 'La recepción ya fue confirmada en otra ubicación';
    END IF;
    SELECT coalesce(
      array_agg(ri.inventory_movement_id ORDER BY ri.id)
        FILTER (WHERE ri.inventory_movement_id IS NOT NULL),
      '{}'::uuid[]
    ) INTO v_ids
    FROM public.oc_recepcion_items ri
    WHERE ri.recepcion_id = p_receipt_id AND ri.empresa_id = p_empresa_id;
    RETURN v_ids;
  END IF;

  SELECT id, project_id, currency INTO v_order
  FROM public.authorized_orders
  WHERE id = v_receipt.order_id AND empresa_id = p_empresa_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'La OC de la recepción no pertenece a la empresa'; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.oc_recepcion_items
    WHERE recepcion_id = p_receipt_id AND empresa_id = p_empresa_id
  ) THEN
    RAISE EXCEPTION 'La recepción necesita al menos una línea';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.oc_recepcion_items ri
    LEFT JOIN public.authorized_order_items oi
      ON oi.id = ri.order_item_id
     AND oi.order_id = v_receipt.order_id
     AND oi.empresa_id = p_empresa_id
    WHERE ri.recepcion_id = p_receipt_id
      AND ri.empresa_id = p_empresa_id
      AND oi.id IS NULL
  ) THEN
    RAISE EXCEPTION 'Una línea de recepción no pertenece a la OC';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.oc_recepcion_items
    WHERE recepcion_id = p_receipt_id AND empresa_id = p_empresa_id
    GROUP BY order_item_id
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'No se puede repetir un ítem de OC dentro de una recepción';
  END IF;

  FOR v_item IN
    SELECT ri.order_item_id,
           sum(ri.cantidad_recibida) AS receipt_quantity,
           max(oi.quantity) AS ordered_quantity
    FROM public.oc_recepcion_items ri
    JOIN public.authorized_order_items oi
      ON oi.id = ri.order_item_id
     AND oi.order_id = v_receipt.order_id
     AND oi.empresa_id = p_empresa_id
    WHERE ri.recepcion_id = p_receipt_id
      AND ri.empresa_id = p_empresa_id
    GROUP BY ri.order_item_id
  LOOP
    SELECT coalesce(sum(ri2.cantidad_recibida), 0)
      INTO v_received_quantity
    FROM public.oc_recepcion_items ri2
    JOIN public.oc_recepciones r2 ON r2.id = ri2.recepcion_id
    WHERE r2.order_id = v_receipt.order_id
      AND r2.empresa_id = p_empresa_id
      AND ri2.empresa_id = p_empresa_id
      AND ri2.order_item_id = v_item.order_item_id
      AND ri2.recepcion_id <> p_receipt_id
      AND r2.status = 'CONFIRMED';
    IF v_item.receipt_quantity > v_item.ordered_quantity - v_received_quantity THEN
      RAISE EXCEPTION 'La recepción supera la cantidad pendiente de la línea de OC';
    END IF;
  END LOOP;

  v_location := coalesce(v_location, v_receipt.delivery_location_id);
  IF v_location IS NULL THEN
    SELECT il.id INTO v_location
    FROM public.inventory_locations il
    WHERE il.empresa_id = p_empresa_id AND il.active
      AND ((v_order.project_id IS NOT NULL AND il.location_type = 'PROJECT'
            AND il.project_id = v_order.project_id)
        OR (v_order.project_id IS NULL AND il.location_type = 'CENTRAL' AND il.is_primary))
    ORDER BY il.is_primary DESC, il.created_at
    LIMIT 1;
  END IF;
  IF v_location IS NULL THEN
    RAISE EXCEPTION 'La recepción necesita una ubicación de entrega válida';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.inventory_locations
    WHERE id = v_location AND empresa_id = p_empresa_id AND active
  ) THEN
    RAISE EXCEPTION 'La ubicación de entrega no pertenece a la empresa';
  END IF;

  FOR v_item IN
    SELECT ri.id, ri.producto_id, ri.cantidad_recibida, ri.inventory_movement_id,
           oi.unit, oi.unit_price
    FROM public.oc_recepcion_items ri
    JOIN public.authorized_order_items oi ON oi.id = ri.order_item_id
    WHERE ri.recepcion_id = p_receipt_id
      AND ri.empresa_id = p_empresa_id
      AND oi.empresa_id = p_empresa_id
  LOOP
    IF v_item.producto_id IS NULL THEN
      RAISE EXCEPTION 'La línea de recepción % necesita vincularse a un material del catálogo', v_item.id;
    END IF;
    IF v_item.inventory_movement_id IS NOT NULL THEN
      v_ids := array_append(v_ids, v_item.inventory_movement_id);
      CONTINUE;
    END IF;
    v_key := coalesce(nullif(trim(p_idempotency_key), ''), p_receipt_id::text) || ':' || v_item.id::text;
    v_movement := public.inventory_post_movement(
      p_empresa_id := p_empresa_id,
      p_producto_id := v_item.producto_id,
      p_quantity := v_item.cantidad_recibida,
      p_unit := v_item.unit,
      p_movement_type := 'RECEIPT',
      p_to_location_id := v_location,
      p_project_id := v_order.project_id,
      p_source_type := 'OC_RECEPCION',
      p_source_id := p_receipt_id,
      p_source_line_id := v_item.id,
      p_idempotency_key := v_key,
      p_cost_currency := v_order.currency,
      p_unit_cost := v_item.unit_price,
      p_created_by := p_confirmed_by,
      p_metadata := jsonb_build_object('receipt_id', p_receipt_id, 'order_id', v_order.id)
    );
    UPDATE public.oc_recepcion_items
    SET inventory_movement_id = v_movement
    WHERE id = v_item.id;
    v_ids := array_append(v_ids, v_movement);
  END LOOP;

  UPDATE public.oc_recepciones
  SET delivery_location_id = v_location,
      status = 'CONFIRMED', confirmed_by = p_confirmed_by,
      confirmed_at = now(), updated_at = now()
  WHERE id = p_receipt_id;
  RETURN v_ids;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventory_confirm_warehouse_submission(p_empresa_id uuid, p_submission_id uuid, p_confirmed_by uuid, p_idempotency_key text DEFAULT NULL::text)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_submission record;
  v_line record;
  v_movement uuid;
  v_ids uuid[] := '{}';
  v_key text;
BEGIN
  IF auth.role() <> 'service_role' THEN
    IF public.current_empresa_id() IS NULL OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
       OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
      RAISE EXCEPTION 'Acceso denegado para confirmar rendición';
    END IF;
  END IF;

  SELECT * INTO v_submission
  FROM public.warehouse_submissions
  WHERE id = p_submission_id AND empresa_id = p_empresa_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Rendición no encontrada'; END IF;
  IF v_submission.status = 'VOIDED' THEN RAISE EXCEPTION 'La rendición está anulada'; END IF;
  IF v_submission.status = 'CONFIRMED' THEN
    SELECT coalesce(array_agg(inventory_movement_id ORDER BY line_number), '{}') INTO v_ids
    FROM public.warehouse_submission_lines
    WHERE submission_id = p_submission_id AND inventory_movement_id IS NOT NULL;
    RETURN v_ids;
  END IF;
  IF v_submission.upload_incomplete THEN
    RAISE EXCEPTION 'La rendición tiene cargas de archivos incompletas o pendientes';
  END IF;
  IF v_submission.status NOT IN ('READY', 'NEEDS_REVIEW') THEN
    RAISE EXCEPTION 'La rendición todavía no está lista para confirmar';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.warehouse_submission_lines
    WHERE submission_id = p_submission_id AND state = 'PROPOSED'
  ) THEN
    RAISE EXCEPTION 'La rendición todavía tiene líneas propuestas sin revisar';
  END IF;

  FOR v_line IN
    SELECT * FROM public.warehouse_submission_lines
    WHERE submission_id = p_submission_id AND empresa_id = p_empresa_id AND state = 'CONFIRMED'
    ORDER BY line_number
  LOOP
    IF v_line.producto_id IS NULL OR v_line.quantity IS NULL OR v_line.unit IS NULL
       OR v_line.budget_item_id IS NULL THEN
      RAISE EXCEPTION 'La línea % no está completa para confirmar', v_line.line_number;
    END IF;
    IF v_line.inventory_movement_id IS NOT NULL THEN
      v_ids := array_append(v_ids, v_line.inventory_movement_id);
      CONTINUE;
    END IF;
    v_key := coalesce(nullif(trim(p_idempotency_key), ''), p_submission_id::text) || ':' || v_line.id::text;
    v_movement := public.inventory_post_movement(
      p_empresa_id := p_empresa_id,
      p_producto_id := v_line.producto_id,
      p_quantity := v_line.quantity,
      p_unit := v_line.unit,
      p_movement_type := 'CONSUMPTION',
      p_from_location_id := v_submission.location_id,
      p_project_id := v_submission.project_id,
      p_budget_item_id := v_line.budget_item_id,
      p_source_type := 'WAREHOUSE_SUBMISSION',
      p_source_id := p_submission_id,
      p_source_line_id := v_line.id,
      p_idempotency_key := v_key,
      p_created_by := p_confirmed_by,
      p_metadata := jsonb_build_object('submission_id', p_submission_id, 'line_number', v_line.line_number)
    );
    UPDATE public.warehouse_submission_lines
    SET inventory_movement_id = v_movement, updated_at = now()
    WHERE id = v_line.id;
    v_ids := array_append(v_ids, v_movement);
  END LOOP;

  UPDATE public.warehouse_submissions
  SET status = 'CONFIRMED', confirmed_by = p_confirmed_by,
      confirmed_at = now(), updated_at = now(), processing_error = NULL
  WHERE id = p_submission_id;
  RETURN v_ids;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventory_post_manual_movement(p_empresa_id uuid, p_producto_id uuid, p_quantity numeric, p_unit text, p_movement_type text, p_from_location_id uuid DEFAULT NULL::uuid, p_to_location_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_cost_currency currency_code DEFAULT NULL::currency_code, p_unit_cost numeric DEFAULT NULL::numeric, p_exchange_rate_to_company numeric DEFAULT NULL::numeric, p_created_by uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_plan text;
  v_actor uuid := auth.uid();
  v_from_project uuid;
  v_to_project uuid;
  v_expected_project uuid;
  v_effective_exchange_rate numeric;
  v_movement_id uuid;
  v_posted record;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF public.current_empresa_id() IS DISTINCT FROM p_empresa_id
       OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
      RAISE EXCEPTION 'Acceso denegado para registrar movimientos manuales';
    END IF;
    SELECT e.plan INTO v_plan
    FROM public.empresas e
    WHERE e.id = p_empresa_id;
    IF v_plan IS NULL OR v_plan NOT IN ('pro', 'caterpillar') THEN
      RAISE EXCEPTION 'Los movimientos canónicos de inventario requieren plan Pro';
    END IF;
    IF p_created_by IS DISTINCT FROM v_actor THEN
      RAISE EXCEPTION 'El creador del movimiento debe ser el usuario autenticado';
    END IF;
  END IF;

  IF upper(trim(p_movement_type)) NOT IN ('TRANSFER', 'RETURN', 'ADJUSTMENT') THEN
    RAISE EXCEPTION 'Este RPC solo admite transferencias, devoluciones y ajustes';
  END IF;
  IF p_idempotency_key IS NULL
     OR p_idempotency_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'El movimiento manual requiere una clave UUID estable';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.productos p
    WHERE p.id = p_producto_id AND p.empresa_id = p_empresa_id AND p.activo
  ) THEN
    RAISE EXCEPTION 'El material no está activo o no pertenece a la empresa';
  END IF;

  IF p_from_location_id IS NOT NULL THEN
    SELECT l.project_id INTO v_from_project
    FROM public.inventory_locations l
    WHERE l.id = p_from_location_id AND l.empresa_id = p_empresa_id AND l.active;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'La ubicación origen no pertenece a la empresa o está inactiva';
    END IF;
  END IF;
  IF p_to_location_id IS NOT NULL THEN
    SELECT l.project_id INTO v_to_project
    FROM public.inventory_locations l
    WHERE l.id = p_to_location_id AND l.empresa_id = p_empresa_id AND l.active;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'La ubicación destino no pertenece a la empresa o está inactiva';
    END IF;
  END IF;

  v_expected_project := CASE
    WHEN upper(trim(p_movement_type)) = 'RETURN' AND v_to_project IS NOT NULL THEN v_to_project
    ELSE coalesce(v_from_project, v_to_project)
  END;
  IF p_project_id IS DISTINCT FROM v_expected_project THEN
    RAISE EXCEPTION 'El proyecto del movimiento debe derivarse de sus ubicaciones';
  END IF;
  v_effective_exchange_rate := CASE
    WHEN upper(trim(p_movement_type)) = 'ADJUSTMENT'
      AND p_quantity > 0 AND p_cost_currency = 'PYG'::public.currency_code THEN 1
    ELSE p_exchange_rate_to_company
  END;

  v_movement_id := public.inventory_post_movement(
    p_empresa_id => p_empresa_id,
    p_producto_id => p_producto_id,
    p_quantity => p_quantity,
    p_unit => p_unit,
    p_movement_type => p_movement_type,
    p_from_location_id => p_from_location_id,
    p_to_location_id => p_to_location_id,
    p_project_id => v_expected_project,
    p_source_type => 'MANUAL',
    p_source_id => p_idempotency_key::uuid,
    p_source_line_id => NULL,
    p_idempotency_key => p_idempotency_key,
    p_cost_currency => p_cost_currency,
    p_unit_cost => p_unit_cost,
    p_exchange_rate_to_company => p_exchange_rate_to_company,
    p_created_by => p_created_by,
    p_metadata => coalesce(p_metadata, '{}'::jsonb)
  );

  SELECT m.id, m.producto_id, m.quantity, m.unit, m.movement_type,
         m.from_location_id, m.to_location_id, m.project_id,
         m.budget_item_id, m.source_type, m.source_id, m.source_line_id, m.idempotency_key,
         m.cost_currency, m.unit_cost, m.exchange_rate_to_company,
         m.created_by, m.metadata
  INTO v_posted
  FROM public.inventory_movements m
  WHERE m.id = v_movement_id AND m.empresa_id = p_empresa_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No se encontró el movimiento resultante';
  END IF;

  IF v_posted.producto_id IS DISTINCT FROM p_producto_id
     OR v_posted.quantity IS DISTINCT FROM p_quantity
     OR v_posted.unit IS DISTINCT FROM trim(p_unit)
     OR v_posted.movement_type IS DISTINCT FROM upper(trim(p_movement_type))
     OR v_posted.from_location_id IS DISTINCT FROM p_from_location_id
     OR v_posted.to_location_id IS DISTINCT FROM p_to_location_id
     OR v_posted.project_id IS DISTINCT FROM v_expected_project
     OR v_posted.budget_item_id IS NOT NULL
     OR v_posted.source_type IS DISTINCT FROM 'MANUAL'
     OR v_posted.source_id IS DISTINCT FROM p_idempotency_key::uuid
     OR v_posted.source_line_id IS NOT NULL
     OR v_posted.idempotency_key IS DISTINCT FROM p_idempotency_key
     OR v_posted.created_by IS DISTINCT FROM p_created_by
     OR v_posted.metadata IS DISTINCT FROM coalesce(p_metadata, '{}'::jsonb)
     OR (upper(trim(p_movement_type)) = 'ADJUSTMENT'
         AND v_posted.cost_currency IS DISTINCT FROM p_cost_currency)
     OR (upper(trim(p_movement_type)) = 'ADJUSTMENT'
         AND p_quantity > 0
         AND v_posted.unit_cost IS DISTINCT FROM p_unit_cost)
     OR (upper(trim(p_movement_type)) = 'ADJUSTMENT'
         AND p_quantity > 0
         AND v_posted.exchange_rate_to_company IS DISTINCT FROM v_effective_exchange_rate)
  THEN
    RAISE EXCEPTION 'La clave de idempotencia ya corresponde a un movimiento con datos distintos';
  END IF;

  RETURN v_movement_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventory_post_movement(p_empresa_id uuid, p_producto_id uuid, p_quantity numeric, p_unit text, p_movement_type text, p_from_location_id uuid DEFAULT NULL::uuid, p_to_location_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_budget_item_id uuid DEFAULT NULL::uuid, p_source_type text DEFAULT 'MANUAL'::text, p_source_id uuid DEFAULT NULL::uuid, p_source_line_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_cost_currency currency_code DEFAULT NULL::currency_code, p_unit_cost numeric DEFAULT NULL::numeric, p_exchange_rate_to_company numeric DEFAULT NULL::numeric, p_created_by uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_type                text := upper(trim(p_movement_type));
  v_source_type         text := coalesce(nullif(trim(p_source_type), ''), 'MANUAL');
  v_idempotency_key     text := nullif(trim(p_idempotency_key), '');
  v_existing            record;
  v_movement_id         uuid;
  v_product_unit        text;
  v_product_empresa     uuid;
  v_location_empresa    uuid;
  v_from_project        uuid;
  v_to_project          uuid;
  v_from_type           text;
  v_to_type             text;
  v_context_project     uuid := p_project_id;
  v_currency             public.currency_code := p_cost_currency;
  v_order_currency      public.currency_code;
  v_receipt_location    uuid;
  v_receipt_order       uuid;
  v_receipt_order_item  uuid;
  v_receipt_product     uuid;
  v_receipt_quantity    numeric;
  v_ordered_quantity    numeric;
  v_received_quantity   numeric;
  v_cost_unit            numeric;
  v_total_cost           numeric := 0;
  v_total_cost_company   numeric;
  v_cost_status          text := 'COMPUTABLE';
  v_effective_exchange_rate numeric;
  v_remaining             numeric;
  v_take                  numeric;
  v_cost_take             numeric;
  v_cost_take_company     numeric;
  v_currency_count        integer;
  v_currency_text         text;
  v_cost_quantity         numeric;
  v_balance               record;
  v_balance_unit_cost     numeric;
  v_balance_company_unit_cost numeric;
  v_had_balance           boolean;
BEGIN
  IF auth.role() <> 'service_role' THEN
    IF public.current_empresa_id() IS NULL OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id THEN
      RAISE EXCEPTION 'Acceso denegado: tenant inválido';
    END IF;
    IF NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
      RAISE EXCEPTION 'No tenés permisos para registrar movimientos de inventario';
    END IF;
  END IF;

  IF v_type NOT IN ('RECEIPT', 'TRANSFER', 'CONSUMPTION', 'RETURN', 'ADJUSTMENT') THEN
    RAISE EXCEPTION 'Tipo de movimiento inválido: %', p_movement_type;
  END IF;
  IF p_quantity IS NULL OR p_quantity = 0 OR (v_type <> 'ADJUSTMENT' AND p_quantity < 0) THEN
    RAISE EXCEPTION 'La cantidad del movimiento no es válida';
  END IF;
  IF v_type = 'RECEIPT' AND (p_from_location_id IS NOT NULL OR p_to_location_id IS NULL) THEN
    RAISE EXCEPTION 'Una recepción necesita solo ubicación destino';
  ELSIF v_type = 'TRANSFER' AND (p_from_location_id IS NULL OR p_to_location_id IS NULL
      OR p_from_location_id = p_to_location_id) THEN
    RAISE EXCEPTION 'Una transferencia necesita origen y destino distintos';
  ELSIF v_type = 'CONSUMPTION' AND (p_from_location_id IS NULL OR p_to_location_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Un consumo necesita solo ubicación origen';
  ELSIF v_type = 'RETURN' AND (p_from_location_id IS NULL OR p_to_location_id IS NULL
      OR p_from_location_id = p_to_location_id) THEN
    RAISE EXCEPTION 'RETURN necesita origen y destino distintos';
  ELSIF v_type = 'ADJUSTMENT' AND (
      (p_quantity > 0 AND (p_from_location_id IS NOT NULL OR p_to_location_id IS NULL))
      OR (p_quantity < 0 AND (p_from_location_id IS NULL OR p_to_location_id IS NOT NULL))
    ) THEN
    RAISE EXCEPTION 'La forma del ajuste no es válida';
  END IF;
  IF p_unit IS NULL OR length(trim(p_unit)) = 0 THEN
    RAISE EXCEPTION 'La unidad del movimiento es obligatoria';
  END IF;
  IF v_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'La idempotency_key es obligatoria';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_empresa_id::text || ':' || v_idempotency_key, 0)
  );
  IF p_source_id IS NOT NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        p_empresa_id::text || ':' || v_source_type || ':' || p_source_id::text
          || ':' || coalesce(p_source_line_id::text, ''),
        0
      )
    );
  END IF;
  IF p_exchange_rate_to_company IS NOT NULL AND p_exchange_rate_to_company <= 0 THEN
    RAISE EXCEPTION 'El tipo de cambio debe ser mayor a cero';
  END IF;
  IF p_unit_cost IS NOT NULL AND p_unit_cost < 0 THEN
    RAISE EXCEPTION 'El costo unitario no puede ser negativo';
  END IF;

  SELECT * INTO v_existing
  FROM public.inventory_movements
  WHERE empresa_id = p_empresa_id AND idempotency_key = v_idempotency_key;
  IF FOUND THEN
    IF v_existing.producto_id IS DISTINCT FROM p_producto_id
       OR v_existing.quantity IS DISTINCT FROM p_quantity
       OR v_existing.unit IS DISTINCT FROM trim(p_unit)
       OR v_existing.movement_type IS DISTINCT FROM v_type
       OR v_existing.from_location_id IS DISTINCT FROM p_from_location_id
       OR v_existing.to_location_id IS DISTINCT FROM p_to_location_id
       OR (p_cost_currency IS NOT NULL AND v_existing.cost_currency IS DISTINCT FROM p_cost_currency)
       OR (p_unit_cost IS NOT NULL AND v_existing.unit_cost IS DISTINCT FROM p_unit_cost)
       OR (p_project_id IS NOT NULL AND v_existing.project_id IS DISTINCT FROM p_project_id)
       OR (p_budget_item_id IS NOT NULL AND v_existing.budget_item_id IS DISTINCT FROM p_budget_item_id) THEN
      RAISE EXCEPTION 'La idempotency_key ya fue usada para otra operación';
    END IF;
    RETURN v_existing.id;
  END IF;
  IF p_source_id IS NOT NULL THEN
    SELECT * INTO v_existing
    FROM public.inventory_movements
    WHERE empresa_id = p_empresa_id
      AND source_type = v_source_type
      AND source_id = p_source_id
      AND source_line_id IS NOT DISTINCT FROM p_source_line_id
      AND movement_type = v_type;
    IF FOUND THEN
      IF v_existing.producto_id IS DISTINCT FROM p_producto_id
         OR v_existing.quantity IS DISTINCT FROM p_quantity
         OR v_existing.from_location_id IS DISTINCT FROM p_from_location_id
         OR v_existing.to_location_id IS DISTINCT FROM p_to_location_id
         OR (p_cost_currency IS NOT NULL AND v_existing.cost_currency IS DISTINCT FROM p_cost_currency)
         OR (p_unit_cost IS NOT NULL AND v_existing.unit_cost IS DISTINCT FROM p_unit_cost)
         OR (p_project_id IS NOT NULL AND v_existing.project_id IS DISTINCT FROM p_project_id)
         OR (p_budget_item_id IS NOT NULL AND v_existing.budget_item_id IS DISTINCT FROM p_budget_item_id) THEN
        RAISE EXCEPTION 'El origen ya fue aplicado con otra operación';
      END IF;
      RETURN v_existing.id;
    END IF;
  END IF;

  SELECT empresa_id, unidad INTO v_product_empresa, v_product_unit
  FROM public.productos
  WHERE id = p_producto_id;
  IF v_product_empresa IS NULL OR v_product_empresa IS DISTINCT FROM p_empresa_id THEN
    RAISE EXCEPTION 'El material no pertenece a la empresa';
  END IF;
  IF trim(v_product_unit) <> trim(p_unit) THEN
    RAISE EXCEPTION 'La unidad no coincide con la unidad del material';
  END IF;

  IF p_from_location_id IS NOT NULL THEN
    SELECT empresa_id, project_id, location_type
      INTO v_location_empresa, v_from_project, v_from_type
    FROM public.inventory_locations
    WHERE id = p_from_location_id AND active;
    IF v_location_empresa IS NULL OR v_location_empresa IS DISTINCT FROM p_empresa_id THEN
      RAISE EXCEPTION 'La ubicación origen no pertenece a la empresa o está inactiva';
    END IF;
  END IF;
  IF p_to_location_id IS NOT NULL THEN
    SELECT empresa_id, project_id, location_type
      INTO v_location_empresa, v_to_project, v_to_type
    FROM public.inventory_locations
    WHERE id = p_to_location_id AND active;
    IF v_location_empresa IS NULL OR v_location_empresa IS DISTINCT FROM p_empresa_id THEN
      RAISE EXCEPTION 'La ubicación destino no pertenece a la empresa o está inactiva';
    END IF;
  END IF;

  IF v_type = 'RECEIPT' AND v_source_type = 'OC_RECEPCION' AND p_source_id IS NOT NULL THEN
    SELECT r.order_id, r.delivery_location_id, ao.currency,
           ri.producto_id, ri.cantidad_recibida, ri.order_item_id, aoi.quantity
      INTO v_receipt_order, v_receipt_location, v_order_currency,
           v_receipt_product, v_receipt_quantity, v_receipt_order_item,
           v_ordered_quantity
    FROM public.oc_recepciones r
    JOIN public.oc_recepcion_items ri ON ri.recepcion_id = r.id
    JOIN public.authorized_orders ao ON ao.id = r.order_id
    JOIN public.authorized_order_items aoi ON aoi.id = ri.order_item_id
    WHERE r.id = p_source_id
      AND ri.id = p_source_line_id
      AND r.empresa_id = p_empresa_id
      AND ao.empresa_id = p_empresa_id
      AND aoi.empresa_id = p_empresa_id
      AND ri.empresa_id = p_empresa_id;
    IF v_receipt_order IS NULL THEN
      RAISE EXCEPTION 'La recepción o su línea no pertenece a la empresa';
    END IF;
    PERFORM 1
    FROM public.authorized_orders
    WHERE id = v_receipt_order AND empresa_id = p_empresa_id
    FOR UPDATE;
    SELECT coalesce(sum(ri2.cantidad_recibida), 0)
      INTO v_received_quantity
    FROM public.oc_recepcion_items ri2
    JOIN public.oc_recepciones r2 ON r2.id = ri2.recepcion_id
    WHERE r2.order_id = v_receipt_order
      AND r2.empresa_id = p_empresa_id
      AND ri2.empresa_id = p_empresa_id
      AND ri2.order_item_id = v_receipt_order_item
      AND ri2.recepcion_id <> p_source_id
      AND r2.status = 'CONFIRMED';
    IF p_quantity > v_ordered_quantity - v_received_quantity THEN
      RAISE EXCEPTION 'La recepción supera la cantidad pendiente de la línea de OC';
    END IF;
    IF v_receipt_product IS DISTINCT FROM p_producto_id
       OR p_quantity > v_receipt_quantity THEN
      RAISE EXCEPTION 'La línea de recepción no coincide con el material o cantidad';
    END IF;
    IF v_receipt_location IS NOT NULL AND v_receipt_location IS DISTINCT FROM p_to_location_id THEN
      RAISE EXCEPTION 'La ubicación no coincide con la recepción';
    END IF;
    v_context_project := coalesce(v_context_project,
      (SELECT project_id FROM public.authorized_orders WHERE id = v_receipt_order));
    v_currency := coalesce(v_currency, v_order_currency);
  END IF;

  IF v_to_project IS NOT NULL AND v_type IN ('RECEIPT', 'RETURN') THEN
    IF v_context_project IS NULL THEN v_context_project := v_to_project; END IF;
    IF v_context_project IS DISTINCT FROM v_to_project THEN
      RAISE EXCEPTION 'El proyecto contextual no coincide con la ubicación destino';
    END IF;
  END IF;
  IF v_type = 'CONSUMPTION' THEN
    IF v_context_project IS NULL OR p_budget_item_id IS NULL THEN
      RAISE EXCEPTION 'El consumo requiere proyecto y partida presupuestaria';
    END IF;
    IF v_from_project IS DISTINCT FROM v_context_project THEN
      RAISE EXCEPTION 'El consumo debe salir del pañol de la obra indicada';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.budget_items bi
      JOIN public.projects pr ON pr.id = bi.project_id
      WHERE bi.id = p_budget_item_id
        AND bi.project_id = v_context_project
        AND pr.empresa_id = p_empresa_id
    ) THEN
      RAISE EXCEPTION 'La partida no pertenece al proyecto y tenant indicados';
    END IF;
  END IF;
  IF p_project_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.projects WHERE id = p_project_id AND empresa_id = p_empresa_id
  ) THEN
    RAISE EXCEPTION 'El proyecto no pertenece a la empresa';
  END IF;
  IF p_budget_item_id IS NOT NULL AND v_type <> 'CONSUMPTION' THEN
    RAISE EXCEPTION 'Solo el consumo puede imputarse a una partida';
  END IF;

  IF v_type = 'RECEIPT' AND (v_currency IS NULL OR p_unit_cost IS NULL) THEN
    RAISE EXCEPTION 'La recepción necesita costo y moneda de compra explícitos';
  END IF;
  IF v_type = 'ADJUSTMENT' AND (v_currency IS NULL OR p_unit_cost IS NULL) THEN
    RAISE EXCEPTION 'El ajuste necesita costo y moneda explicitos';
  END IF;

  IF v_type = 'RECEIPT' OR (v_type = 'ADJUSTMENT' AND p_quantity > 0) THEN
    IF v_currency = 'PYG' THEN
      v_cost_status := 'COMPUTABLE';
      v_effective_exchange_rate := 1;
    ELSIF p_exchange_rate_to_company IS NOT NULL AND p_exchange_rate_to_company > 0 THEN
      v_cost_status := 'COMPUTABLE';
      v_effective_exchange_rate := p_exchange_rate_to_company;
    ELSE
      v_cost_status := 'REVISION_REQUERIDA';
      v_effective_exchange_rate := NULL;
    END IF;
  END IF;

  INSERT INTO public.inventory_movements (
    empresa_id, producto_id, quantity, unit, movement_type,
    from_location_id, to_location_id, project_id, budget_item_id,
    source_type, source_id, source_line_id, idempotency_key,
    status, cost_status, created_by, confirmed_by, metadata
  ) VALUES (
    p_empresa_id, p_producto_id, p_quantity, trim(p_unit), v_type,
    p_from_location_id, p_to_location_id, v_context_project, p_budget_item_id,
    v_source_type, p_source_id, p_source_line_id, v_idempotency_key,
    'DRAFT', v_cost_status, p_created_by, p_created_by, coalesce(p_metadata, '{}'::jsonb)
  ) RETURNING id INTO v_movement_id;

  IF v_type = 'RECEIPT' OR (v_type = 'ADJUSTMENT' AND p_quantity > 0) THEN
    v_cost_unit := p_unit_cost;
    v_total_cost := p_quantity * v_cost_unit;
    v_total_cost_company := CASE WHEN v_cost_status = 'COMPUTABLE'
      THEN v_total_cost * v_effective_exchange_rate ELSE NULL END;
    PERFORM public.upsert_inventory_balance(
      p_empresa_id => p_empresa_id,
      p_producto_id => p_producto_id,
      p_location_id => p_to_location_id,
      p_cost_currency => CASE WHEN v_cost_status = 'COMPUTABLE' THEN v_currency ELSE NULL END,
      p_quantity => p_quantity,
      p_total_cost => CASE WHEN v_cost_status = 'COMPUTABLE' THEN v_total_cost ELSE NULL END,
      p_total_cost_company => v_total_cost_company,
      p_cost_status => v_cost_status,
      p_original_cost_currency => v_currency::text,
      p_original_unit_cost => v_cost_unit,
      p_original_total_cost => v_total_cost,
      p_exchange_rate_to_company => v_effective_exchange_rate,
      p_cost_source => CASE WHEN v_cost_status = 'COMPUTABLE'
        THEN 'CANONICAL_MOVEMENT' ELSE 'CANONICAL_MOVEMENT_REVIEW' END
    );

    INSERT INTO public.inventory_movement_costs (
      empresa_id, movement_id, quantity, cost_currency, unit_cost, total_cost,
      cost_status, exchange_rate_to_company, total_cost_company
    ) VALUES (
      p_empresa_id, v_movement_id, p_quantity, v_currency, v_cost_unit, v_total_cost,
      v_cost_status, v_effective_exchange_rate, v_total_cost_company
    );

  ELSIF v_type = 'ADJUSTMENT' AND p_quantity < 0 THEN
    SELECT quantity, total_cost, total_cost_company, exchange_rate_to_company,
           cost_currency, cost_status INTO v_balance
    FROM public.inventory_balances
    WHERE empresa_id = p_empresa_id AND producto_id = p_producto_id
      AND location_id = p_from_location_id AND cost_currency = v_currency
      AND cost_status = 'COMPUTABLE'
    FOR UPDATE;
    IF NOT FOUND OR v_balance.quantity < abs(p_quantity) THEN
      RAISE EXCEPTION 'Stock insuficiente para el ajuste';
    END IF;
    v_cost_unit := CASE WHEN v_balance.quantity = 0 THEN 0
                        ELSE v_balance.total_cost / v_balance.quantity END;
    v_total_cost := abs(p_quantity) * v_cost_unit;
    v_cost_take_company := abs(p_quantity)
      * (v_balance.total_cost_company / NULLIF(v_balance.quantity, 0));
    v_total_cost_company := v_cost_take_company;
    v_effective_exchange_rate := v_balance.exchange_rate_to_company;
    UPDATE public.inventory_balances
    SET quantity = quantity - abs(p_quantity),
        total_cost = greatest(0, total_cost - v_total_cost),
        total_cost_company = greatest(0, total_cost_company - v_total_cost_company),
        updated_at = now()
    WHERE empresa_id = p_empresa_id AND producto_id = p_producto_id
      AND location_id = p_from_location_id AND cost_currency = v_currency;
    INSERT INTO public.inventory_movement_costs (
      empresa_id, movement_id, quantity, cost_currency, unit_cost, total_cost,
      cost_status, exchange_rate_to_company, total_cost_company
    ) VALUES (
      p_empresa_id, v_movement_id, abs(p_quantity), v_currency, v_cost_unit, v_total_cost,
      'COMPUTABLE', v_effective_exchange_rate, v_total_cost_company
    );
    v_total_cost := -v_total_cost;

  ELSE
    v_remaining := p_quantity;
    FOR v_balance IN
      SELECT id, cost_currency, quantity, total_cost, total_cost_company,
             exchange_rate_to_company, cost_status, original_cost_currency,
             original_unit_cost
      FROM public.inventory_balances
      WHERE empresa_id = p_empresa_id AND producto_id = p_producto_id
        AND location_id = p_from_location_id AND quantity > 0
        AND cost_status = 'COMPUTABLE' AND cost_currency IS NOT NULL
      ORDER BY cost_currency::text
      FOR UPDATE
    LOOP
      EXIT WHEN v_remaining <= 0;
      v_take := least(v_remaining, v_balance.quantity);
      v_balance_unit_cost := CASE WHEN v_balance.quantity = 0 THEN 0
                                  ELSE v_balance.total_cost / v_balance.quantity END;
      v_cost_take := CASE WHEN v_take = v_balance.quantity THEN v_balance.total_cost
                          ELSE v_take * v_balance_unit_cost END;
      IF v_balance.cost_currency <> 'PYG'
         AND (v_balance.exchange_rate_to_company IS NULL
              OR v_balance.total_cost_company IS NULL) THEN
        RAISE EXCEPTION 'El saldo extranjero requiere FX antes de moverse';
      END IF;
      v_balance_company_unit_cost := CASE WHEN v_balance.quantity = 0 THEN 0
        ELSE v_balance.total_cost_company / v_balance.quantity END;
      v_cost_take_company := CASE WHEN v_take = v_balance.quantity
        THEN v_balance.total_cost_company
        ELSE v_take * v_balance_company_unit_cost END;

      UPDATE public.inventory_balances
      SET quantity = quantity - v_take,
          total_cost = greatest(0, total_cost - v_cost_take),
          total_cost_company = greatest(0, total_cost_company - v_cost_take_company),
          updated_at = now()
      WHERE id = v_balance.id;

      INSERT INTO public.inventory_movement_costs (
        empresa_id, movement_id, quantity, cost_currency, unit_cost, total_cost,
        cost_status, exchange_rate_to_company, total_cost_company
      ) VALUES (
        p_empresa_id, v_movement_id, v_take, v_balance.cost_currency,
        v_balance_unit_cost, v_cost_take, 'COMPUTABLE',
        v_balance.exchange_rate_to_company, v_cost_take_company
      );

      IF v_type IN ('TRANSFER', 'RETURN') THEN
        PERFORM public.upsert_inventory_balance(
          p_empresa_id => p_empresa_id,
          p_producto_id => p_producto_id,
          p_location_id => p_to_location_id,
          p_cost_currency => v_balance.cost_currency,
          p_quantity => v_take,
          p_total_cost => v_cost_take,
          p_total_cost_company => v_cost_take_company,
          p_cost_status => 'COMPUTABLE',
          p_original_cost_currency => coalesce(
            v_balance.original_cost_currency, v_balance.cost_currency::text
          ),
          p_original_unit_cost => coalesce(v_balance.original_unit_cost, v_balance_unit_cost),
          p_original_total_cost => v_cost_take,
          p_exchange_rate_to_company => v_balance.exchange_rate_to_company,
          p_cost_source => 'CANONICAL_MOVEMENT'
        );
      END IF;
      v_remaining := v_remaining - v_take;
    END LOOP;
    IF coalesce(v_remaining, p_quantity) > 0 THEN
      RAISE EXCEPTION 'Stock insuficiente en la ubicación origen: faltan %', v_remaining;
    END IF;

    SELECT coalesce(sum(total_cost), 0), coalesce(sum(quantity), 0),
           count(DISTINCT cost_currency), min(cost_currency::text),
           CASE WHEN count(*) = count(total_cost_company)
                THEN sum(total_cost_company) ELSE NULL END
      INTO v_total_cost, v_cost_quantity, v_currency_count, v_currency_text,
           v_total_cost_company
    FROM public.inventory_movement_costs
    WHERE movement_id = v_movement_id;
  END IF;

  IF v_type = 'RECEIPT' OR v_type = 'ADJUSTMENT' THEN
    SELECT count(DISTINCT cost_currency), min(cost_currency::text),
           CASE WHEN count(*) = count(total_cost_company)
                THEN sum(total_cost_company) ELSE NULL END
      INTO v_currency_count, v_currency_text, v_total_cost_company
    FROM public.inventory_movement_costs
    WHERE movement_id = v_movement_id;
  END IF;

  IF v_currency_count = 1 THEN
    v_currency := v_currency_text::public.currency_code;
    SELECT sum(total_cost) / NULLIF(sum(quantity), 0)
      INTO v_cost_unit
    FROM public.inventory_movement_costs
    WHERE movement_id = v_movement_id;
  ELSE
    v_currency := NULL;
    v_cost_unit := NULL;
  END IF;

  IF v_cost_status = 'COMPUTABLE'
     AND v_total_cost_company IS NOT NULL
     AND v_total_cost IS NOT NULL
     AND v_total_cost <> 0
     AND v_type IN ('TRANSFER', 'RETURN', 'CONSUMPTION') THEN
    v_effective_exchange_rate := abs(v_total_cost_company / v_total_cost);
  END IF;

  UPDATE public.inventory_movements
  SET cost_currency = v_currency,
      unit_cost = v_cost_unit,
      cost_status = v_cost_status,
      cost_total = CASE WHEN v_type = 'ADJUSTMENT' AND p_quantity < 0
                        THEN v_total_cost ELSE abs(v_total_cost) END,
      exchange_rate_to_company = CASE
        WHEN v_cost_status = 'COMPUTABLE' AND v_currency_count = 1
          THEN v_effective_exchange_rate
        ELSE NULL
      END,
      cost_total_company = CASE WHEN v_type = 'ADJUSTMENT' AND p_quantity < 0
                                THEN CASE WHEN v_total_cost_company IS NULL THEN NULL ELSE -v_total_cost_company END
                                ELSE v_total_cost_company END,
      status = 'CONFIRMED', confirmed_by = p_created_by, confirmed_at = now()
  WHERE id = v_movement_id;

  PERFORM public.sync_inventory_legacy_projection(
    p_empresa_id,
    p_producto_id,
    ARRAY[p_from_location_id, p_to_location_id]::uuid[]
  );

  RETURN v_movement_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventory_save_submission_lines_atomic(p_empresa_id uuid, p_submission_id uuid, p_evidence_id uuid, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_submission record;
  v_evidence record;
  v_next_line integer;
  v_item jsonb;
  v_inserted_count integer := 0;
  v_raw_desc text;
  v_qty numeric;
  v_unit text;
  v_confidence numeric;
  v_uncertainty text;
  v_notes text;
BEGIN
  IF auth.role() <> 'service_role' THEN
    IF public.current_empresa_id() IS NULL OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
       OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
      RAISE EXCEPTION 'Acceso denegado para registrar líneas de rendición';
    END IF;
  END IF;

  SELECT * INTO v_submission
  FROM public.warehouse_submissions
  WHERE id = p_submission_id AND empresa_id = p_empresa_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Rendición no encontrada o no pertenece a la empresa';
  END IF;

  IF v_submission.status = 'CONFIRMED' THEN
    RAISE EXCEPTION 'No se pueden agregar líneas a una rendición confirmada';
  END IF;

  IF v_submission.status = 'VOIDED' THEN
    RAISE EXCEPTION 'No se pueden agregar líneas a una rendición anulada';
  END IF;

  SELECT * INTO v_evidence
  FROM public.warehouse_submission_evidence
  WHERE id = p_evidence_id AND submission_id = p_submission_id AND empresa_id = p_empresa_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Evidencia no encontrada para esta rendición';
  END IF;

  SELECT coalesce(max(line_number), 0) + 1 INTO v_next_line
  FROM public.warehouse_submission_lines
  WHERE submission_id = p_submission_id;

  IF p_lines IS NOT NULL AND jsonb_array_length(p_lines) > 0 THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
      v_raw_desc := trim(coalesce(v_item->>'rawDescription', ''));
      IF length(v_raw_desc) = 0 THEN
        CONTINUE;
      END IF;

      v_qty := (v_item->>'quantity')::numeric;
      v_unit := nullif(trim(coalesce(v_item->>'unit', '')), '');
      v_confidence := (v_item->>'confidence')::numeric;
      v_uncertainty := nullif(trim(coalesce(v_item->>'uncertaintyReason', '')), '');
      v_notes := nullif(trim(coalesce(v_item->>'notes', '')), '');

      INSERT INTO public.warehouse_submission_lines (
        empresa_id,
        submission_id,
        line_number,
        raw_description,
        quantity,
        unit,
        state,
        confidence,
        uncertainty_reason,
        source_evidence_id,
        notes
      ) VALUES (
        p_empresa_id,
        p_submission_id,
        v_next_line,
        v_raw_desc,
        v_qty,
        v_unit,
        'PROPOSED',
        v_confidence,
        v_uncertainty,
        p_evidence_id,
        v_notes
      );

      v_next_line := v_next_line + 1;
      v_inserted_count := v_inserted_count + 1;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'inserted_count', v_inserted_count,
    'next_line_number', v_next_line
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.log_audit_event(p_action text, p_rfq_id uuid DEFAULT NULL::uuid, p_rfq_provider_id uuid DEFAULT NULL::uuid, p_invoice_id uuid DEFAULT NULL::uuid, p_authorized_order_id uuid DEFAULT NULL::uuid, p_detail jsonb DEFAULT NULL::jsonb, p_actor_type text DEFAULT 'internal'::text, p_actor_label text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  insert into public.audit_logs (
    actor_id, actor_type, actor_label, action, rfq_id, rfq_provider_id,
    invoice_id, authorized_order_id, detail
  ) values (
    auth.uid(), p_actor_type, p_actor_label, p_action, p_rfq_id, p_rfq_provider_id,
    p_invoice_id, p_authorized_order_id, p_detail
  ) returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.log_quotation_view(p_token_hash text, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tok public.sales_quotation_tokens%ROWTYPE;
BEGIN
  IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' THEN RETURN; END IF;
  SELECT * INTO v_tok FROM public.sales_quotation_tokens WHERE token_hash = p_token_hash;
  IF NOT FOUND THEN RETURN; END IF;
  INSERT INTO public.sales_quotation_events
    (empresa_id, sales_document_id, token_id, event_type, actor_label, actor_ip, actor_user_agent)
  VALUES (v_tok.empresa_id, v_tok.sales_document_id, v_tok.id, 'VIEWED', 'cliente', p_ip, p_user_agent);
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_email_send_attempt_dispatching(p_send_attempt_id uuid, p_empresa_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_attempt public.email_send_attempts%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required for email attempt transition';
  end if;
  select a.* into v_attempt
  from public.email_send_attempts a
  join public.email_drafts d on d.id = a.draft_id
  where a.id = p_send_attempt_id and a.empresa_id = p_empresa_id
    and d.created_by = p_user_id
  for update;
  if not found or v_attempt.status <> 'CLAIMED' then
    raise exception 'email send attempt is not claimable for dispatch';
  end if;
  update public.email_send_attempts
  set status = 'DISPATCHING', started_at = coalesce(started_at, now())
  where id = p_send_attempt_id;
  return jsonb_build_object('attempt_id', p_send_attempt_id, 'status', 'DISPATCHING');
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_email_send_attempt_unknown(p_send_attempt_id uuid, p_empresa_id uuid, p_user_id uuid, p_error_code text, p_failure_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_attempt public.email_send_attempts%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required for email attempt transition';
  end if;
  select a.* into v_attempt
  from public.email_send_attempts a
  join public.email_drafts d on d.id = a.draft_id
  where a.id = p_send_attempt_id and a.empresa_id = p_empresa_id
    and d.created_by = p_user_id
  for update;
  if not found or v_attempt.status not in ('CLAIMED', 'DISPATCHING') then
    raise exception 'email send attempt cannot be marked delivery-unknown';
  end if;
  update public.email_send_attempts
  set status = 'DELIVERY_UNKNOWN', error_code = p_error_code, completed_at = now()
  where id = p_send_attempt_id;
  update public.email_drafts
  set status = 'DELIVERY_UNKNOWN', failure_reason = p_failure_reason
  where id = v_attempt.draft_id and status = 'SENDING';
  return jsonb_build_object('attempt_id', p_send_attempt_id, 'status', 'DELIVERY_UNKNOWN');
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_invoice_apto_para_pago(p_invoice_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_status public.invoice_status;
  v_order_id uuid;
begin
  select status into v_status from public.invoices where id = p_invoice_id;
  if v_status not in ('MATCH', 'APROBADO_EXCEPCION') then
    raise exception 'La factura debe estar conciliada (MATCH) o aprobada por excepción antes de marcar apto para pago';
  end if;

  update public.invoices set status = 'APTO_PARA_PAGO' where id = p_invoice_id;

  select authorized_order_id into v_order_id
  from public.invoice_order_matches where invoice_id = p_invoice_id;

  perform public.sync_order_payment_status(v_order_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_invoice_pagado(p_invoice_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_status public.invoice_status;
  v_order_id uuid;
begin
  select status into v_status from public.invoices where id = p_invoice_id;
  if v_status <> 'APTO_PARA_PAGO' then
    raise exception 'La factura debe estar APTO_PARA_PAGO antes de marcarla como pagada';
  end if;

  update public.invoices set status = 'PAGADO' where id = p_invoice_id;

  select authorized_order_id into v_order_id
  from public.invoice_order_matches where invoice_id = p_invoice_id;

  perform public.sync_order_payment_status(v_order_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.next_doc_code(p_empresa_id uuid, p_doc_type text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_n integer;
BEGIN
  IF auth.uid() IS NULL
     OR p_empresa_id IS DISTINCT FROM public.current_empresa_id() THEN
    RAISE EXCEPTION 'Access denied for document code generation';
  END IF;
  IF p_doc_type IS NULL OR p_doc_type NOT IN ('RFQ','OC','OP','OT') THEN
    RAISE EXCEPTION 'Invalid document type';
  END IF;

  INSERT INTO public.doc_code_counters AS counter (empresa_id, doc_type, last_number)
  VALUES (p_empresa_id, p_doc_type, 1)
  ON CONFLICT (empresa_id, doc_type)
  DO UPDATE SET last_number = counter.last_number + 1
  RETURNING last_number INTO v_n;

  RETURN p_doc_type || '-' || pg_catalog.to_char(pg_catalog.now(), 'YYYY') || '-'
    || pg_catalog.lpad(v_n::text, 4, '0');
END;
$function$

CREATE OR REPLACE FUNCTION public.normalizar_ruc(p_ruc text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_clean TEXT;
BEGIN
  IF p_ruc IS NULL OR trim(p_ruc) = '' THEN
    RETURN NULL;
  END IF;
  v_clean := regexp_replace(trim(p_ruc), '\s+', '', 'g');
  v_clean := regexp_replace(v_clean, '^(PY-)?RUC-', '', 'i');
  IF position('-' IN v_clean) > 0 THEN
    v_clean := split_part(v_clean, '-', 1);
  END IF;
  v_clean := regexp_replace(v_clean, '[^a-zA-Z0-9]', '', 'g');
  IF length(v_clean) = 0 THEN
    RETURN NULL;
  END IF;
  RETURN upper(v_clean);
END;
$function$

CREATE OR REPLACE FUNCTION public.normalizar_texto(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  if p_text is null then
    return null;
  end if;
  -- Quitar acentos y dobles espacios, convertir a mayúsculas
  return upper(trim(regexp_replace(
    translate(p_text, 'áéíóúÁÉÍÓÚñÑüÜ', 'aeiouAEIOUnNuU'),
    '\s+', ' ', 'g'
  )));
end;
$function$

CREATE OR REPLACE FUNCTION public.planilla_confirmar_computo(p_planilla_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_empresa_id     uuid;
  v_planilla       record;
  v_project_id     uuid;
  v_row            jsonb;
  v_row_id         text;
  v_deleted        boolean;
  v_code           text;
  v_description    text;
  v_unit           text;
  v_quantity       numeric;
  v_unit_price     numeric;
  v_style          jsonb;
  v_existing_id    uuid;
  v_base_updated   timestamptz;
  v_current_updated timestamptz;
  v_max_sort       integer;
  v_new_id         uuid;
  v_inserted       integer := 0;
  v_updated        integer := 0;
  v_deleted_count  integer := 0;
  v_code_to_id     jsonb := '{}'::jsonb;
  v_parent_code    text;
  v_parent_id      uuid;
  v_dot_idx        integer;
BEGIN
  v_empresa_id := public.current_empresa_id();
  IF v_empresa_id IS NULL THEN
    RAISE EXCEPTION 'No se pudo determinar la empresa del usuario autenticado.';
  END IF;

  SELECT * INTO v_planilla
  FROM public.planillas
  WHERE id = p_planilla_id AND empresa_id = v_empresa_id
  FOR UPDATE;

  IF v_planilla IS NULL THEN
    RAISE EXCEPTION 'Planilla % no encontrada o sin permisos.', p_planilla_id;
  END IF;

  IF v_planilla.modulo <> 'computo_presupuesto' THEN
    RAISE EXCEPTION 'Esta función solo confirma planillas de cómputo/presupuesto.';
  END IF;

  IF v_planilla.estado = 'confirmed' THEN
    RETURN jsonb_build_object(
      'already_confirmed', true,
      'planilla_id', v_planilla.id,
      'result', v_planilla.applied_result
    );
  END IF;

  IF v_planilla.estado = 'cancelled' THEN
    RAISE EXCEPTION 'La planilla % está cancelada y no puede confirmarse.', p_planilla_id;
  END IF;

  v_project_id := (v_planilla.contexto->>'projectId')::uuid;
  IF v_project_id IS NULL THEN
    RAISE EXCEPTION 'La planilla no tiene projectId en su contexto.';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.projects WHERE id = v_project_id AND empresa_id = v_empresa_id
  ) THEN
    RAISE EXCEPTION 'Proyecto % no encontrado o no pertenece a la empresa.', v_project_id;
  END IF;

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_planilla.snapshot->'rows')
  LOOP
    v_row_id := v_row->>'_rowId';
    CONTINUE WHEN v_row_id IS NULL OR left(v_row_id, 4) = 'new:';

    v_existing_id := v_row_id::uuid;
    v_deleted := coalesce((v_row->>'_deleted')::boolean, false);

    SELECT updated_at INTO v_current_updated
    FROM public.budget_items
    WHERE id = v_existing_id AND project_id = v_project_id;

    v_base_updated := NULLIF(v_planilla.base_versions->>v_row_id, '')::timestamptz;

    IF v_current_updated IS NULL THEN
      RAISE EXCEPTION 'CONFLICTO_CONCURRENCIA: la partida % ya no existe (fue eliminada).', v_row_id
        USING ERRCODE = 'P0409';
    END IF;

    IF v_base_updated IS NULL OR v_current_updated <> v_base_updated THEN
      RAISE EXCEPTION 'CONFLICTO_CONCURRENCIA: la partida % cambió desde que se abrió la planilla.', v_row_id
        USING ERRCODE = 'P0409';
    END IF;

    IF v_deleted THEN
      DELETE FROM public.budget_items WHERE id = v_existing_id AND project_id = v_project_id;
      v_deleted_count := v_deleted_count + 1;
    ELSE
      v_code        := v_row->>'code';
      v_description := v_row->>'description';
      v_unit        := NULLIF(v_row->>'unit', '');
      v_quantity    := NULLIF(v_row->>'quantity', '')::numeric;
      v_unit_price  := NULLIF(v_row->>'unit_price', '')::numeric;
      v_style       := coalesce(v_row->'_style', '{}'::jsonb);

      IF v_code IS NULL OR trim(v_code) = '' THEN
        RAISE EXCEPTION 'La partida % no puede quedar sin código.', v_row_id;
      END IF;
      IF v_description IS NULL OR trim(v_description) = '' THEN
        RAISE EXCEPTION 'La partida % no puede quedar sin descripción.', v_row_id;
      END IF;

      UPDATE public.budget_items
      SET code = v_code, description = v_description, unit = v_unit,
          quantity = v_quantity, unit_price = v_unit_price, style = v_style
      WHERE id = v_existing_id AND project_id = v_project_id;
      v_updated := v_updated + 1;

      v_code_to_id := v_code_to_id || jsonb_build_object(v_code, v_existing_id::text);
    END IF;
  END LOOP;

  SELECT coalesce(max(sort_order), 0) INTO v_max_sort
  FROM public.budget_items WHERE project_id = v_project_id;

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_planilla.snapshot->'rows')
  LOOP
    v_row_id := v_row->>'_rowId';
    CONTINUE WHEN v_row_id IS NULL OR left(v_row_id, 4) <> 'new:';
    CONTINUE WHEN coalesce((v_row->>'_deleted')::boolean, false);

    v_code        := v_row->>'code';
    v_description := v_row->>'description';
    v_unit        := NULLIF(v_row->>'unit', '');
    v_quantity    := NULLIF(v_row->>'quantity', '')::numeric;
    v_unit_price  := NULLIF(v_row->>'unit_price', '')::numeric;
    v_style       := coalesce(v_row->'_style', '{}'::jsonb);

    IF v_code IS NULL OR trim(v_code) = '' THEN
      RAISE EXCEPTION 'Una fila nueva no puede quedar sin código.';
    END IF;
    IF v_description IS NULL OR trim(v_description) = '' THEN
      RAISE EXCEPTION 'Una fila nueva no puede quedar sin descripción.';
    END IF;

    v_parent_id := NULL;
    v_dot_idx := length(v_code) - position('.' in reverse(v_code));
    IF position('.' in v_code) > 0 THEN
      v_parent_code := left(v_code, v_dot_idx);
      v_parent_id := NULLIF(v_code_to_id->>v_parent_code, '')::uuid;
      IF v_parent_id IS NULL THEN
        SELECT id INTO v_parent_id FROM public.budget_items
        WHERE project_id = v_project_id AND code = v_parent_code;
      END IF;
    END IF;

    v_max_sort := v_max_sort + 1;
    INSERT INTO public.budget_items (
      project_id, parent_id, code, description, unit, quantity, unit_price, sort_order, style
    ) VALUES (
      v_project_id, v_parent_id, v_code, v_description, v_unit, v_quantity, v_unit_price, v_max_sort, v_style
    ) RETURNING id INTO v_new_id;
    v_inserted := v_inserted + 1;

    v_code_to_id := v_code_to_id || jsonb_build_object(v_code, v_new_id::text);
  END LOOP;

  UPDATE public.planillas
  SET estado = 'confirmed',
      confirmed_at = now(),
      confirmed_by = auth.uid(),
      applied_result = jsonb_build_object(
        'inserted', v_inserted, 'updated', v_updated, 'deleted', v_deleted_count
      )
  WHERE id = p_planilla_id;

  RETURN jsonb_build_object(
    'already_confirmed', false,
    'planilla_id', p_planilla_id,
    'result', jsonb_build_object('inserted', v_inserted, 'updated', v_updated, 'deleted', v_deleted_count)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_closed_project_certificate_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.status::text IS DISTINCT FROM 'BORRADOR' THEN
    RAISE EXCEPTION 'Un certificado cerrado no se puede eliminar';
  END IF;
  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_confirmed_warehouse_submission_evidence_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_submission_id uuid;
  v_status text;
BEGIN
  v_submission_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.submission_id ELSE NEW.submission_id END;
  SELECT status INTO v_status
  FROM public.warehouse_submissions
  WHERE id = v_submission_id
  FOR UPDATE;
  IF v_status = 'CONFIRMED' THEN
    RAISE EXCEPTION 'La evidencia de una rendición confirmada es inmutable';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_confirmed_warehouse_submission_line_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_submission_id uuid;
  v_status text;
BEGIN
  v_submission_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.submission_id ELSE NEW.submission_id END;
  SELECT status INTO v_status
  FROM public.warehouse_submissions
  WHERE id = v_submission_id
  FOR UPDATE;

  IF v_status = 'CONFIRMED' THEN
    RAISE EXCEPTION 'Las líneas de una rendición confirmada son inmutables';
  END IF;
  IF TG_OP <> 'INSERT' AND OLD.inventory_movement_id IS NOT NULL THEN
    RAISE EXCEPTION 'Una línea vinculada a un movimiento canónico es inmutable';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_confirmed_warehouse_submission_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status = 'CONFIRMED' THEN
      RAISE EXCEPTION 'Una rendición confirmada es inmutable y no puede ser eliminada';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.status = 'CONFIRMED' THEN
      RAISE EXCEPTION 'Una rendición confirmada es inmutable y no puede ser modificada ni reabierta';
    END IF;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_inventory_movement_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP = 'DELETE' OR OLD.status = 'CONFIRMED' THEN
    RAISE EXCEPTION 'Los movimientos de inventario confirmados son inmutables; use una reversión o ajuste';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.recompute_invoice_status(p_invoice_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tolerance_pct constant numeric := 5;  -- espejo de OVERBILL_TOLERANCE_PCT
  v_current_status public.invoice_status;
  v_order_id uuid;
  v_order_total numeric(14,2);
  v_facturado numeric(14,2);
  v_has_exception boolean;
begin
  select status into v_current_status from public.invoices where id = p_invoice_id;

  -- Una vez que una acción humana marcó la factura apta para pago (o ya se
  -- pagó), el recálculo automático de conciliación no debe revertirla.
  if v_current_status in ('APTO_PARA_PAGO', 'PAGADO') then
    return;
  end if;

  select iom.authorized_order_id into v_order_id
  from public.invoice_order_matches iom
  where iom.invoice_id = p_invoice_id;

  if v_order_id is null then
    update public.invoices set status = 'PENDIENTE' where id = p_invoice_id;
    return;
  end if;

  select ao.total_price into v_order_total
  from public.authorized_orders ao where ao.id = v_order_id;

  select coalesce(sum(i.total), 0) into v_facturado
  from public.invoice_order_matches iom
  join public.invoices i on i.id = iom.invoice_id
  where iom.authorized_order_id = v_order_id;

  update public.authorized_orders
    set facturado_amount = v_facturado,
        status = case
          when status in ('APTO_PARA_PAGO', 'PAGADO') then status
          when v_facturado >= v_order_total then 'FACTURADO'
          else 'AUTORIZADO'
        end
    where id = v_order_id;

  select exists(select 1 from public.invoice_exceptions where invoice_id = p_invoice_id)
    into v_has_exception;

  if v_facturado <= v_order_total * (1 + v_tolerance_pct / 100.0) then
    update public.invoices set status = 'MATCH' where id = p_invoice_id;
  elsif v_has_exception then
    update public.invoices set status = 'APROBADO_EXCEPCION' where id = p_invoice_id;
  else
    update public.invoices set status = 'REQUIERE_REVISION' where id = p_invoice_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.recompute_order_item_quantity_invoiced()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item_id uuid;
begin
  v_item_id := coalesce(new.order_item_id, old.order_item_id);

  update public.authorized_order_items
  set quantity_invoiced = (
    select coalesce(sum(quantity_matched), 0)
    from public.invoice_item_matches
    where order_item_id = v_item_id
  )
  where id = v_item_id;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.recover_stale_email_send_attempts(p_cutoff timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_attempt record;
  v_count integer := 0;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required for email attempt recovery';
  end if;
  for v_attempt in
    select a.id, a.draft_id
    from public.email_send_attempts a
    where a.status = 'DISPATCHING'
      and a.started_at < p_cutoff
    for update skip locked
  loop
    update public.email_send_attempts
    set status = 'DELIVERY_UNKNOWN', error_code = 'STALE_DISPATCHING', completed_at = now()
    where id = v_attempt.id and status = 'DISPATCHING';
    update public.email_drafts
    set status = 'DELIVERY_UNKNOWN', failure_reason = 'El intento quedÃ³ incierto y no se reintentarÃ¡ automÃ¡ticamente.'
    where id = v_attempt.draft_id and status = 'SENDING';
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_cobro_atomico(p_empresa_id uuid, p_sales_document_id uuid, p_amount numeric, p_method text, p_receipt_date date DEFAULT CURRENT_DATE, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_cuenta_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_doc public.sales_documents;
  v_account_currency public.currency_code;
  v_receipt_id uuid;
BEGIN
  IF auth.uid() IS NULL
     OR p_created_by IS DISTINCT FROM auth.uid()
     OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
     OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Acceso denegado para registrar cobro';
  END IF;
  SELECT * INTO v_doc FROM public.sales_documents d
  WHERE d.id = p_sales_document_id AND d.empresa_id = p_empresa_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Documento de venta no encontrado'; END IF;
  IF v_doc.status NOT IN ('EMITIDA','COBRADA_PARCIAL') THEN
    RAISE EXCEPTION 'Solo se registran cobros en documentos emitidos';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount - (v_doc.total - v_doc.cobrado_amount) > 0.01 THEN
    RAISE EXCEPTION 'El monto de cobro es inválido o supera el saldo del documento';
  END IF;
  IF p_created_by IS NULL THEN RAISE EXCEPTION 'El actor del cobro es obligatorio'; END IF;

  IF p_cuenta_id IS NOT NULL THEN
    SELECT c.moneda INTO v_account_currency FROM public.cuentas_financieras c
    WHERE c.id = p_cuenta_id AND c.empresa_id = p_empresa_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Cuenta financiera no encontrada para la empresa'; END IF;
    IF v_account_currency IS DISTINCT FROM v_doc.currency THEN
      RAISE EXCEPTION 'La moneda de la cuenta no coincide con la del documento';
    END IF;
  END IF;

  INSERT INTO public.sales_receipts (
    empresa_id, sales_document_id, amount, receipt_date, method, reference,
    notes, cuenta_id, created_by
  ) VALUES (
    p_empresa_id, p_sales_document_id, p_amount, coalesce(p_receipt_date, CURRENT_DATE),
    p_method::public.receipt_method, p_reference, p_notes, p_cuenta_id, p_created_by
  ) RETURNING id INTO v_receipt_id;

  IF p_cuenta_id IS NOT NULL THEN
    PERFORM public.registrar_movimiento_tesoreria(
      p_empresa_id := p_empresa_id,
      p_cuenta_id := p_cuenta_id,
      p_monto := p_amount,
      p_tipo := 'COBRO',
      p_fecha := coalesce(p_receipt_date, CURRENT_DATE),
      p_motivo := 'Cobro comprobante ' || v_doc.code,
      p_sales_receipt_id := v_receipt_id,
      p_created_by := p_created_by,
      p_permitir_negativo := true
    );
  END IF;
  RETURN v_receipt_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_movimiento_tesoreria(p_empresa_id uuid, p_cuenta_id uuid, p_monto numeric, p_tipo text, p_fecha date DEFAULT NULL::date, p_motivo text DEFAULT NULL::text, p_payment_order_id uuid DEFAULT NULL::uuid, p_sales_receipt_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid, p_permitir_negativo boolean DEFAULT false)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_saldo numeric;
  v_moneda public.currency_code;
  v_ref_moneda public.currency_code;
  v_ref_cuenta uuid;
  v_ref_monto numeric;
  v_op_status text;
  v_op_cuenta uuid;
  v_link_count integer;
BEGIN
  IF auth.uid() IS NULL
     OR p_created_by IS DISTINCT FROM auth.uid()
     OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
     OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Acceso denegado para registrar movimiento de tesorería';
  END IF;
  IF p_monto IS NULL OR p_monto = 0 THEN
    RAISE EXCEPTION 'El monto no puede ser cero';
  END IF;
  IF p_tipo IS NULL OR p_tipo NOT IN ('INGRESO','EGRESO','AJUSTE','PAGO','COBRO') THEN
    RAISE EXCEPTION 'Tipo de movimiento no permitido';
  END IF;
  IF p_tipo IN ('INGRESO','EGRESO','AJUSTE')
     AND pg_catalog.btrim(coalesce(p_motivo, '')) = '' THEN
    RAISE EXCEPTION 'El movimiento requiere tipo y motivo';
  END IF;
  IF (p_tipo = 'INGRESO' AND p_monto <= 0)
     OR (p_tipo IN ('EGRESO','PAGO') AND p_monto >= 0)
     OR (p_tipo = 'COBRO' AND p_monto <= 0) THEN
    RAISE EXCEPTION 'El signo del monto no coincide con el tipo de movimiento';
  END IF;

  SELECT c.saldo, c.moneda INTO v_saldo, v_moneda
  FROM public.cuentas_financieras c
  WHERE c.id = p_cuenta_id AND c.empresa_id = p_empresa_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cuenta financiera no encontrada'; END IF;

  IF p_project_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.projects p WHERE p.id = p_project_id AND p.empresa_id = p_empresa_id
  ) THEN
    RAISE EXCEPTION 'La obra no pertenece a la empresa';
  END IF;

  IF p_payment_order_id IS NOT NULL THEN
    IF p_tipo <> 'PAGO' THEN
      RAISE EXCEPTION 'Orden de pago inválida para este movimiento';
    END IF;
    SELECT po.status, po.cuenta_id INTO v_op_status, v_op_cuenta
    FROM public.payment_orders po
    WHERE po.id = p_payment_order_id AND po.empresa_id = p_empresa_id
    FOR UPDATE;
    IF NOT FOUND OR v_op_status <> 'EJECUTADA' OR v_op_cuenta IS DISTINCT FROM p_cuenta_id THEN
      RAISE EXCEPTION 'La OP no está ejecutada con esta cuenta de tesorería';
    END IF;
    SELECT count(*) INTO v_link_count FROM public.payment_order_invoices poi
    WHERE poi.payment_order_id = p_payment_order_id AND poi.empresa_id = p_empresa_id;
    IF v_link_count = 0 OR EXISTS (
      SELECT 1
      FROM public.payment_order_invoices poi
      LEFT JOIN public.invoices i ON i.id = poi.invoice_id
      WHERE poi.payment_order_id = p_payment_order_id
        AND (poi.empresa_id IS DISTINCT FROM p_empresa_id
          OR i.id IS NULL OR i.empresa_id IS DISTINCT FROM p_empresa_id
          OR i.currency IS DISTINCT FROM v_moneda)
    ) THEN
      RAISE EXCEPTION 'La cuenta debe coincidir con la moneda de todas las facturas de la OP';
    END IF;
    SELECT coalesce(sum(i.total), 0) INTO v_ref_monto
    FROM public.payment_order_invoices poi
    JOIN public.invoices i ON i.id = poi.invoice_id
    WHERE poi.payment_order_id = p_payment_order_id AND poi.empresa_id = p_empresa_id
      AND i.empresa_id = p_empresa_id;
    IF p_monto <> -v_ref_monto THEN
      RAISE EXCEPTION 'El movimiento no coincide con el total de la OP';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.movimientos_tesoreria m
      WHERE m.payment_order_id = p_payment_order_id AND m.tipo = 'PAGO'
    ) THEN
      RAISE EXCEPTION 'La OP ya tiene un movimiento de pago en tesorería';
    END IF;
  ELSIF p_tipo = 'PAGO' THEN
    RAISE EXCEPTION 'Un movimiento PAGO requiere una OP de origen';
  END IF;

  IF p_sales_receipt_id IS NOT NULL THEN
    IF p_tipo <> 'COBRO' THEN RAISE EXCEPTION 'Referencia de cobro inválida'; END IF;
    SELECT d.currency, r.cuenta_id, r.amount
      INTO v_ref_moneda, v_ref_cuenta, v_ref_monto
    FROM public.sales_receipts r
    JOIN public.sales_documents d ON d.id = r.sales_document_id
    WHERE r.id = p_sales_receipt_id AND r.empresa_id = p_empresa_id
      AND d.empresa_id = p_empresa_id AND r.reversed_at IS NULL
    FOR UPDATE OF r;
    IF NOT FOUND THEN RAISE EXCEPTION 'Cobro no encontrado para la empresa'; END IF;
    IF v_ref_moneda IS DISTINCT FROM v_moneda
       OR v_ref_cuenta IS DISTINCT FROM p_cuenta_id
       OR v_ref_monto IS DISTINCT FROM p_monto THEN
      RAISE EXCEPTION 'La cuenta, moneda o monto no coincide con el cobro';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.movimientos_tesoreria m
      WHERE m.sales_receipt_id = p_sales_receipt_id AND m.tipo = 'COBRO'
    ) THEN
      RAISE EXCEPTION 'El cobro ya tiene un movimiento en tesorería';
    END IF;
  ELSIF p_tipo = 'COBRO' THEN
    RAISE EXCEPTION 'Un movimiento COBRO requiere su recibo de origen';
  END IF;

  IF p_monto < 0 AND NOT coalesce(p_permitir_negativo, false)
     AND v_saldo + p_monto < 0 THEN
    RAISE EXCEPTION 'Saldo insuficiente: disponible %, requerido %', v_saldo, pg_catalog.abs(p_monto);
  END IF;

  INSERT INTO public.movimientos_tesoreria (
    empresa_id, cuenta_id, fecha, monto, tipo, motivo,
    payment_order_id, sales_receipt_id, project_id, created_by
  ) VALUES (
    p_empresa_id, p_cuenta_id, coalesce(p_fecha, CURRENT_DATE), p_monto, p_tipo,
    nullif(pg_catalog.btrim(p_motivo), ''), p_payment_order_id, p_sales_receipt_id,
    p_project_id, p_created_by
  );
  RETURN v_saldo + p_monto;
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_stock_movimiento(p_empresa_id uuid, p_producto_id uuid, p_tipo text, p_cantidad numeric, p_referencia_tipo text DEFAULT NULL::text, p_referencia_id uuid DEFAULT NULL::uuid, p_notas text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_costo_unitario numeric DEFAULT NULL::numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_stock_actual   numeric;
  v_costo_promedio numeric;
  v_stock_nuevo    numeric;
  v_costo_nuevo    numeric;
  v_costo_mov      numeric;   -- costo_unitario que se registra en el movimiento
  v_costo_total    numeric;
begin
  -- Lock de fila para evitar race conditions
  select stock_actual, costo_promedio
    into v_stock_actual, v_costo_promedio
  from public.productos
  where id = p_producto_id and empresa_id = p_empresa_id
  for update;

  if not found then
    raise exception 'Producto no encontrado';
  end if;

  case p_tipo
    when 'ENTRADA' then
      v_stock_nuevo := v_stock_actual + p_cantidad;
      if p_costo_unitario is not null and v_stock_nuevo > 0 then
        v_costo_nuevo := (v_stock_actual * v_costo_promedio + p_cantidad * p_costo_unitario) / v_stock_nuevo;
        v_costo_mov   := p_costo_unitario;
      else
        v_costo_nuevo := v_costo_promedio;
        v_costo_mov   := coalesce(p_costo_unitario, v_costo_promedio);
      end if;

    when 'SALIDA' then
      if v_stock_actual < p_cantidad then
        raise exception 'Stock insuficiente: disponible %, solicitado %', v_stock_actual, p_cantidad;
      end if;
      v_stock_nuevo := v_stock_actual - p_cantidad;
      v_costo_nuevo := v_costo_promedio;              -- la salida no mueve el CPP
      v_costo_mov   := v_costo_promedio;

    when 'AJUSTE' then
      v_stock_nuevo := p_cantidad;                    -- absoluto
      v_costo_nuevo := coalesce(p_costo_unitario, v_costo_promedio);
      v_costo_mov   := v_costo_nuevo;

    else
      raise exception 'Tipo de movimiento inválido: %', p_tipo;
  end case;

  v_costo_total := (v_stock_nuevo * v_costo_nuevo) - (v_stock_actual * v_costo_promedio);

  update public.productos
  set stock_actual   = v_stock_nuevo,
      costo_promedio = v_costo_nuevo,
      updated_at     = now()
  where id = p_producto_id;

  insert into public.stock_movimientos
    (empresa_id, producto_id, tipo, cantidad, stock_resultante,
     costo_unitario, costo_total, costo_promedio_resultante,
     referencia_tipo, referencia_id, notas, created_by)
  values
    (p_empresa_id, p_producto_id, p_tipo, p_cantidad, v_stock_nuevo,
     round(v_costo_mov, 4), round(v_costo_total, 2), round(v_costo_nuevo, 4),
     p_referencia_tipo, p_referencia_id, p_notas, p_created_by);

  return v_stock_nuevo;
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_transferencia(p_empresa_id uuid, p_cuenta_origen_id uuid, p_cuenta_destino_id uuid, p_monto_origen numeric, p_monto_destino numeric DEFAULT NULL::numeric, p_fecha date DEFAULT NULL::date, p_motivo text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_transfer_id uuid;
  v_saldo_origen numeric;
  v_moneda_origen public.currency_code;
  v_moneda_destino public.currency_code;
  v_monto_destino numeric := coalesce(p_monto_destino, p_monto_origen);
  v_lock_row record;
BEGIN
  IF auth.uid() IS NULL
     OR p_created_by IS DISTINCT FROM auth.uid()
     OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
     OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Acceso denegado para registrar transferencia';
  END IF;
  IF p_cuenta_origen_id IS NULL OR p_cuenta_destino_id IS NULL
     OR p_cuenta_origen_id = p_cuenta_destino_id
     OR p_monto_origen IS NULL OR p_monto_origen <= 0
     OR v_monto_destino IS NULL OR v_monto_destino <= 0 THEN
    RAISE EXCEPTION 'Cuentas y montos de transferencia inválidos';
  END IF;

  FOR v_lock_row IN
    SELECT c.id FROM public.cuentas_financieras c
    WHERE c.empresa_id = p_empresa_id
      AND c.id IN (p_cuenta_origen_id, p_cuenta_destino_id)
    ORDER BY c.id
    FOR UPDATE
  LOOP
    NULL;
  END LOOP;

  SELECT saldo, moneda INTO v_saldo_origen, v_moneda_origen
  FROM public.cuentas_financieras
  WHERE id = p_cuenta_origen_id AND empresa_id = p_empresa_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cuenta origen no encontrada'; END IF;

  SELECT moneda INTO v_moneda_destino
  FROM public.cuentas_financieras
  WHERE id = p_cuenta_destino_id AND empresa_id = p_empresa_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cuenta destino no encontrada'; END IF;

  IF v_moneda_origen = v_moneda_destino AND v_monto_destino <> p_monto_origen THEN
    RAISE EXCEPTION 'Entre cuentas de la misma moneda, los montos deben coincidir';
  END IF;
  IF v_moneda_origen <> v_moneda_destino AND p_monto_destino IS NULL THEN
    RAISE EXCEPTION 'La transferencia entre monedas requiere monto de destino explícito';
  END IF;
  IF v_saldo_origen < p_monto_origen THEN
    RAISE EXCEPTION 'Saldo insuficiente en la cuenta origen: disponible %, requerido %',
      v_saldo_origen, p_monto_origen;
  END IF;

  INSERT INTO public.transferencias (
    empresa_id, cuenta_origen_id, cuenta_destino_id, monto_origen, monto_destino,
    tipo_cambio, fecha, motivo, created_by
  ) VALUES (
    p_empresa_id, p_cuenta_origen_id, p_cuenta_destino_id, p_monto_origen, v_monto_destino,
    CASE WHEN v_moneda_origen = v_moneda_destino THEN 1
      ELSE pg_catalog.round(v_monto_destino / p_monto_origen, 6) END,
    coalesce(p_fecha, CURRENT_DATE), nullif(pg_catalog.btrim(p_motivo), ''), p_created_by
  ) RETURNING id INTO v_transfer_id;

  INSERT INTO public.movimientos_tesoreria (
    empresa_id, cuenta_id, fecha, monto, tipo, motivo, transferencia_id, created_by
  ) VALUES
    (p_empresa_id, p_cuenta_origen_id, coalesce(p_fecha, CURRENT_DATE), -p_monto_origen,
      'TRANSFERENCIA_OUT', nullif(pg_catalog.btrim(p_motivo), ''), v_transfer_id, p_created_by),
    (p_empresa_id, p_cuenta_destino_id, coalesce(p_fecha, CURRENT_DATE), v_monto_destino,
      'TRANSFERENCIA_IN', nullif(pg_catalog.btrim(p_motivo), ''), v_transfer_id, p_created_by);

  RETURN v_transfer_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_quotation(p_token_hash text, p_reason text DEFAULT NULL::text, p_actor_name text DEFAULT NULL::text, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tok public.sales_quotation_tokens%ROWTYPE;
  v_doc public.sales_documents%ROWTYPE;
BEGIN
  IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Enlace inválido.'; END IF;
  SELECT * INTO v_tok FROM public.sales_quotation_tokens WHERE token_hash = p_token_hash FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Enlace inválido.'; END IF;
  IF v_tok.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'Este enlace fue revocado.'; END IF;

  SELECT * INTO v_doc FROM public.sales_documents WHERE id = v_tok.sales_document_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cotización no encontrada.'; END IF;
  IF v_tok.empresa_id IS DISTINCT FROM v_doc.empresa_id THEN
    RAISE EXCEPTION 'Enlace inválido.';
  END IF;
  -- El rechazo nunca crea OT: esta función no inserta en work_orders ni en
  -- sales_quotation_acceptances. Verificable por inspección.
  IF v_doc.acceptance_status = 'ACCEPTED' THEN RAISE EXCEPTION 'Esta cotización ya fue aceptada y no se puede rechazar.'; END IF;
  IF EXISTS (SELECT 1 FROM public.work_orders WHERE sales_document_id = v_doc.id) THEN
    RAISE EXCEPTION 'Esta cotización ya generó una Orden de Trabajo y no se puede rechazar.';
  END IF;
  IF v_doc.acceptance_status = 'REJECTED' THEN
    RETURN jsonb_build_object('sales_document_id', v_doc.id, 'already_rejected', true);
  END IF;
  IF v_doc.acceptance_status <> 'PENDING_ACCEPTANCE' THEN
    RAISE EXCEPTION 'Esta cotización no está pendiente de aceptación.';
  END IF;
  IF v_tok.quotation_version IS DISTINCT FROM v_doc.quotation_version THEN
    RAISE EXCEPTION 'La cotización fue actualizada por la empresa. Pedí el nuevo enlace.';
  END IF;

  UPDATE public.sales_documents SET
    acceptance_status = 'REJECTED',
    rejected_at = now(),
    rejection_reason = NULLIF(btrim(COALESCE(p_reason, '')), '')
  WHERE id = v_doc.id;

  INSERT INTO public.sales_quotation_events
    (empresa_id, sales_document_id, token_id, event_type, actor_label, actor_ip, actor_user_agent, detail)
  VALUES (v_doc.empresa_id, v_doc.id, v_tok.id, 'REJECTED',
    COALESCE(NULLIF(btrim(COALESCE(p_actor_name, '')), ''), 'cliente'), p_ip, p_user_agent,
    jsonb_build_object('reason', p_reason, 'quotation_version', v_doc.quotation_version));

  RETURN jsonb_build_object('sales_document_id', v_doc.id, 'already_rejected', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_subcontractor_certificate_atomically(p_empresa_id uuid, p_certificate_id uuid, p_notes text, p_actor_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_project_id uuid;
  v_status text;
BEGIN
  IF auth.uid() IS NULL
     OR p_actor_id IS DISTINCT FROM auth.uid()
     OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
     OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Acceso denegado para rechazar certificado de subcontratista';
  END IF;
  SELECT sc.project_id, sc.status INTO v_project_id, v_status
  FROM public.subcontractor_certificates sc
  JOIN public.projects p ON p.id = sc.project_id AND p.empresa_id = p_empresa_id
  WHERE sc.id = p_certificate_id
  FOR UPDATE OF sc;
  IF NOT FOUND THEN RAISE EXCEPTION 'Certificado no encontrado para la empresa'; END IF;
  IF v_status = 'RECHAZADO' THEN RETURN p_certificate_id; END IF;
  IF v_status <> 'PENDIENTE' THEN RAISE EXCEPTION 'Solo se puede rechazar un certificado pendiente'; END IF;

  UPDATE public.subcontractor_certificates sc
  SET status = 'RECHAZADO', notes = p_notes
  WHERE sc.id = p_certificate_id AND sc.project_id = v_project_id AND sc.status = 'PENDIENTE';
  IF NOT FOUND THEN RAISE EXCEPTION 'El certificado cambió durante el rechazo'; END IF;
  RETURN p_certificate_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.release_plan_reservations(p_empresa_id uuid, p_actor_id uuid, p_plan_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_empresa_id UUID := public.assert_mrp_actor(p_empresa_id, p_actor_id);
  v_count INTEGER := 0;
BEGIN
  PERFORM 1 FROM public.project_weekly_plans
    WHERE id = p_plan_id AND empresa_id = v_empresa_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Plan no encontrado o sin permisos';
  END IF;

  UPDATE public.inventory_reservations
    SET status = 'RELEASED', released_at = now()
    WHERE weekly_plan_id = p_plan_id AND status = 'ACTIVE' AND empresa_id = v_empresa_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object('ok', true, 'released', v_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.reserve_plan_stock(p_empresa_id uuid, p_actor_id uuid, p_project_id uuid, p_plan_id uuid, p_location_id uuid, p_items jsonb, p_needed_by date, p_idempotency_key text, p_replace boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_empresa_id UUID := public.assert_mrp_actor(p_empresa_id, p_actor_id);
  v_item JSONB;
  v_prod UUID;
  v_qty NUMERIC;
  v_fisico NUMERIC;
  v_reservado NUMERIC;
  v_disp NUMERIC;
  v_key TEXT;
  v_existing UUID;
  v_short JSONB := '[]'::jsonb;
BEGIN
  PERFORM 1 FROM public.projects
    WHERE id = p_project_id AND empresa_id = v_empresa_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Proyecto no encontrado o sin permisos';
  END IF;

  PERFORM 1 FROM public.inventory_locations
    WHERE id = p_location_id AND empresa_id = v_empresa_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Depósito no encontrado o sin permisos';
  END IF;

  IF p_plan_id IS NOT NULL THEN
    PERFORM 1 FROM public.project_weekly_plans
      WHERE id = p_plan_id AND empresa_id = v_empresa_id AND project_id = p_project_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Plan no encontrado o sin permisos';
    END IF;
    IF p_replace THEN
      UPDATE public.inventory_reservations
        SET status = 'RELEASED', released_at = now()
        WHERE weekly_plan_id = p_plan_id AND status = 'ACTIVE' AND empresa_id = v_empresa_id;
    END IF;
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb)) LOOP
    v_prod := NULLIF(v_item ->> 'producto_id', '')::uuid;
    v_qty := NULLIF(v_item ->> 'quantity', '')::numeric;
    IF v_prod IS NULL OR v_qty IS NULL OR v_qty <= 0 THEN
      CONTINUE;
    END IF;

    PERFORM pg_advisory_xact_lock(hashtext(v_empresa_id::text || ':' || v_prod::text || ':' || p_location_id::text));

    PERFORM 1 FROM public.productos
      WHERE id = v_prod AND empresa_id = v_empresa_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Producto no encontrado o sin permisos';
    END IF;

    IF p_plan_id IS NOT NULL THEN
      SELECT id INTO v_existing FROM public.inventory_reservations
        WHERE weekly_plan_id = p_plan_id AND producto_id = v_prod
          AND location_id = p_location_id AND status = 'ACTIVE'
          AND empresa_id = v_empresa_id
        LIMIT 1;
      IF FOUND THEN
        CONTINUE;
      END IF;
    END IF;

    SELECT COALESCE(SUM(quantity), 0) INTO v_fisico
      FROM public.inventory_balances
      WHERE empresa_id = v_empresa_id AND location_id = p_location_id AND producto_id = v_prod;
    PERFORM 1 FROM public.inventory_balances
      WHERE empresa_id = v_empresa_id AND location_id = p_location_id AND producto_id = v_prod
      FOR UPDATE;

    PERFORM 1 FROM public.inventory_reservations
      WHERE empresa_id = v_empresa_id AND location_id = p_location_id
        AND producto_id = v_prod AND status = 'ACTIVE'
      FOR UPDATE;
    SELECT COALESCE(SUM(quantity), 0) INTO v_reservado
      FROM public.inventory_reservations
      WHERE empresa_id = v_empresa_id AND location_id = p_location_id
        AND producto_id = v_prod AND status = 'ACTIVE';

    v_disp := v_fisico - v_reservado;
    IF v_disp < v_qty THEN
      v_short := v_short || jsonb_build_object(
        'producto_id', v_prod, 'solicitado', v_qty, 'disponible', v_disp
      );
    ELSE
      v_key := CASE WHEN p_idempotency_key IS NULL THEN NULL
        ELSE p_idempotency_key || ':' || v_prod::text END;
      INSERT INTO public.inventory_reservations
        (empresa_id, location_id, producto_id, project_id, weekly_plan_id,
         quantity, status, needed_by_date, idempotency_key, created_by)
      VALUES
        (v_empresa_id, p_location_id, v_prod, p_project_id, p_plan_id,
         v_qty, 'ACTIVE', p_needed_by, v_key, p_actor_id);
    END IF;
  END LOOP;

  IF jsonb_array_length(v_short) > 0 THEN
    RAISE EXCEPTION 'Stock central insuficiente: %', v_short::text;
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_work_order_policy(p_empresa_id uuid, p_client_id uuid, p_project_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(mode work_order_approval_mode, policy_id uuid, scope text, responsible_role user_role)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record;
BEGIN
  IF p_project_id IS NOT NULL THEN
    SELECT p.mode, p.id, p.scope, p.responsible_role INTO r
    FROM public.work_order_routing_policies p
    WHERE p.empresa_id = p_empresa_id AND p.scope = 'PROJECT' AND p.project_id = p_project_id;
    IF FOUND THEN mode := r.mode; policy_id := r.id; scope := r.scope; responsible_role := r.responsible_role; RETURN NEXT; RETURN; END IF;
  END IF;
  SELECT p.mode, p.id, p.scope, p.responsible_role INTO r
  FROM public.work_order_routing_policies p
  WHERE p.empresa_id = p_empresa_id AND p.scope = 'CLIENT' AND p.client_id = p_client_id;
  IF FOUND THEN mode := r.mode; policy_id := r.id; scope := r.scope; responsible_role := r.responsible_role; RETURN NEXT; RETURN; END IF;
  SELECT p.mode, p.id, p.scope, p.responsible_role INTO r
  FROM public.work_order_routing_policies p
  WHERE p.empresa_id = p_empresa_id AND p.scope = 'TENANT_DEFAULT';
  IF FOUND THEN mode := r.mode; policy_id := r.id; scope := r.scope; responsible_role := r.responsible_role; RETURN NEXT; RETURN; END IF;
  -- Fail-safe: sin configuración no hay pase directo a producción.
  mode := 'RESPONSIBLE_APPROVAL'; policy_id := NULL; scope := 'SYSTEM_DEFAULT'; responsible_role := 'administracion';
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.resync_project_certificate_quantities_atomically(p_empresa_id uuid, p_certificate_id uuid, p_actor_id uuid, p_updates jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_project_id uuid;
  v_status text;
  v_input_count integer;
  v_distinct_count integer;
  v_expected_count integer;
  v_updated_count integer;
  v_monto_anterior numeric;
  v_monto_presente numeric;
BEGIN
  IF auth.uid() IS NULL
     OR p_actor_id IS DISTINCT FROM auth.uid()
     OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
     OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Acceso denegado para recalcular certificado';
  END IF;
  IF p_updates IS NULL OR pg_catalog.jsonb_typeof(p_updates) <> 'array' THEN
    RAISE EXCEPTION 'La lista de cantidades no es válida';
  END IF;

  SELECT c.project_id, c.status::text INTO v_project_id, v_status
  FROM public.project_certificates c
  JOIN public.projects p ON p.id = c.project_id AND p.empresa_id = p_empresa_id
  WHERE c.id = p_certificate_id
  FOR UPDATE OF c;
  IF NOT FOUND THEN RAISE EXCEPTION 'Certificado no encontrado para la empresa'; END IF;
  IF v_status <> 'BORRADOR' THEN
    RAISE EXCEPTION 'El certificado ya está elaborado y no se puede editar';
  END IF;

  SELECT count(*), count(DISTINCT u.item_id)
    INTO v_input_count, v_distinct_count
  FROM pg_catalog.jsonb_to_recordset(p_updates)
    AS u(item_id uuid, qty_anterior numeric, qty_presente numeric);
  IF v_input_count <> v_distinct_count THEN
    RAISE EXCEPTION 'La lista contiene líneas duplicadas';
  END IF;
  IF EXISTS (
    SELECT 1 FROM pg_catalog.jsonb_to_recordset(p_updates)
      AS u(item_id uuid, qty_anterior numeric, qty_presente numeric)
    WHERE u.item_id IS NULL OR u.qty_anterior IS NULL OR u.qty_presente IS NULL
      OR u.qty_anterior < 0 OR u.qty_presente < 0
  ) THEN
    RAISE EXCEPTION 'Las cantidades deben ser válidas y no negativas';
  END IF;

  SELECT count(*) INTO v_expected_count
  FROM public.project_certificate_items i
  WHERE i.certificate_id = p_certificate_id AND i.budget_item_id IS NOT NULL;
  IF v_input_count <> v_expected_count THEN
    RAISE EXCEPTION 'La lista de cantidades no coincide con las líneas del certificado';
  END IF;

  UPDATE public.project_certificate_items i
  SET qty_anterior = u.qty_anterior,
      qty_presente = u.qty_presente
  FROM pg_catalog.jsonb_to_recordset(p_updates)
    AS u(item_id uuid, qty_anterior numeric, qty_presente numeric)
  WHERE i.id = u.item_id AND i.certificate_id = p_certificate_id
    AND i.budget_item_id IS NOT NULL;
  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  IF v_updated_count <> v_input_count THEN
    RAISE EXCEPTION 'Cambió una línea durante el recálculo del certificado';
  END IF;

  SELECT coalesce(sum(i.monto_anterior), 0), coalesce(sum(i.monto_presente), 0)
    INTO v_monto_anterior, v_monto_presente
  FROM public.project_certificate_items i
  WHERE i.certificate_id = p_certificate_id;
  UPDATE public.project_certificates c
  SET monto_anterior = v_monto_anterior,
      monto_presente = v_monto_presente
  WHERE c.id = p_certificate_id AND c.project_id = v_project_id AND c.status = 'BORRADOR';
  IF NOT FOUND THEN RAISE EXCEPTION 'El certificado cambió durante el recálculo'; END IF;

  RETURN v_updated_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.revert_project_certificate_status_atomically(p_certificate_id uuid, p_expected_status text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_project_id uuid;
  v_numero integer;
  v_status text;
  v_target_status text;
BEGIN
  IF v_user_id IS NULL OR NOT public.is_internal_role(ARRAY['admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Solo administración puede retroceder un certificado';
  END IF;
  SELECT p.id INTO v_project_id
  FROM public.projects p JOIN public.project_certificates c ON c.project_id = p.id
  WHERE c.id = p_certificate_id AND p.empresa_id = public.current_empresa_id()
  FOR UPDATE OF p;
  IF NOT FOUND THEN RAISE EXCEPTION 'Certificado no encontrado para la empresa'; END IF;
  SELECT c.numero, c.status::text INTO v_numero, v_status
  FROM public.project_certificates c WHERE c.id = p_certificate_id AND c.project_id = v_project_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Certificado no encontrado para la empresa'; END IF;
  IF v_status IS DISTINCT FROM p_expected_status THEN
    RAISE EXCEPTION 'El certificado cambió de estado; actualizá la pantalla e intentá de nuevo';
  END IF;
  v_target_status := CASE v_status WHEN 'ELABORADO' THEN 'BORRADOR' WHEN 'VERIFICADO' THEN 'ELABORADO'
    WHEN 'APROBADO' THEN 'VERIFICADO' WHEN 'FACTURADO' THEN 'APROBADO' ELSE NULL END;
  IF v_target_status IS NULL THEN RAISE EXCEPTION 'El certificado está en borrador, no se puede retroceder'; END IF;
  IF v_status IN ('APROBADO', 'FACTURADO') AND EXISTS (
    SELECT 1 FROM public.project_certificates later WHERE later.project_id = v_project_id AND later.numero > v_numero) THEN
    RAISE EXCEPTION 'Existe un certificado posterior que depende de este';
  END IF;
  INSERT INTO private.project_certificate_transition_authorizations (transaction_id, certificate_id, user_id, from_status, to_status)
  VALUES (pg_catalog.txid_current(), p_certificate_id, v_user_id, v_status, v_target_status);
  IF v_status = 'ELABORADO' THEN
    UPDATE public.project_certificates SET status = v_target_status, elaborado_por = NULL, elaborado_at = NULL, closed_at = NULL,
      devolucion_anticipo_pct_snap = NULL, retencion_pct_snap = NULL WHERE id = p_certificate_id;
  ELSIF v_status = 'VERIFICADO' THEN
    UPDATE public.project_certificates SET status = v_target_status, verificado_por = NULL, verificado_at = NULL WHERE id = p_certificate_id;
  ELSIF v_status = 'APROBADO' THEN
    UPDATE public.project_certificates SET status = v_target_status, aprobado_por = NULL, aprobado_at = NULL WHERE id = p_certificate_id;
  ELSE
    UPDATE public.project_certificates SET status = v_target_status, facturado_at = NULL, factura_numero = NULL WHERE id = p_certificate_id;
  END IF;
  RETURN v_target_status;
END;
$function$

CREATE OR REPLACE FUNCTION public.revertir_cobro_atomico(p_empresa_id uuid, p_sales_receipt_id uuid, p_reversal_reason text, p_created_by uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_doc_id uuid;
  v_receipt public.sales_receipts;
  v_original record;
  v_reversal_id uuid;
  v_first_reversal_id uuid;
  v_reversed_any boolean := false;
  v_reason text := pg_catalog.btrim(coalesce(p_reversal_reason, ''));
BEGIN
  IF auth.uid() IS NULL
     OR p_created_by IS DISTINCT FROM auth.uid()
     OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
     OR NOT public.is_internal_role(ARRAY['administracion','admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Acceso denegado para revertir cobro';
  END IF;
  IF v_reason = '' THEN RAISE EXCEPTION 'El motivo de reversa es obligatorio'; END IF;

  SELECT r.sales_document_id INTO v_doc_id
  FROM public.sales_receipts r
  WHERE r.id = p_sales_receipt_id AND r.empresa_id = p_empresa_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cobro no encontrado para la empresa'; END IF;

  PERFORM 1 FROM public.sales_documents d
  WHERE d.id = v_doc_id AND d.empresa_id = p_empresa_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Documento de venta no encontrado para la empresa'; END IF;

  SELECT * INTO v_receipt FROM public.sales_receipts r
  WHERE r.id = p_sales_receipt_id AND r.sales_document_id = v_doc_id
    AND r.empresa_id = p_empresa_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cobro no encontrado para la empresa'; END IF;
  IF v_receipt.reversed_at IS NOT NULL THEN RETURN v_receipt.id; END IF;

  FOR v_original IN
    SELECT m.id, m.cuenta_id, m.monto, m.empresa_id, c.moneda, d.currency AS document_currency
    FROM public.movimientos_tesoreria m
    JOIN public.cuentas_financieras c ON c.id = m.cuenta_id AND c.empresa_id = m.empresa_id
    JOIN public.sales_documents d ON d.id = v_doc_id AND d.empresa_id = p_empresa_id
    WHERE m.sales_receipt_id = p_sales_receipt_id AND m.empresa_id = p_empresa_id
      AND m.tipo = 'COBRO'
    ORDER BY m.id
    FOR UPDATE OF m, c
  LOOP
    IF v_original.moneda IS DISTINCT FROM v_original.document_currency THEN
      RAISE EXCEPTION 'La cuenta del movimiento original no coincide con la moneda del documento';
    END IF;
    INSERT INTO public.movimientos_tesoreria (
      empresa_id, cuenta_id, fecha, monto, tipo, motivo,
      sales_receipt_id, reversal_of_movement_id, created_by
    ) VALUES (
      p_empresa_id, v_original.cuenta_id, CURRENT_DATE, -v_original.monto, 'AJUSTE',
      'Reversa de cobro: ' || v_reason, p_sales_receipt_id, v_original.id, p_created_by
    ) RETURNING id INTO v_reversal_id;
    IF v_first_reversal_id IS NULL THEN v_first_reversal_id := v_reversal_id; END IF;
    v_reversed_any := true;
  END LOOP;

  IF v_receipt.cuenta_id IS NOT NULL AND NOT v_reversed_any THEN
    RAISE EXCEPTION 'El cobro tiene cuenta asignada pero no se encontró su movimiento de tesorería';
  END IF;

  UPDATE public.sales_receipts r
  SET reversed_at = pg_catalog.now(),
      reversed_by = p_created_by,
      reversal_reason = v_reason,
      reversal_movement_id = v_first_reversal_id
  WHERE r.id = p_sales_receipt_id AND r.empresa_id = p_empresa_id AND r.reversed_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'El cobro cambió durante la reversa'; END IF;
  RETURN p_sales_receipt_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_production_recipe_atomic(p_empresa_id uuid, p_actor_id uuid, p_recipe_id uuid, p_project_id uuid, p_code text, p_name text, p_production_unit text, p_description text, p_contract_total_quantity numeric, p_source_type text, p_source_file_name text, p_components jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_empresa_id UUID := public.assert_mrp_actor(p_empresa_id, p_actor_id);
  v_recipe_id UUID;
  v_item JSONB;
  v_item_id UUID;
  v_qty NUMERIC;
  v_count INTEGER;
BEGIN
  IF p_code IS NULL OR btrim(p_code) = '' THEN
    RAISE EXCEPTION 'Código de receta requerido';
  END IF;
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'Nombre de receta requerido';
  END IF;
  IF p_production_unit IS NULL OR btrim(p_production_unit) = '' THEN
    RAISE EXCEPTION 'Unidad de producción requerida';
  END IF;
  IF p_source_type NOT IN ('EXCEL', 'BIM', 'MANUAL') THEN
    RAISE EXCEPTION 'source_type inválido';
  END IF;

  PERFORM 1 FROM public.projects
    WHERE id = p_project_id AND empresa_id = v_empresa_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Proyecto no encontrado o sin permisos';
  END IF;

  IF p_components IS NULL OR jsonb_array_length(p_components) = 0 THEN
    RAISE EXCEPTION 'La receta necesita al menos un componente';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_components) LOOP
    v_item_id := NULLIF(v_item ->> 'budget_item_id', '')::uuid;
    v_qty := NULLIF(v_item ->> 'quantity_per_unit', '')::numeric;
    IF v_item_id IS NULL THEN
      RAISE EXCEPTION 'Componente sin partida válida';
    END IF;
    IF v_qty IS NULL OR v_qty <= 0 THEN
      RAISE EXCEPTION 'Cantidad por unidad debe ser > 0';
    END IF;
    SELECT COUNT(*) INTO v_count FROM public.budget_items bi
      JOIN public.projects p ON p.id = bi.project_id
      WHERE bi.id = v_item_id
        AND bi.project_id = p_project_id
        AND p.empresa_id = v_empresa_id;
    IF v_count <> 1 THEN
      RAISE EXCEPTION 'Partida no pertenece a este proyecto/empresa: %', v_item_id;
    END IF;
  END LOOP;

  IF p_recipe_id IS NOT NULL THEN
    SELECT id INTO v_recipe_id FROM public.production_recipes
      WHERE id = p_recipe_id AND project_id = p_project_id AND empresa_id = v_empresa_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Receta no encontrada o sin permisos';
    END IF;
    UPDATE public.production_recipes SET
      code = btrim(p_code),
      name = btrim(p_name),
      production_unit = btrim(p_production_unit),
      description = NULLIF(btrim(COALESCE(p_description, '')), ''),
      contract_total_quantity = p_contract_total_quantity,
      source_type = p_source_type,
      source_file_name = NULLIF(btrim(COALESCE(p_source_file_name, '')), ''),
      updated_at = now()
      WHERE id = v_recipe_id;
    DELETE FROM public.production_recipe_components WHERE recipe_id = v_recipe_id;
  ELSE
    INSERT INTO public.production_recipes
      (empresa_id, project_id, code, name, production_unit, description,
       contract_total_quantity, source_type, source_file_name, active, created_by)
    VALUES
      (v_empresa_id, p_project_id, btrim(p_code), btrim(p_name), btrim(p_production_unit),
       NULLIF(btrim(COALESCE(p_description, '')), ''),
       p_contract_total_quantity, p_source_type,
       NULLIF(btrim(COALESCE(p_source_file_name, '')), ''), true, p_actor_id)
    RETURNING id INTO v_recipe_id;
  END IF;

  INSERT INTO public.production_recipe_components
    (recipe_id, budget_item_id, quantity_per_production_unit, unit, sort_order)
  SELECT
    v_recipe_id,
    (v ->> 'budget_item_id')::uuid,
    (v ->> 'quantity_per_unit')::numeric,
    COALESCE(NULLIF(btrim(v ->> 'unit'), ''), 'unid'),
    (row_number() OVER ())::integer - 1
  FROM jsonb_array_elements(p_components) WITH ORDINALITY AS t(v, ord)
  ORDER BY ord;

  RETURN jsonb_build_object('recipe_id', v_recipe_id, 'status', 'SUCCESS');
END;
$function$

CREATE OR REPLACE FUNCTION public.save_weekly_plan_atomic(p_plan_id uuid, p_project_id uuid, p_start_date date, p_end_date date, p_status text, p_notes text, p_items jsonb, p_weather_snapshot_batch_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_empresa_id UUID;
  v_plan_id UUID;
  v_item JSONB;
  v_budget_item_id UUID;
  v_front_label TEXT;
  v_input_mode TEXT;
  v_input_value NUMERIC;
  v_nominal_qty NUMERIC;
  v_target_qty NUMERIC;
  v_remaining_qty NUMERIC;
  v_unit TEXT;
  v_exists BOOLEAN;
  v_contractual_qty NUMERIC;
  v_executed_qty NUMERIC;
BEGIN
  -- Validar empresa_id del invocador: FAIL-CLOSED estricto (no fallback)
  v_empresa_id := public.current_empresa_id();
  IF v_empresa_id IS NULL THEN
    RAISE EXCEPTION 'Acceso denegado: se requiere usuario autenticado con empresa asignada.';
  END IF;

  -- Validar pertenencia del proyecto a la empresa del usuario
  SELECT EXISTS(
    SELECT 1 FROM public.projects
    WHERE id = p_project_id AND empresa_id = v_empresa_id
  ) INTO v_exists;

  IF NOT v_exists THEN
    RAISE EXCEPTION 'Proyecto % no encontrado o no pertenece a la empresa.', p_project_id;
  END IF;

  -- Validar rango de fechas
  IF p_end_date < p_start_date THEN
    RAISE EXCEPTION 'La fecha de fin (%) no puede ser anterior a la de inicio (%).', p_end_date, p_start_date;
  END IF;

  -- Validar o crear cabecera del plan
  IF p_plan_id IS NOT NULL THEN
    SELECT id INTO v_plan_id
    FROM public.project_weekly_plans
    WHERE id = p_plan_id AND empresa_id = v_empresa_id;

    IF v_plan_id IS NULL THEN
      RAISE EXCEPTION 'Plan semanal % no encontrado o sin permisos.', p_plan_id;
    END IF;

    UPDATE public.project_weekly_plans
    SET start_date = p_start_date,
        end_date = p_end_date,
        status = p_status,
        notes = p_notes,
        weather_snapshot_batch_id = coalesce(p_weather_snapshot_batch_id, weather_snapshot_batch_id),
        updated_at = now()
    WHERE id = v_plan_id;
  ELSE
    INSERT INTO public.project_weekly_plans (
      empresa_id,
      project_id,
      start_date,
      end_date,
      status,
      notes,
      weather_snapshot_batch_id,
      created_by
    ) VALUES (
      v_empresa_id,
      p_project_id,
      p_start_date,
      p_end_date,
      p_status,
      p_notes,
      p_weather_snapshot_batch_id,
      auth.uid()
    ) RETURNING id INTO v_plan_id;
  END IF;

  -- Asegurar limpieza de tabla temporal en llamadas repetidas dentro de la misma transacción
  DROP TABLE IF EXISTS tmp_item_budget_tracking;
  CREATE TEMP TABLE tmp_item_budget_tracking (
    budget_item_id UUID PRIMARY KEY,
    contractual_qty NUMERIC,
    executed_qty NUMERIC,
    remaining_qty NUMERIC
  ) ON COMMIT DROP;

  -- Pre-cargar partidas referenciadas en el payload para controlar capping multi-frente
  IF p_items IS NOT NULL AND jsonb_typeof(p_items) = 'array' THEN
    INSERT INTO tmp_item_budget_tracking (budget_item_id, contractual_qty, executed_qty, remaining_qty)
    SELECT
      b.id,
      coalesce(b.quantity, 0),
      coalesce(sum(ee.quantity_executed), 0),
      greatest(0, coalesce(b.quantity, 0) - coalesce(sum(ee.quantity_executed), 0))
    FROM (
      SELECT DISTINCT (elem->>'budget_item_id')::UUID AS b_id
      FROM jsonb_array_elements(p_items) elem
      WHERE (elem->>'budget_item_id') IS NOT NULL
    ) raw_ids
    JOIN public.budget_items b ON b.id = raw_ids.b_id AND b.project_id = p_project_id
    LEFT JOIN public.execution_entries ee ON ee.budget_item_id = b.id AND ee.project_id = p_project_id
    GROUP BY b.id, b.quantity
    ON CONFLICT (budget_item_id) DO NOTHING;
  END IF;

  -- Eliminar items actuales del plan dentro de la misma transacción
  DELETE FROM public.project_weekly_plan_items
  WHERE plan_id = v_plan_id;

  -- Insertar items validados y calcular target_quantity contractual
  IF p_items IS NOT NULL AND jsonb_typeof(p_items) = 'array' THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      v_budget_item_id := (v_item->>'budget_item_id')::UUID;
      v_front_label := NULLIF(trim(v_item->>'front_label'), '');
      v_input_mode := v_item->>'input_mode';
      v_input_value := (v_item->>'input_value')::NUMERIC;
      v_unit := coalesce(v_item->>'unit', 'unid');

      -- Validar que la partida pertenece a este proyecto
      IF NOT EXISTS (
        SELECT 1 FROM tmp_item_budget_tracking
        WHERE budget_item_id = v_budget_item_id
      ) THEN
        RAISE EXCEPTION 'La partida % no pertenece al proyecto %.', v_budget_item_id, p_project_id;
      END IF;

      -- Validar input_mode
      IF v_input_mode NOT IN ('QUANTITY', 'CONTRACT_PERCENTAGE_POINTS') THEN
        RAISE EXCEPTION 'Modo de entrada inválido: %', v_input_mode;
      END IF;

      -- Validar input_value
      IF v_input_value < 0 THEN
        RAISE EXCEPTION 'El valor de meta no puede ser negativo: %', v_input_value;
      END IF;

      IF v_input_value > 0 THEN
        SELECT contractual_qty, remaining_qty
        INTO v_contractual_qty, v_remaining_qty
        FROM tmp_item_budget_tracking
        WHERE budget_item_id = v_budget_item_id;

        -- Conversión semántica de target_quantity
        IF v_input_mode = 'CONTRACT_PERCENTAGE_POINTS' THEN
          v_nominal_qty := v_contractual_qty * (v_input_value / 100.0);
        ELSE
          v_nominal_qty := v_input_value;
        END IF;

        -- Capping por remanente disponible (para frentes acumulados)
        v_target_qty := greatest(0, least(v_nominal_qty, v_remaining_qty));

        -- Reducir el saldo remanente disponible para siguientes frentes de la misma partida
        UPDATE tmp_item_budget_tracking
        SET remaining_qty = greatest(0, remaining_qty - v_target_qty)
        WHERE budget_item_id = v_budget_item_id;

        INSERT INTO public.project_weekly_plan_items (
          plan_id,
          budget_item_id,
          front_label,
          input_mode,
          input_value,
          target_quantity,
          unit
        ) VALUES (
          v_plan_id,
          v_budget_item_id,
          v_front_label,
          v_input_mode,
          v_input_value,
          v_target_qty,
          v_unit
        );
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'plan_id', v_plan_id,
    'status', 'SUCCESS'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.scan_pin_check_actor_lock(p_actor_key text)
 RETURNS TABLE(is_locked boolean, locked_until timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := clock_timestamp();
  v_row record;
begin
  select * into v_row from public.scan_pin_attempts where actor_key = p_actor_key;
  if found and v_row.locked_until is not null and v_row.locked_until > v_now then
    return query select true, v_row.locked_until;
  else
    return query select false, null::timestamptz;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.select_and_authorize_offer_atomically(p_empresa_id uuid, p_actor_id uuid, p_rfq_id uuid, p_rfq_provider_id uuid, p_quote_version_id uuid, p_selection_reason selection_reason DEFAULT NULL::selection_reason, p_selection_reason_detail text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_rfq public.rfqs;
  v_rp record;
  v_quote public.quote_versions;
  v_order_id uuid;
  v_lowest_competing_price numeric;
  v_is_cheapest boolean;
BEGIN
  IF auth.uid() IS NULL
     OR p_actor_id IS DISTINCT FROM auth.uid()
     OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
     OR NOT public.is_internal_role(ARRAY['comercial','admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Acceso denegado para autorizar oferta';
  END IF;

  SELECT * INTO v_rfq FROM public.rfqs r
  WHERE r.id = p_rfq_id AND r.empresa_id = p_empresa_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Solicitud no encontrada'; END IF;

  SELECT rp.id, rp.rfq_id, rp.provider_id, p.name AS provider_name
    INTO v_rp
  FROM public.rfq_providers rp
  JOIN public.providers p ON p.id = rp.provider_id AND p.empresa_id = p_empresa_id
  WHERE rp.id = p_rfq_provider_id AND rp.rfq_id = p_rfq_id
    AND rp.empresa_id = p_empresa_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Proveedor no encontrado en esta solicitud'; END IF;

  SELECT qv.* INTO v_quote
  FROM public.quote_versions qv
  JOIN public.quotes q ON q.id = qv.quote_id AND q.empresa_id = p_empresa_id
  WHERE qv.id = p_quote_version_id AND qv.empresa_id = p_empresa_id
    AND q.rfq_provider_id = p_rfq_provider_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cotización no encontrada para este proveedor y solicitud'; END IF;
  IF v_quote.version_number <> (
    SELECT max(qv_latest.version_number)
    FROM public.quote_versions qv_latest
    WHERE qv_latest.quote_id = v_quote.quote_id AND qv_latest.empresa_id = p_empresa_id
  ) THEN
    RAISE EXCEPTION 'Solo se puede autorizar la última versión de la cotización';
  END IF;

  IF v_rfq.status = 'AUTORIZADO' THEN
    SELECT ao.id INTO v_order_id
    FROM public.authorized_orders ao
    WHERE ao.rfq_id = p_rfq_id AND ao.empresa_id = p_empresa_id
      AND ao.created_from = 'rfq'
      AND ao.provider_id = v_rp.provider_id
      AND ao.quote_version_id = p_quote_version_id
    ORDER BY ao.created_at DESC
    LIMIT 1;
    IF v_order_id IS NOT NULL AND v_rfq.selected_rfq_provider_id = p_rfq_provider_id THEN
      RETURN v_order_id;
    END IF;
    RAISE EXCEPTION 'La solicitud ya tiene otra oferta autorizada';
  END IF;
  IF v_rfq.status NOT IN ('COTIZANDO','OFERTAS_RECIBIDAS') THEN
    RAISE EXCEPTION 'La solicitud está cerrada o no admite autorización';
  END IF;

  SELECT min(qv_comp.total_price) INTO v_lowest_competing_price
  FROM public.rfq_providers rp_comp
  JOIN public.quotes q_comp ON q_comp.rfq_provider_id = rp_comp.id
    AND q_comp.empresa_id = p_empresa_id
  JOIN public.quote_versions qv_comp ON qv_comp.quote_id = q_comp.id
    AND qv_comp.empresa_id = p_empresa_id
    AND qv_comp.version_number = (
      SELECT max(qv_latest.version_number)
      FROM public.quote_versions qv_latest
      WHERE qv_latest.quote_id = q_comp.id AND qv_latest.empresa_id = p_empresa_id
    )
  WHERE rp_comp.rfq_id = p_rfq_id AND rp_comp.empresa_id = p_empresa_id
    AND rp_comp.id <> p_rfq_provider_id
    AND qv_comp.currency = v_quote.currency;

  v_is_cheapest := v_lowest_competing_price IS NULL
    OR v_quote.total_price <= v_lowest_competing_price;
  IF NOT v_is_cheapest AND p_selection_reason IS NULL THEN
    RAISE EXCEPTION 'La oferta no es la más económica: se requiere motivo de selección';
  END IF;

  INSERT INTO public.authorized_orders (
    empresa_id, rfq_id, provider_id, quote_version_id, created_from,
    provider_name, client_name, product, quantity, unit, unit_price,
    total_price, currency, vat_included, authorized_by, is_cheapest,
    selection_reason, selection_reason_detail, project_id
  ) VALUES (
    p_empresa_id, v_rfq.id, v_rp.provider_id, v_quote.id, 'rfq',
    v_rp.provider_name, v_rfq.client_name, v_rfq.product, v_rfq.quantity, v_rfq.unit,
    v_quote.unit_price, v_quote.total_price, v_quote.currency, v_quote.vat_included,
    p_actor_id, v_is_cheapest,
    CASE WHEN v_is_cheapest THEN NULL ELSE p_selection_reason END,
    CASE WHEN v_is_cheapest THEN NULL ELSE nullif(pg_catalog.btrim(p_selection_reason_detail), '') END,
    v_rfq.project_id
  ) RETURNING id INTO v_order_id;

  UPDATE public.rfqs r
  SET status = 'AUTORIZADO', selected_rfq_provider_id = p_rfq_provider_id,
      updated_at = pg_catalog.now()
  WHERE r.id = p_rfq_id AND r.empresa_id = p_empresa_id
    AND r.status IN ('COTIZANDO','OFERTAS_RECIBIDAS');
  IF NOT FOUND THEN RAISE EXCEPTION 'La solicitud cambió durante la autorización'; END IF;
  RETURN v_order_id;
END;
$function$

