CREATE OR REPLACE FUNCTION public.submit_receipt_portal(p_token_hash text, p_fecha date, p_recibido_por text, p_remision_number text, p_notas text, p_items jsonb, p_evidence jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_link public.receipt_portal_links%ROWTYPE;
  v_order public.authorized_orders%ROWTYPE;
  v_item record;
  v_receipt_id uuid;
  v_producto_id uuid;
  v_product_count integer;
  v_received numeric;
  v_prefix text;
  v_item_count integer;
  v_unique_item_count integer;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Acceso denegado';
  END IF;
  IF p_token_hash IS NULL OR p_token_hash !~ '^[a-f0-9]{64}$'
     OR p_fecha IS NULL
     OR length(btrim(coalesce(p_recibido_por, ''))) NOT BETWEEN 1 AND 120
     OR p_items IS NULL OR jsonb_typeof(p_items) IS DISTINCT FROM 'array'
     OR jsonb_typeof(coalesce(p_evidence, '[]'::jsonb)) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Datos de recepción inválidos';
  END IF;
  IF jsonb_array_length(p_items) NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'La recepción debe incluir entre 1 y 100 líneas';
  END IF;

  SELECT * INTO v_link
  FROM public.receipt_portal_links
  WHERE token_hash = p_token_hash AND active AND expires_at > now()
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Enlace inválido, vencido o ya utilizado'; END IF;

  SELECT * INTO v_order
  FROM public.authorized_orders
  WHERE id = v_link.order_id AND empresa_id = v_link.empresa_id
  FOR UPDATE;
  IF NOT FOUND OR v_order.project_id IS NULL THEN RAISE EXCEPTION 'OC no encontrada'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.inventory_locations
    WHERE id = v_link.location_id AND empresa_id = v_link.empresa_id
      AND project_id = v_order.project_id AND location_type = 'PROJECT' AND active
  ) THEN
    RAISE EXCEPTION 'La ubicación de obra ya no está activa';
  END IF;

  SELECT count(*), count(DISTINCT x.order_item_id)
  INTO v_item_count, v_unique_item_count
  FROM jsonb_to_recordset(p_items) AS x(order_item_id uuid, quantity numeric, notes text);
  IF v_item_count <> v_unique_item_count THEN
    RAISE EXCEPTION 'No se puede repetir una línea de la OC';
  END IF;

  INSERT INTO public.oc_recepciones (
    empresa_id, order_id, fecha, recibido_por, notas, delivery_location_id,
    remision_number, idempotency_key, status, created_by
  ) VALUES (
    v_link.empresa_id, v_order.id, p_fecha, btrim(p_recibido_por),
    nullif(btrim(p_notas), ''), v_link.location_id,
    nullif(btrim(p_remision_number), ''), 'receipt-portal:' || v_link.id::text,
    'DRAFT', NULL
  ) RETURNING id INTO v_receipt_id;

  FOR v_item IN
    SELECT * FROM jsonb_to_recordset(p_items)
      AS x(order_item_id uuid, quantity numeric, notes text)
  LOOP
    IF v_item.order_item_id IS NULL OR v_item.quantity IS NULL OR v_item.quantity <= 0 THEN
      RAISE EXCEPTION 'Cantidad o línea de recepción inválida';
    END IF;

    PERFORM 1 FROM public.authorized_order_items
    WHERE id = v_item.order_item_id AND order_id = v_order.id AND empresa_id = v_link.empresa_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'La línea no pertenece a la OC'; END IF;

    SELECT oi.quantity - coalesce(sum(
      CASE WHEN r.id IS NOT NULL THEN ri.cantidad_recibida ELSE 0 END
    ), 0)
    INTO v_received
    FROM public.authorized_order_items oi
    LEFT JOIN public.oc_recepcion_items ri ON ri.order_item_id = oi.id AND ri.empresa_id = v_link.empresa_id
    LEFT JOIN public.oc_recepciones r ON r.id = ri.recepcion_id
      AND r.order_id = v_order.id AND r.empresa_id = v_link.empresa_id
      AND r.status IN ('DRAFT', 'CONFIRMED')
    WHERE oi.id = v_item.order_item_id AND oi.order_id = v_order.id AND oi.empresa_id = v_link.empresa_id
    GROUP BY oi.quantity;
    IF v_received IS NULL OR v_item.quantity > v_received THEN
      RAISE EXCEPTION 'La cantidad supera lo pendiente de la OC';
    END IF;

    SELECT count(*), (array_agg(p.id))[1]
    INTO v_product_count, v_producto_id
    FROM public.productos p
    JOIN public.authorized_order_items oi ON oi.id = v_item.order_item_id
    WHERE p.empresa_id = v_link.empresa_id AND p.activo
      AND lower(btrim(p.nombre)) = lower(btrim(oi.product))
      AND lower(btrim(coalesce(p.unidad, ''))) = lower(btrim(coalesce(oi.unit, '')));
    IF v_product_count <> 1 THEN v_producto_id := NULL; END IF;

    INSERT INTO public.oc_recepcion_items (
      empresa_id, recepcion_id, order_item_id, producto_id, cantidad_recibida, notas
    ) VALUES (
      v_link.empresa_id, v_receipt_id, v_item.order_item_id, v_producto_id,
      v_item.quantity, nullif(btrim(v_item.notes), '')
    );
  END LOOP;

  v_prefix := 'receipt-portals/' || v_link.id::text || '/';
  FOR v_item IN
    SELECT * FROM jsonb_to_recordset(coalesce(p_evidence, '[]'::jsonb)) AS x(
      storage_bucket text, storage_path text, file_name text,
      mime_type text, size_bytes bigint, sha256 text
    )
  LOOP
    IF v_item.storage_bucket <> 'warehouse-evidence'
       OR left(v_item.storage_path, length(v_prefix)) <> v_prefix
       OR v_item.size_bytes <= 0 THEN
      RAISE EXCEPTION 'Evidencia de recepción inválida';
    END IF;
    INSERT INTO public.inventory_receipt_evidence (
      empresa_id, receipt_id, storage_bucket, storage_path, file_name,
      mime_type, size_bytes, sha256, uploaded_by
    ) VALUES (
      v_link.empresa_id, v_receipt_id, v_item.storage_bucket, v_item.storage_path,
      v_item.file_name, v_item.mime_type, v_item.size_bytes, v_item.sha256, NULL
    );
  END LOOP;

  UPDATE public.receipt_portal_links
  SET active = false, last_used_at = now()
  WHERE id = v_link.id;
  RETURN v_receipt_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_sandbox_bid(p_room_id uuid, p_participant_id uuid, p_price_pyg bigint, p_idempotency_key text DEFAULT NULL::text, p_expected_policy_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_room        public.auction_sandbox_rooms%rowtype;
  v_now         timestamptz := clock_timestamp();
  v_best        bigint;
  v_own_last    bigint;
  v_seq         bigint;
  v_bid_id      uuid;
  v_effective   text;
begin
  -- Idempotencia DESPUÉS del lock (dos submits concurrentes con la misma
  -- key se serializan: el segundo ve la fila del primero, sin excepción).
  if p_idempotency_key is not null then
    select id, server_sequence into v_bid_id, v_seq
    from public.auction_sandbox_bids
    where idempotency_key = p_idempotency_key;
    if found then
      return jsonb_build_object(
        'accepted', true, 'duplicate', true,
        'bid_id', v_bid_id, 'sequence', v_seq);
    end if;
  end if;

  select * into v_room
  from public.auction_sandbox_rooms
  where id = p_room_id
  for update;

  if not found then
    return jsonb_build_object(
      'accepted', false, 'rejection_code', 'UNKNOWN_ROOM',
      'rejection_message', 'Sala inexistente.');
  end if;

  -- Re-chequear idempotencia bajo lock (serializa duplicados concurrentes).
  if p_idempotency_key is not null then
    select id, server_sequence into v_bid_id, v_seq
    from public.auction_sandbox_bids
    where idempotency_key = p_idempotency_key;
    if found then
      return jsonb_build_object(
        'accepted', true, 'duplicate', true,
        'bid_id', v_bid_id, 'sequence', v_seq);
    end if;
  end if;

  -- Policy binding (0070): the caller passes the version its candidate was
  -- authorized under. A newer persisted version aborts — the candidate was
  -- computed off a superseded policy and could breach the CURRENT autoLimit
  -- (which this RPC does not enforce). NULL skips (human path).
  if p_expected_policy_version is not null
     and exists (select 1
                 from public.auction_sandbox_policy_versions
                 where room_id = p_room_id
                   and version > p_expected_policy_version) then
    return jsonb_build_object(
      'accepted', false, 'rejection_code', 'POLICY_SUPERSEDED',
      'rejection_message', 'La policy cambió durante el envío. Reintentá con la versión actual.');
  end if;

  -- Fase efectiva por RELOJ DEL SERVIDOR (nunca client timestamp).
  v_effective := v_room.status;
  if v_room.status = 'ACTIVE_NORMAL' and v_room.started_at is not null
     and v_now >= v_room.started_at + (v_room.normal_duration_seconds || ' seconds')::interval then
    v_effective := 'ACTIVE_RANDOM';
  end if;
  if v_effective = 'ACTIVE_RANDOM' then
    declare v_close timestamptz;
    begin
      select random_close_at into v_close
      from public.auction_sandbox_room_private where room_id = p_room_id;
      if v_close is not null and v_now >= v_close then
        v_effective := 'CLOSED';
      end if;
    end;
  end if;

  if v_effective <> 'ACTIVE_NORMAL' and v_effective <> 'ACTIVE_RANDOM' then
    return jsonb_build_object(
      'accepted', false, 'rejection_code', 'ROOM_NOT_ACTIVE',
      'rejection_message', 'La subasta no está activa.');
  end if;

  if not exists (select 1 from public.auction_sandbox_participants
                 where id = p_participant_id and room_id = p_room_id) then
    return jsonb_build_object(
      'accepted', false, 'rejection_code', 'UNKNOWN_PARTICIPANT',
      'rejection_message', 'Participante desconocido en esta sala.');
  end if;

  if p_price_pyg is null or p_price_pyg <= 0 then
    return jsonb_build_object(
      'accepted', false, 'rejection_code', 'INVALID_PRICE',
      'rejection_message', 'El precio debe ser un entero positivo en guaraníes.');
  end if;

  select min(price_pyg) into v_own_last
  from public.auction_sandbox_bids
  where room_id = p_room_id and participant_id = p_participant_id and accepted;

  if v_own_last is not null and p_price_pyg >= v_own_last then
    return jsonb_build_object(
      'accepted', false, 'rejection_code', 'NOT_DECREASING',
      'rejection_message', 'La nueva oferta debe ser menor a tu última oferta.');
  end if;

  select min(price_pyg) into v_best
  from public.auction_sandbox_bids
  where room_id = p_room_id and accepted;

  if v_best is null then
    if p_price_pyg >= v_room.opening_price_pyg then
      return jsonb_build_object(
        'accepted', false, 'rejection_code', 'NOT_BELOW_OPENING',
        'rejection_message', 'La primera oferta debe ser menor al precio de apertura.');
    end if;
  elsif v_best - p_price_pyg < v_room.minimum_decrement_pyg then
    return jsonb_build_object(
      'accepted', false, 'rejection_code', 'BELOW_MINIMUM_DECREMENT',
      'rejection_message', 'No alcanza la mejora mínima sobre el mejor precio.');
  end if;

  v_seq := v_room.next_sequence;
  update public.auction_sandbox_rooms
  set next_sequence = next_sequence + 1
  where id = p_room_id;

  insert into public.auction_sandbox_bids
    (room_id, participant_id, price_pyg, server_sequence, server_received_at,
     idempotency_key, accepted)
  values
    (p_room_id, p_participant_id, p_price_pyg, v_seq, v_now,
     p_idempotency_key, true)
  returning id into v_bid_id;

  -- Evento hermanado con la MISMA secuencia (un solo bump por oferta).
  insert into public.auction_sandbox_events (room_id, type, payload, server_sequence)
  values (p_room_id, 'BID_ACCEPTED',
          jsonb_build_object('bid_id', v_bid_id, 'participant_id', p_participant_id,
                             'price_pyg', p_price_pyg, 'sequence', v_seq),
          v_seq);

  return jsonb_build_object(
    'accepted', true, 'duplicate', false,
    'bid_id', v_bid_id, 'sequence', v_seq);
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_recompute_on_invoice_total_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.total is distinct from old.total then
    perform public.recompute_invoice_status(new.id);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_recompute_on_match_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if (tg_op = 'DELETE') then
    perform public.recompute_invoice_status(old.invoice_id);
    perform public.recompute_order_facturado(old.authorized_order_id);
    return old;
  else
    perform public.recompute_invoice_status(new.invoice_id);
    perform public.recompute_order_facturado(new.authorized_order_id);
    return new;
  end if;
end;
$function$

